const MAX_PROJECTED_LOOP_GRAPH_WORK_V1: usize =
    MAX_RANKED_BOUNDS_BLOCKS * (MAX_RANKED_BOUNDS_BLOCKS + MAX_RANKED_BOUNDS_EDGES);
