fn local_provenance_with_scalar_inventory_v1(
    callables: &[SemanticCallableDeclV1],
    types: &[fe2o3_mir_model::semantic_mir_v1::SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    definitions: &[u8],
    address_escaped: &[bool],
) -> Result<LocalProvenanceV1, ProductionRankedProjectionErrorV1> {
    local_provenance_with_scalar_inventory_core_v18(callables, types, function,
        definitions, address_escaped,
        &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy)
}

fn local_provenance_with_scalar_inventory_core_v18(
    callables: &[SemanticCallableDeclV1],
    types: &[fe2o3_mir_model::semantic_mir_v1::SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    definitions: &[u8],
    address_escaped: &[bool],
    allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<LocalProvenanceV1, ProductionRankedProjectionErrorV1> {
    let local_count = function.locals().len();
    if definitions.len() != local_count || address_escaped.len() != local_count {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "local provenance scalar custody tables do not match the semantic local table",
        ));
    }
    allocation.header::<LocalProvenanceV1>()?;
    allocation.header::<Result<LocalProvenanceV1, ProductionRankedProjectionErrorV1>>()?;
    let exclusive_owner_origins = exclusive_owner_carrier_v1::exclusive_owner_value_origins_core_v18(
        callables,
        function,
        definitions,
        allocation,
    )?;
    let mut stable_argument_origins = allocation.filled(local_count, None)?;
    let mut allocation_origins = allocation.filled(local_count, None)?;
    let mut allocation_provenance = allocation.filled(local_count, None)?;
    let mut stable_edges = allocation.nested(local_count)?;
    let mut allocation_edges = allocation.nested(local_count)?;
    let mut allocation_contract_edges = allocation.nested(local_count)?;
    for (local_index, local) in function.locals().iter().enumerate() {
        allocation.charge(1)?;
        if let SemanticLocalRoleV1::Argument(argument) = local.role() {
            if definitions[local_index] == 0 && !address_escaped[local_index] {
                stable_argument_origins[local_index] = Some(argument);
            }
            allocation_origins[local_index] = Some(argument);
            allocation_provenance[local_index] =
                Some(LocalAllocationProvenanceV1::Argument(argument));
        }
    }
    let mut edge_count = 0_usize;
    for block in function.blocks() {
        allocation.charge(1)?;
        for statement in block.statements() {
            allocation.charge(1)?;
            let SemanticStatementKindV1::Assign(assignment) = statement.kind() else {
                continue;
            };
            let destination = assignment.destination();
            if !destination.projections().is_empty()
                || definitions
                    .get(destination.local().index() as usize)
                    .copied()
                    != Some(1)
            {
                continue;
            }
            let destination = destination.local().index() as usize;
            let stable_source = match assignment.value().kind() {
                SemanticRvalueKindV1::Use(operand) | SemanticRvalueKindV1::Cast { operand, .. } => {
                    simple_operand_local(operand)
                }
                _ => None,
            };
            if let Some(source) = stable_source {
                let source = source.index() as usize;
                if address_escaped.get(source).copied() == Some(false)
                    && !address_escaped[destination]
                {
                    push_local_provenance_edge_core_v18(
                        &mut stable_edges,
                        source,
                        destination,
                        &mut edge_count,
                        allocation,
                    )?;
                }
            };

            let allocation_source = match assignment.value().kind() {
                SemanticRvalueKindV1::Use(operand) => {
                    allocation_operand_local_v1(types, function, operand)
                }
                SemanticRvalueKindV1::Cast {
                    kind: SemanticCastKindV1::Pointer,
                    operand,
                } => simple_operand_local(operand),
                SemanticRvalueKindV1::Borrow { place, .. } => {
                    allocation.charge(place.projections().len())?;
                    borrowed_allocation_local_v1(function, place, &exclusive_owner_origins)
                }
                SemanticRvalueKindV1::AddressOf { place, .. } => {
                    allocation.charge(place.projections().len())?;
                    reborrowed_allocation_local_v1(place)
                }
                _ => None,
            };
            if let Some(source) = allocation_source {
                push_local_provenance_edge_core_v18(
                    &mut allocation_edges,
                    source.index() as usize,
                    destination,
                    &mut edge_count,
                    allocation,
                )?;
                push_local_provenance_edge_core_v18(
                    &mut allocation_contract_edges,
                    source.index() as usize,
                    destination,
                    &mut edge_count,
                    allocation,
                )?;
            } else if let SemanticRvalueKindV1::Borrow { place, .. }
            | SemanticRvalueKindV1::AddressOf { place, .. } = assignment.value().kind()
                && place.projections().is_empty()
                && function
                    .locals()
                    .get(place.local().index() as usize)
                    .is_some_and(|local| !matches!(local.role(), SemanticLocalRoleV1::Argument(_)))
            {
                let origin = LocalAllocationProvenanceV1::Private(place.local());
                match allocation_provenance.get_mut(destination) {
                    Some(slot @ None) => *slot = Some(origin),
                    Some(Some(existing)) if *existing == origin => {}
                    Some(Some(_)) => {
                        return Err(ProductionRankedProjectionErrorV1::Incomplete(
                            "a local may alias multiple kernel allocation origins",
                        ));
                    }
                    None => {
                        return Err(ProductionRankedProjectionErrorV1::Unsupported(
                            "a private allocation root is outside the semantic local table",
                        ));
                    }
                }
            }

            if let SemanticRvalueKindV1::Binary {
                operation: SemanticBinaryOpV1::Offset,
                left,
                ..
            } = assignment.value().kind()
                && let Some(source) = allocation_operand_local_v1(types, function, left)
            {
                // Pointer offsets retain only an authenticated external allocation
                // contract. Private roots have no size/range contract and must not
                // gain address-formation authority through raw pointer arithmetic.
                push_local_provenance_edge_core_v18(
                    &mut allocation_contract_edges,
                    source.index() as usize,
                    destination,
                    &mut edge_count,
                    allocation,
                )?;
            }
        }
    }

    propagate_exact_local_origins_core_v18(
        &mut stable_argument_origins,
        &stable_edges,
        "a runtime index may derive from multiple kernel arguments",
        allocation,
    )?;
    propagate_exact_local_origins_core_v18(
        &mut allocation_provenance,
        &allocation_edges,
        "a local may alias multiple kernel allocation origins",
        allocation,
    )?;
    propagate_exact_local_origins_core_v18(
        &mut allocation_origins,
        &allocation_contract_edges,
        "a local may alias multiple kernel allocation origins",
        allocation,
    )?;
    Ok(LocalProvenanceV1 {
        stable_argument_origins,
        allocation_origins,
        allocation_provenance,
    })
}

fn push_local_provenance_edge_v1(
    edges: &mut [Vec<usize>],
    source: usize,
    destination: usize,
    edge_count: &mut usize,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    push_local_provenance_edge_core_v18(edges, source, destination, edge_count,
        &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy)
}

fn push_local_provenance_edge_core_v18(
    edges: &mut [Vec<usize>], source: usize, destination: usize, edge_count: &mut usize,
    allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    if source >= edges.len() || destination >= edges.len() {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "a local provenance edge is outside the semantic local table",
        ));
    }
    *edge_count =
        edge_count
            .checked_add(1)
            .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                "local provenance edge accounting overflowed",
            ))?;
    if *edge_count > MAX_PROJECTED_CAPABILITY_DATAFLOW_WORK_V1 {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "local provenance edges exceed the charged projection limit",
        ));
    }
    allocation.reserve(&mut edges[source], 1, false,
        "local provenance edge storage cannot be reserved")?;
    allocation.push(&mut edges[source], destination)
}

fn propagate_exact_local_origins_v1<T: Copy + Eq>(
    origins: &mut [Option<T>],
    edges: &[Vec<usize>],
    conflict: &'static str,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    propagate_exact_local_origins_core_v18(origins, edges, conflict,
        &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy)
}

fn propagate_exact_local_origins_core_v18<T: Copy + Eq>(
    origins: &mut [Option<T>], edges: &[Vec<usize>], conflict: &'static str,
    allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    if origins.len() != edges.len() {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "local provenance tables have inconsistent lengths",
        ));
    }
    allocation.header::<Result<(), ProductionRankedProjectionErrorV1>>()?;
    let mut worklist = allocation.queue(origins.len(),
        "local provenance dataflow worklist cannot be reserved")?;
    for (local, origin) in origins.iter().enumerate() {
        allocation.charge(1)?;
        if origin.is_some() {
            allocation.charge(1)?;
            worklist.push_back(local);
        }
    }
    let mut work = 0_usize;
    while let Some(source) = worklist.pop_front() {
        allocation.charge(1)?;
        let Some(origin) = origins[source] else {
            continue;
        };
        for &destination in &edges[source] {
            allocation.charge(1)?;
            work = work
                .checked_add(1)
                .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                    "local provenance dataflow work accounting overflowed",
                ))?;
            if work > MAX_PROJECTED_CAPABILITY_DATAFLOW_WORK_V1 {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "local provenance dataflow exceeds the charged projection limit",
                ));
            }
            match origins[destination] {
                None => {
                    allocation.charge(1)?;
                    origins[destination] = Some(origin);
                    worklist.push_back(destination);
                }
                Some(existing) if existing == origin => {}
                Some(_) => {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(conflict));
                }
            }
        }
    }
    Ok(())
}

fn reborrowed_allocation_local_v1(place: &SemanticPlaceV1) -> Option<SemanticLocalIdV1> {
    let mut projections = place.projections().iter();
    matches!(
        projections.next().map(|projection| projection.kind()),
        Some(SemanticProjectionKindV1::Dereference)
    )
    .then(|| {
        projections
            .all(|projection| {
                matches!(
                    projection.kind(),
                    SemanticProjectionKindV1::Field(_)
                        | SemanticProjectionKindV1::Downcast(_)
                        | SemanticProjectionKindV1::OpaqueCast
                        | SemanticProjectionKindV1::Subtype
                )
            })
            .then_some(place.local())
    })
    .flatten()
}

fn borrowed_allocation_local_v1(
    function: &SemanticFunctionDeclV1,
    place: &SemanticPlaceV1,
    exclusive_owner_origins: &[Option<u32>],
) -> Option<SemanticLocalIdV1> {
    if let Some(local) = reborrowed_allocation_local_v1(place) {
        return Some(local);
    }
    if !place.projections().is_empty() {
        return None;
    }
    let local = function.locals().get(place.local().index() as usize)?;
    if let SemanticLocalRoleV1::Argument(argument) = local.role() {
        return matches!(
            function
                .abi()
                .source_argument_ownership()
                .get(argument as usize),
            Some(SemanticSourceArgumentOwnershipV1::ExclusiveOwner)
        )
        .then_some(place.local());
    }
    exclusive_owner_origins
        .get(place.local().index() as usize)
        .copied()
        .flatten()
        .map(|_| place.local())
}

#[cfg(test)]
fn local_stable_argument_origins(
    types: &[fe2o3_mir_model::semantic_mir_v1::SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
) -> Result<Vec<Option<u32>>, ProductionRankedProjectionErrorV1> {
    Ok(local_provenance_v1(types, function)?.stable_argument_origins)
}

fn local_allocation_contracts(
    types: &[fe2o3_mir_model::semantic_mir_v1::SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    origins: &[Option<u32>],
) -> Result<Vec<Option<AllocationContractV1>>, ProductionRankedProjectionErrorV1> {
    local_allocation_contracts_core_v18(types, function, origins,
        &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy)
}

fn local_allocation_contracts_core_v18(
    types: &[fe2o3_mir_model::semantic_mir_v1::SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1, origins: &[Option<u32>],
    allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<Vec<Option<AllocationContractV1>>, ProductionRankedProjectionErrorV1> {
    if origins.len() != function.locals().len() {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "allocation-origin and semantic-local tables have different lengths",
        ));
    }
    let source_types = function.abi().source_input_types();
    let source_ownership = function.abi().source_argument_ownership();
    let abi_arguments = function.abi().adjusted_arguments();
    if source_ownership.len() != source_types.len() {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "source ownership and semantic argument tables have different lengths",
        ));
    }
    allocation.header::<Result<Vec<Option<AllocationContractV1>>, ProductionRankedProjectionErrorV1>>()?;
    let mut arguments = allocation.filled(source_types.len(), None)?;
    for (argument_index, &ty) in source_types.iter().enumerate() {
        allocation.charge(1)?;
        let type_decl = types.get(ty.index() as usize).ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "a kernel argument type is outside the semantic type table",
            ),
        )?;
        let abi_argument = abi_arguments.get(argument_index).ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "a kernel source argument is missing its authenticated FnAbi record",
            ),
        )?;
        let pointee = abi_argument
            .value()
            .pointee_override()
            .or(type_decl.abi_properties().first_pointee());
        let allocation_origin = u64::try_from(argument_index)
            .ok()
            .and_then(|index| index.checked_add(1))
            .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                "a kernel argument index does not fit the allocation identity space",
            ))?;
        let first_pointer_noalias = match abi_argument.mode() {
            SemanticAbiPassModeV1::Direct(attributes) => attributes.regular().no_alias(),
            SemanticAbiPassModeV1::Pair { first, .. } => first.regular().no_alias(),
            SemanticAbiPassModeV1::Ignore
            | SemanticAbiPassModeV1::Cast { .. }
            | SemanticAbiPassModeV1::Indirect { .. } => false,
        };
        let Some(pointee) = pointee else {
            continue;
        };
        let abi_contract = allocation_contract_from_pointee(
            pointee.kind(),
            first_pointer_noalias,
            allocation_origin,
        );
        let singleton_object = matches!(
            source_ownership[argument_index],
            SemanticSourceArgumentOwnershipV1::ExclusiveOwner
        ) && matches!(type_decl.layout().backend_repr(), SemanticBackendReprV1::Scalar(scalar) if matches!(scalar.primitive(), SemanticBackendPrimitiveV1::Pointer { .. }));
        arguments[argument_index] = Some(authenticated_source_allocation_contract_v1(
            source_ownership[argument_index],
            pointee.kind(),
            AllocationContractV1 {
                singleton_object,
                ..abi_contract
            },
        )?);
    }
    if matches!(allocation, source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy) {
        return Ok(origins.iter().map(|origin|
            origin.and_then(|origin| arguments.get(origin as usize).copied().flatten())).collect());
    }
    let mut result = allocation.capacity(origins.len())?;
    for origin in origins {
        allocation.charge(1)?;
        allocation.push(&mut result,
            origin.and_then(|origin| arguments.get(origin as usize).copied().flatten()))?;
    }
    Ok(result)
}

fn volatile_load_frozen_shared_scalar_source_v1(
    types: &[SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    stable_argument_origins: &[Option<u32>],
    receiver: usize,
    element: SemanticTypeIdV1,
) -> bool {
    let Some(argument) = stable_argument_origins
        .get(receiver)
        .copied()
        .flatten()
        .and_then(|argument| usize::try_from(argument).ok())
    else {
        return false;
    };
    let Some(&ownership) = function.abi().source_argument_ownership().get(argument) else {
        return false;
    };
    let Some(&source_type) = function.abi().source_input_types().get(argument) else {
        return false;
    };
    let Some(source_declaration) = types.get(source_type.index() as usize) else {
        return false;
    };
    let Some(abi_argument) = function.abi().adjusted_arguments().get(argument) else {
        return false;
    };
    let Some(pointee) = abi_argument
        .value()
        .pointee_override()
        .or(source_declaration.abi_properties().first_pointee())
    else {
        return false;
    };
    volatile_load_frozen_shared_scalar_type_v1(
        types,
        source_type,
        ownership,
        pointee.kind(),
        element,
    )
}

fn volatile_load_frozen_shared_scalar_type_v1(
    types: &[SemanticTypeDeclV1],
    source_type: SemanticTypeIdV1,
    ownership: SemanticSourceArgumentOwnershipV1,
    pointee_kind: SemanticAbiPointeeKindV1,
    element: SemanticTypeIdV1,
) -> bool {
    if ownership != SemanticSourceArgumentOwnershipV1::SharedBorrow
        || !matches!(
            pointee_kind,
            SemanticAbiPointeeKindV1::SharedReference { .. }
        )
    {
        return false;
    }
    let Some(source_declaration) = types.get(source_type.index() as usize) else {
        return false;
    };
    let SemanticTypeShapeV1::Pointer(pointer) = source_declaration.shape() else {
        return false;
    };
    if pointer.kind() != SemanticPointerKindV1::Reference
        || pointer.mutability() != SemanticMutabilityV1::Immutable
        || pointer.address_space() != 0
        || pointer.pointer_width_bits() != 64
        || pointer.metadata() != SemanticPointerMetadataV1::SliceLength
    {
        return false;
    }
    let Some(SemanticTypeShapeV1::Slice {
        element: slice_element,
    }) = types
        .get(pointer.pointee().index() as usize)
        .map(SemanticTypeDeclV1::shape)
    else {
        return false;
    };
    *slice_element == element
        && matches!(
            types
                .get(element.index() as usize)
                .map(SemanticTypeDeclV1::shape),
            Some(SemanticTypeShapeV1::Scalar(SemanticScalarTypeV1::Bool))
                | Some(SemanticTypeShapeV1::Scalar(SemanticScalarTypeV1::Integer {
                    bits: 8 | 16 | 32 | 64,
                    ..
                }))
                | Some(SemanticTypeShapeV1::Scalar(SemanticScalarTypeV1::Float {
                    bits: 32 | 64
                }))
        )
}

fn authenticated_source_allocation_contract_v1(
    ownership: SemanticSourceArgumentOwnershipV1,
    pointee: SemanticAbiPointeeKindV1,
    abi_contract: AllocationContractV1,
) -> Result<AllocationContractV1, ProductionRankedProjectionErrorV1> {
    // rustc may omit noalias at opt-level=0 or for pinned mutable pointees.
    // Authenticate reference provenance without strengthening the ABI contract.
    Ok(match ownership {
        SemanticSourceArgumentOwnershipV1::UniqueBorrow
            if matches!(
                    pointee,
                    SemanticAbiPointeeKindV1::MutableReference { .. }
                        | SemanticAbiPointeeKindV1::Box { .. }
                ) =>
        {
            abi_contract
        }
        SemanticSourceArgumentOwnershipV1::ExclusiveOwner
            if matches!(pointee, SemanticAbiPointeeKindV1::Raw) =>
        {
            AllocationContractV1 {
                allocation_origin: abi_contract.allocation_origin,
                noalias_class: abi_contract.allocation_origin + 1,
                writable: true,
                singleton_object: abi_contract.singleton_object,
            }
        }
        SemanticSourceArgumentOwnershipV1::SharedBorrow
            if matches!(pointee, SemanticAbiPointeeKindV1::SharedReference { .. }) =>
        {
            abi_contract
        }
        SemanticSourceArgumentOwnershipV1::RawPointer
            if matches!(pointee, SemanticAbiPointeeKindV1::Raw) =>
        {
            abi_contract
        }
        SemanticSourceArgumentOwnershipV1::ByValue if abi_contract.noalias_class == 0 => {
            abi_contract
        }
        SemanticSourceArgumentOwnershipV1::UniqueBorrow
        | SemanticSourceArgumentOwnershipV1::ExclusiveOwner
        | SemanticSourceArgumentOwnershipV1::SharedBorrow
        | SemanticSourceArgumentOwnershipV1::RawPointer
        | SemanticSourceArgumentOwnershipV1::ByValue
        | SemanticSourceArgumentOwnershipV1::Unspecified => {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "source ownership disagrees with rustc ABI pointer provenance",
            ));
        }
    })
}

fn allocation_contract_from_pointee(
    pointee: SemanticAbiPointeeKindV1,
    first_pointer_noalias: bool,
    allocation_origin: u64,
) -> AllocationContractV1 {
    let (noalias_class, writable) = match pointee {
        SemanticAbiPointeeKindV1::SharedReference { frozen } => (1, !frozen),
        SemanticAbiPointeeKindV1::MutableReference { .. }
        | SemanticAbiPointeeKindV1::Box { .. }
            if first_pointer_noalias =>
        {
            (allocation_origin + 1, true)
        }
        SemanticAbiPointeeKindV1::MutableReference { .. }
        | SemanticAbiPointeeKindV1::Box { .. }
        | SemanticAbiPointeeKindV1::Raw => (0, true),
    };
    AllocationContractV1 {
        allocation_origin,
        noalias_class,
        writable,
        singleton_object: false,
    }
}

fn projected_disjoint_operand_v1(
    call: &SemanticDirectCallV1,
    argument: usize,
    values: &[Option<ProjectedDisjointIndexV1>],
    option_dominance: &SemanticOptionDominanceV1,
    enum_payload_dominance: &SemanticEnumPayloadDominanceV1,
    use_block: usize,
) -> Result<ProjectedDisjointIndexV1, ProductionRankedProjectionErrorV1> {
    let local = call
        .arguments()
        .get(argument)
        .and_then(simple_operand_local)
        .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
            "a checked disjoint access whose index witness is not one exact local",
        ))?;
    let projected = values
        .get(local.index() as usize)
        .copied()
        .flatten()
        .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
            "a checked disjoint access not bound to authenticated index authority",
        ))?;
    if !projected.availability.is_none_or(|availability| {
        capability_availability_allows(
            option_dominance,
            enum_payload_dominance,
            availability,
            SemanticBlockIdV1::from_index(use_block as u32),
        )
    }) {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "an index capability is used outside its authenticated Some edge",
        ));
    }
    Ok(projected)
}

fn push_projected_index_constant_v1(
    value: u64,
    operations: &mut Vec<ProductionRankedOperationV1>,
    next_value: &mut u32,
    ranked_ir: &mut String,
) -> Result<ProductionRankedValueV1, ProductionRankedProjectionErrorV1> {
    reserve_operation(operations)?;
    let result = next_value_id(next_value)?;
    operations.push(ProductionRankedOperationV1::IndexConstant { result, value });
    push_ranked_ir(
        ranked_ir,
        &format!("  %{} = kernel.index_constant {value}\n", result.get()),
    )?;
    Ok(ProductionRankedValueV1::Local(result))
}

fn push_projected_index_binary_v1(
    kind: IndexBinaryKindAttr,
    lhs: ProductionRankedValueV1,
    rhs: ProductionRankedValueV1,
    operations: &mut Vec<ProductionRankedOperationV1>,
    next_value: &mut u32,
    ranked_ir: &mut String,
) -> Result<ProductionRankedValueV1, ProductionRankedProjectionErrorV1> {
    reserve_operation(operations)?;
    let result = next_value_id(next_value)?;
    operations.push(ProductionRankedOperationV1::IndexBinary {
        result,
        kind,
        lhs,
        rhs,
    });
    push_ranked_ir(
        ranked_ir,
        &format!(
            "  %{} = kernel.index_binary {kind:?} {}, {}\n",
            result.get(),
            ranked_value_text_v1(lhs),
            ranked_value_text_v1(rhs),
        ),
    )?;
    Ok(ProductionRankedValueV1::Local(result))
}

#[allow(clippy::too_many_arguments)]
fn project_disjoint_block_component_indices_v1(
    callables: &[SemanticCallableDeclV1],
    function: &SemanticFunctionDeclV1,
    linear_launch_upper_bound: Option<u64>,
    constants: &[Option<u64>],
    index_values: &[Option<ProjectedDisjointIndexV1>],
    local_definitions: &[u8],
    address_escaped: &[bool],
    enum_payload_loads: &[PendingEnumPayloadLoadV1],
    option_dominance: &SemanticOptionDominanceV1,
    enum_payload_dominance: &SemanticEnumPayloadDominanceV1,
    option_predicates: &mut [Option<GuardPredicateV1>],
    operations: &mut Vec<ProductionRankedOperationV1>,
    next_value: &mut u32,
    ranked_ir: &mut String,
) -> Result<Vec<Option<ProjectedOrdinaryIndexV1>>, ProductionRankedProjectionErrorV1> {
    let local_count = function.locals().len();
    if index_values.len() != local_count
        || local_definitions.len() != local_count
        || address_escaped.len() != local_count
        || option_predicates.len() != local_count
    {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "component-index projection inventories do not match the semantic local table",
        ));
    }
    let mut option_payload_values = vec![None; local_count];
    for (block_index, block) in function.blocks().iter().enumerate() {
        let SemanticTerminatorKindV1::Call(call) = block.terminator().kind() else {
            continue;
        };
        let Some(SemanticCallableDeclV1::CompilerIntrinsic {
            operation:
                SemanticCompilerIntrinsicOperationV1::DisjointBlockComponentIndex {
                    index_space,
                    lanes_per_block,
                    elements_per_lane,
                    ..
                },
            ..
        }) = callables.get(call.callee().index() as usize)
        else {
            continue;
        };
        let expected = SemanticDisjointIndexSpaceV1::BlockedIndex1d {
            lanes_per_block: *lanes_per_block,
            elements_per_lane: *elements_per_lane,
        };
        if *index_space != expected
            || !blocked_mapping_fits_launch_v1(
                linear_launch_upper_bound,
                *lanes_per_block,
                *elements_per_lane,
            )
        {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "component-index blocked geometry is malformed or exceeds the authenticated launch",
            ));
        }
        let destination = simple_call_destination(call)?.index() as usize;
        if local_definitions.get(destination).copied() != Some(1)
            || address_escaped.get(destination).copied() != Some(false)
        {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a component-index Option result lacks one stable local destination",
            ));
        }
        if option_payload_values[destination].is_some() {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "multiple component-index payloads target one semantic local",
            ));
        }
        let block_index_value = projected_disjoint_operand_v1(
            call,
            0,
            index_values,
            option_dominance,
            enum_payload_dominance,
            block_index,
        )?;
        if block_index_value.mapping != expected {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "component-index receiver mapping identity changed",
            ));
        }
        let component = if let Some(component) = call
            .arguments()
            .get(1)
            .and_then(|operand| constant_operand_value(operand, constants))
        {
            push_projected_index_constant_v1(component, operations, next_value, ranked_ir)?
        } else {
            let component_local = call
                .arguments()
                .get(1)
                .and_then(simple_operand_local)
                .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                    "a component-index operand is not one exact scalar local or constant",
                ))?;
            let component = index_values
                .get(component_local.index() as usize)
                .copied()
                .flatten()
                .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                    "a component-index scalar lacks exact ranked value provenance",
                ))?;
            if !component.availability.is_none_or(|availability| {
                capability_availability_allows(
                    option_dominance,
                    enum_payload_dominance,
                    availability,
                    SemanticBlockIdV1::from_index(block_index as u32),
                )
            }) {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "a component-index scalar is used outside its authenticated source region",
                ));
            }
            component.value
        };
        let lanes =
            push_projected_index_constant_v1(*lanes_per_block, operations, next_value, ranked_ir)?;
        let elements = push_projected_index_constant_v1(
            *elements_per_lane,
            operations,
            next_value,
            ranked_ir,
        )?;
        let block_elements = lanes_per_block.checked_mul(*elements_per_lane).ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "component-index blocked dimensions overflow u64",
            ),
        )?;
        let block_elements =
            push_projected_index_constant_v1(block_elements, operations, next_value, ranked_ir)?;
        let block_number = push_projected_index_binary_v1(
            IndexBinaryKindAttr::Divide,
            block_index_value.value,
            lanes,
            operations,
            next_value,
            ranked_ir,
        )?;
        let lane = push_projected_index_binary_v1(
            IndexBinaryKindAttr::Remainder,
            block_index_value.value,
            lanes,
            operations,
            next_value,
            ranked_ir,
        )?;
        let block_base = push_projected_index_binary_v1(
            IndexBinaryKindAttr::Multiply,
            block_number,
            block_elements,
            operations,
            next_value,
            ranked_ir,
        )?;
        let component_base = push_projected_index_binary_v1(
            IndexBinaryKindAttr::Multiply,
            component,
            lanes,
            operations,
            next_value,
            ranked_ir,
        )?;
        let component_index = push_projected_index_binary_v1(
            IndexBinaryKindAttr::Add,
            block_base,
            component_base,
            operations,
            next_value,
            ranked_ir,
        )?;
        let component_index = push_projected_index_binary_v1(
            IndexBinaryKindAttr::Add,
            component_index,
            lane,
            operations,
            next_value,
            ranked_ir,
        )?;
        let predicate = option_predicates.get_mut(destination).ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "a component-index Option result is outside the semantic local table",
            ),
        )?;
        if predicate.is_some() {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "multiple predicates target one component-index Option local",
            ));
        }
        *predicate = Some(GuardPredicateV1 {
            comparisons: vec![(component, elements)],
        });
        option_payload_values[destination] = Some(component_index);
    }

    bind_component_index_enum_payloads_v1(
        function,
        &option_payload_values,
        local_definitions,
        address_escaped,
        enum_payload_loads,
        enum_payload_dominance,
    )
}

fn bind_component_index_enum_payloads_v1(
    function: &SemanticFunctionDeclV1,
    option_payload_values: &[Option<ProductionRankedValueV1>],
    local_definitions: &[u8],
    address_escaped: &[bool],
    enum_payload_loads: &[PendingEnumPayloadLoadV1],
    enum_payload_dominance: &SemanticEnumPayloadDominanceV1,
) -> Result<Vec<Option<ProjectedOrdinaryIndexV1>>, ProductionRankedProjectionErrorV1> {
    let local_count = function.locals().len();
    if option_payload_values.len() != local_count
        || local_definitions.len() != local_count
        || address_escaped.len() != local_count
    {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "component-index enum-payload inventories do not match the semantic local table",
        ));
    }
    let mut ordinary_index_values = vec![None; local_count];
    for load in enum_payload_loads {
        let Some(payload) = option_payload_values.get(load.carrier).copied().flatten() else {
            continue;
        };
        if load.variant != 1
            || local_definitions.get(load.carrier).copied() != Some(1)
            || local_definitions.get(load.destination).copied() != Some(1)
            || address_escaped.get(load.destination).copied() != Some(false)
        {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a component-index payload load changed carrier, variant, or local custody",
            ));
        }
        let availability = enum_payload_dominance
            .availability(
                SemanticLocalIdV1::from_index(load.carrier as u32),
                load.variant,
            )
            .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                "a component-index Some payload lacks an exact enum-dominance region",
            ))?;
        if !enum_payload_dominance.allows(
            availability,
            SemanticBlockIdV1::from_index(load.use_block as u32),
        ) {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "a component-index payload is loaded outside its authenticated Some edge",
            ));
        }
        let projected = ProjectedOrdinaryIndexV1 {
            value: payload,
            availability,
        };
        let slot = ordinary_index_values.get_mut(load.destination).ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "a component-index payload destination is outside the semantic local table",
            ),
        )?;
        match *slot {
            None => *slot = Some(projected),
            Some(existing) if existing == projected => {}
            Some(_) => {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "multiple component-index payloads reach one ordinary index local",
                ));
            }
        }
    }
    Ok(ordinary_index_values)
}

fn capability_availability_allows(
    option: &SemanticOptionDominanceV1,
    enum_payload: &SemanticEnumPayloadDominanceV1,
    availability: CapabilityAvailabilityV1,
    block: SemanticBlockIdV1,
) -> bool {
    match availability {
        CapabilityAvailabilityV1::Option(availability) => option.allows(availability, block),
        CapabilityAvailabilityV1::EnumPayload(availability) => {
            enum_payload.allows(availability, block)
        }
    }
}

fn ranked_value_text_v1(value: ProductionRankedValueV1) -> String {
    match value {
        ProductionRankedValueV1::Local(identity) => format!("%{}", identity.get()),
        ProductionRankedValueV1::Argument(argument) => format!("%arg{argument}"),
        ProductionRankedValueV1::BlockArgument { block, argument } => {
            format!("%bb{block}_arg{argument}")
        }
    }
}

fn switch_predicates(
    function: &SemanticFunctionDeclV1,
    option_predicates: &[Option<GuardPredicateV1>],
    direct_switch_predicates: &[Option<GuardPredicateV1>],
) -> Result<Vec<Option<GuardPredicateV1>>, ProductionRankedProjectionErrorV1> {
    if direct_switch_predicates.len() != function.locals().len() {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "direct switch predicates do not match the semantic local table",
        ));
    }
    let scalar_inventory = assertion_definition_inventory(function)?;
    switch_predicates_core_v18(function, option_predicates, direct_switch_predicates,
        &scalar_inventory, &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy)
}

fn switch_predicates_with_facts_v18(
    function: &SemanticFunctionDeclV1,
    option_predicates: &[Option<GuardPredicateV1>],
    direct_switch_predicates: &[Option<GuardPredicateV1>],
    facts: &mut dyn ProjectedAssertionFactsV1,
) -> Result<Vec<Option<GuardPredicateV1>>, ProductionRankedProjectionErrorV1> {
    let mut allocation=source_ranked_consumer_resources_v18::ProjectionAllocationV18::from_facts(facts)?;
    if matches!(allocation,source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy) {
        return switch_predicates(function,option_predicates,direct_switch_predicates);
    }
    if direct_switch_predicates.len()!=function.locals().len() {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "direct switch predicates do not match the semantic local table"));
    }
    let scalar_inventory=assertion_definition_inventory_with_allocation_v18(function,&mut allocation)?;
    switch_predicates_core_v18(function,option_predicates,direct_switch_predicates,&scalar_inventory,&mut allocation)
}

fn clone_guard_predicate_v18(
    predicate: &GuardPredicateV1,
    allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<GuardPredicateV1, ProductionRankedProjectionErrorV1> {
    Ok(GuardPredicateV1 {comparisons: allocation.copy_slice(&predicate.comparisons)?})
}

fn switch_predicates_core_v18(
    function: &SemanticFunctionDeclV1,
    option_predicates: &[Option<GuardPredicateV1>],
    direct_switch_predicates: &[Option<GuardPredicateV1>],
    scalar_inventory: &AssertionDefinitionInventoryV1,
    allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<Vec<Option<GuardPredicateV1>>, ProductionRankedProjectionErrorV1> {
    let mut predicates = if matches!(allocation,source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy) {
        direct_switch_predicates.to_vec()
    } else {
        let mut rows=allocation.capacity(direct_switch_predicates.len())?;
        for predicate in direct_switch_predicates {
            let copied=predicate.as_ref().map(|predicate| clone_guard_predicate_v18(predicate,allocation)).transpose()?;
            allocation.push(&mut rows,copied)?;
        }
        rows
    };
    for block in function.blocks() {
        allocation.charge(1)?;
        for statement in block.statements() {
            allocation.charge(1)?;
            let SemanticStatementKindV1::Assign(assignment) = statement.kind() else {
                continue;
            };
            let destination = assignment.destination();
            if !destination.projections().is_empty() {
                continue;
            }
            let SemanticRvalueKindV1::Discriminant(source) = assignment.value().kind() else {
                continue;
            };
            if !source.projections().is_empty() {
                continue;
            }
            let destination_index = destination.local().index() as usize;
            if scalar_inventory.counts.get(destination_index).copied() != Some(1)
                || scalar_inventory
                    .address_escaped
                    .get(destination_index)
                    .copied()
                    != Some(false)
            {
                continue;
            }
            let Some(predicate) = option_predicates
                .get(source.local().index() as usize)
                .and_then(Option::as_ref)
            else {
                continue;
            };
            let predicate=clone_guard_predicate_v18(predicate,allocation)?;
            let slot = predicates.get_mut(destination_index).ok_or(
                ProductionRankedProjectionErrorV1::Unsupported(
                    "an Option discriminant outside the semantic local table",
                ),
            )?;
            if slot.is_some() {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "an Option discriminant local with multiple definitions",
                ));
            }
            *slot = Some(predicate);
        }
    }
    Ok(predicates)
}

fn operation_defines_value(operation: &ProductionRankedOperationV1) -> bool {
    matches!(
        operation,
        ProductionRankedOperationV1::View { .. }
            | ProductionRankedOperationV1::ViewInSpace { .. }
            | ProductionRankedOperationV1::IndexConstant { .. }
            | ProductionRankedOperationV1::IndexUnknown { .. }
            | ProductionRankedOperationV1::InvocationIndex { .. }
            | ProductionRankedOperationV1::IndexBinary { .. }
            | ProductionRankedOperationV1::CheckedTiledIndex2D { .. }
            | ProductionRankedOperationV1::CheckedRowStripedIndex2D { .. }
            | ProductionRankedOperationV1::Dimension { .. }
            | ProductionRankedOperationV1::SemanticSymbol { .. }
            | ProductionRankedOperationV1::SemanticConstant { .. }
            | ProductionRankedOperationV1::SemanticBinary { .. }
    )
}

fn bind_projected_access_site(
    sources: &mut [ProjectedAccessSourceV1],
    guarded_sites: &mut [GuardedAccessSiteV1],
    site: ProjectedSemanticAccessSiteV1,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    for source in sources {
        if source.semantic_site.replace(site).is_some() {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "a projected access was attributed to multiple semantic sites",
            ));
        }
    }
    for guarded in guarded_sites {
        if guarded.access.semantic_site.replace(site).is_some() {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "a guarded access was attributed to multiple semantic sites",
            ));
        }
    }
    Ok(())
}

fn order_projected_block_effects(
    operations: Vec<ProductionRankedOperationV1>,
    guarded_sites: Vec<GuardedAccessSiteV1>,
    sources: Vec<ProjectedAccessSourceV1>,
    entry_operations: &mut Vec<ProductionRankedOperationV1>,
) -> Result<ProjectedSemanticBlockV1, ProductionRankedProjectionErrorV1> {
    order_projected_block_effects_core_v18(operations, guarded_sites, sources, entry_operations,
        &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy)
}

fn order_projected_block_effects_core_v18(
    operations: Vec<ProductionRankedOperationV1>,
    guarded_sites: Vec<GuardedAccessSiteV1>,
    sources: Vec<ProjectedAccessSourceV1>,
    entry_operations: &mut Vec<ProductionRankedOperationV1>,
    allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<ProjectedSemanticBlockV1, ProductionRankedProjectionErrorV1> {
    allocation.header::<Result<ProjectedSemanticBlockV1, ProductionRankedProjectionErrorV1>>()?;
    allocation.header::<std::iter::Peekable<std::vec::IntoIter<GuardedAccessSiteV1>>>()?;
    allocation.header::<std::iter::Enumerate<std::vec::IntoIter<ProductionRankedOperationV1>>>()?;
    allocation.header::<std::vec::IntoIter<ProjectedAccessSourceV1>>()?;
    let mut source_at = allocation.filled(operations.len(), None)?;
    let item_capacity = if matches!(allocation, source_ranked_consumer_resources_v18::ProjectionAllocationV18::Source(_)) {
        source_ranked_consumer_resources_v18::add(operations.len(), guarded_sites.len())?
    } else { 0 };
    for source in sources {
        allocation.charge(1)?;
        let slot = source_at.get_mut(source.operation).ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "a projected access source outside its semantic block",
            ),
        )?;
        if slot.is_some() {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "multiple projected sources for one ranked effect",
            ));
        }
        *slot = Some(ProjectedEffectSourceV1 {
            access: source.access,
            memory_space: source.memory_space,
            source: source.source,
            output_extent: source.output_extent,
            semantic_site: source.semantic_site,
        });
    }
    let mut sites = guarded_sites.into_iter().peekable();
    let mut items = if matches!(allocation, source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy) {
        Vec::new()
    } else { allocation.capacity(item_capacity)? };
    for (index, operation) in operations.into_iter().enumerate() {
        allocation.charge(1)?;
        while sites
            .peek()
            .is_some_and(|site| site.insertion_operation == index)
        {
            allocation.push(&mut items, ProjectedBlockItemV1::Guarded(
                sites
                    .next()
                    .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                        "a peeked guarded access site disappeared before projection",
                    ))?
                    .access,
            ))?;
        }
        if sites
            .peek()
            .is_some_and(|site| site.insertion_operation < index)
        {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "checked access sites are not in semantic statement order",
            ));
        }
        let source = source_at[index];
        if operation_defines_value(&operation) {
            if source.is_some() {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "a pure ranked definition carried a memory-effect source",
                ));
            }
            reserve_operation_core_v18(entry_operations, allocation)?;
            allocation.push(entry_operations, operation)?;
        } else {
            allocation.push(&mut items, ProjectedBlockItemV1::Effect { operation, source })?;
        }
    }
    for site in sites {
        allocation.charge(1)?;
        if site.insertion_operation != source_at.len() {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "a checked access site is outside its semantic block",
            ));
        }
        allocation.push(&mut items, ProjectedBlockItemV1::Guarded(site.access))?;
    }
    Ok(ProjectedSemanticBlockV1 { items })
}

#[cfg(test)]
mod ordered_source_block_tests_v18 {
    use super::*;
    use fe2o3_kernel_ir::{CanonicalKernelIrWorkBudgetV1 as Work,
        CanonicalKernelIrVerificationResourceBudgetV1 as Budget};
    use source_ranked_consumer_resources_v18::{ProjectionAllocationV18, SourceAssertionMeterV18};
    use std::mem::size_of;

    struct CounterFacts<'a>(&'a mut dyn fe2o3_mir_model::SemanticAssertionMeterV1<Error = ProductionRankedProjectionErrorV1>);
    impl ProjectedAssertionFactsV1 for CounterFacts<'_> {
        fn projection_meter_v18(&mut self) -> Option<&mut dyn fe2o3_mir_model::SemanticAssertionMeterV1<Error = ProductionRankedProjectionErrorV1>> { Some(&mut *self.0) }
        fn charge_private_array_work(&mut self, amount: usize) -> Result<(), ProductionRankedProjectionErrorV1> { self.0.charge_work(amount) }
        fn private_array_initializer_count(&mut self, _: usize, _: usize) -> Result<Option<u64>, ProductionRankedProjectionErrorV1> { panic!("counter test does not inspect initializers") }
        fn is_materialized_block(&mut self, _: usize) -> Result<bool, ProductionRankedProjectionErrorV1> { panic!("counter test grants no control authority") }
        fn condition(&mut self, _: usize, _: bool, _: SemanticBlockIdV1) -> Result<canonical_assertion_facts_v1::ProjectedAssertionConditionV1, ProductionRankedProjectionErrorV1> { panic!("counter test grants no condition authority") }
    }

    fn inputs() -> (Vec<ProductionRankedOperationV1>, Vec<ProjectedAccessSourceV1>) {
        let mut operations = vec![ProductionRankedOperationV1::IndexConstant {
            result: ProductionRankedValueIdV1::new(0), value: 3,
        }];
        let mut sources = Vec::new();
        for access in [AccessKindAttr::Read, AccessKindAttr::Write] {
            let operation = operations.len();
            operations.push(ProductionRankedOperationV1::AllocationEffect {
                kind: access, memory_space: MemorySpaceAttr::Global,
                allocation_origin: 1, noalias_class: 1,
            });
            sources.push(ProjectedAccessSourceV1 {
                block: 7, operation, access, memory_space: MemorySpaceAttr::Global,
                source: SemanticSourceProvenanceV1::unavailable(), output_extent: None,
                semantic_site: Some(ProjectedSemanticAccessSiteV1 { block: 7, statement: Some(operation) }),
            });
        }
        (operations, sources)
    }

    #[test]
    fn ordered_source_block_has_independent_work_capacity_and_first_failure_oracles() {
        let storage = size_of::<Result<ProjectedSemanticBlockV1, ProductionRankedProjectionErrorV1>>()
            + size_of::<std::iter::Peekable<std::vec::IntoIter<GuardedAccessSiteV1>>>()
            + size_of::<std::iter::Enumerate<std::vec::IntoIter<ProductionRankedOperationV1>>>()
            + size_of::<std::vec::IntoIter<ProjectedAccessSourceV1>>()
            + size_of::<Vec<Option<ProjectedEffectSourceV1>>>()
            + 3 * size_of::<Option<ProjectedEffectSourceV1>>()
            + size_of::<Vec<ProjectedBlockItemV1>>() + 3 * size_of::<ProjectedBlockItemV1>();
        // Three source slots, two source rows, three operation visits and
        // three moved outputs. Caller-owned entry capacity already has room.
        let work = 11;
        let (operations, sources) = inputs();
        let mut legacy_entry = Vec::with_capacity(1);
        let expected = order_projected_block_effects(operations, vec![], sources, &mut legacy_entry).unwrap();
        for (work_limit, storage_limit) in [(work, storage), (work - 1, storage), (work, storage - 1)] {
            let (operations, sources) = inputs();
            let mut entry = Vec::with_capacity(1);
            let mut ledger = Work::new(work_limit);
            let mut budget = Budget::new(&mut ledger, 53 + storage_limit);
            budget.reserve_storage(53).unwrap();
            let result = order_projected_block_effects_core_v18(operations, vec![], sources, &mut entry,
                &mut ProjectionAllocationV18::Source(&mut SourceAssertionMeterV18(&mut budget)));
            if work_limit < work {
                assert!(result.is_err());
                assert_eq!((budget.storage(), budget.peak_storage()), (53 + storage, 53 + storage));
                drop(budget);
                assert_eq!(ledger.failed_work(), Some(work));
            } else if storage_limit < storage {
                assert!(result.is_err());
                assert_eq!(budget.failed_storage(), Some(53 + storage));
                assert_eq!(budget.work(), 5);
            } else {
                let projected = result.unwrap();
                assert_eq!(projected, expected);
                assert_eq!(entry, legacy_entry);
                assert_eq!((budget.work(), budget.storage()), (work, 53 + storage));
                drop(projected);
                drop(entry);
                budget.release_storage(storage).unwrap();
                assert_eq!(budget.storage(), 53);
            }
        }
    }

    #[test]
    fn ordered_source_block_rejects_duplicate_and_out_of_range_source_rows() {
        for out_of_range in [false, true] {
            let (operations, mut sources) = inputs();
            sources[1].operation = if out_of_range { 3 } else { sources[0].operation };
            let mut ledger = Work::new(100);
            let mut budget = Budget::new(&mut ledger, 100_000);
            let mut entry = Vec::with_capacity(1);
            assert!(order_projected_block_effects_core_v18(operations, vec![], sources, &mut entry,
                &mut ProjectionAllocationV18::Source(&mut SourceAssertionMeterV18(&mut budget))).is_err());
            assert!(entry.is_empty());
        }
    }

    #[test]
    fn source_access_counter_preparation_has_independent_header_capacity_and_work_oracles() {
        type Key = (usize, Option<usize>);
        type Row = (Key, u32);
        let storage = size_of::<ProjectionAllocationV18<'_>>()
            + size_of::<ProjectionAccessOrdinalsV18>() + size_of::<Vec<Row>>() + size_of::<Row>()
            + size_of::<(usize, usize, usize, Key, Key)>()
            + size_of::<Result<(), ProductionRankedProjectionErrorV1>>();
        let source = inputs().1.remove(0);
        for (work, limit) in [(3, storage), (2, storage), (3, storage - 1)] {
            let mut ledger = Work::new(work);
            let mut budget = Budget::new(&mut ledger, 19 + limit);
            budget.reserve_storage(19).unwrap();
            let result = ProjectionAccessOrdinalsV18::prepare(&[source],
                &mut CounterFacts(&mut SourceAssertionMeterV18(&mut budget)));
            if work < 3 {
                assert!(result.is_err());
                assert_eq!(budget.storage(), 19 + storage);
                drop(budget);
                assert_eq!(ledger.failed_work(), Some(3));
            } else if limit < storage {
                assert!(result.is_err());
                assert_eq!(budget.failed_storage(), Some(19 + storage));
                assert_eq!(budget.work(), 2);
            } else {
                let ProjectionAccessOrdinalsV18::Source(rows) = result.unwrap() else { panic!("source used the legacy hash table") };
                assert_eq!(rows, [((7, Some(1)), 0)]);
                assert_eq!((budget.work(), budget.storage()), (3, 19 + storage));
            }
        }
    }

    #[test]
    fn source_access_counter_repeats_sites_without_merging_access_roles() {
        let (_, mut sources) = inputs();
        sources.push(sources[0]);
        sources[0].semantic_site.as_mut().unwrap().block = usize::MAX;
        sources[2].semantic_site = sources[0].semantic_site;
        let mut ledger = Work::new(100);
        let mut budget = Budget::new(&mut ledger, 100_000);
        let mut meter = SourceAssertionMeterV18(&mut budget);
        let mut facts = CounterFacts(&mut meter);
        let mut counters = ProjectionAccessOrdinalsV18::prepare(&sources, &mut facts).unwrap();
        let first = sources[0].semantic_site.unwrap();
        assert_eq!(counters.current(Some(first), &mut facts).unwrap(), 0);
        *counters.slot(first, &mut facts).unwrap() += 1;
        assert_eq!(counters.current(sources[2].semantic_site, &mut facts).unwrap(), 1);
        assert_eq!(counters.current(sources[1].semantic_site, &mut facts).unwrap(), 0);
        assert!(counters.current(Some(ProjectedSemanticAccessSiteV1 { block: 0, statement: None }), &mut facts).is_err());
        let ProjectionAccessOrdinalsV18::Source(rows) = counters else { unreachable!() };
        assert_eq!(rows.len(), 2);
        assert_eq!(rows.capacity(), 3);
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum ProjectedCfgTerminatorV1 {
    AbsentMaterialized,
    Branch(usize),
    Predicate {
        predicate: GuardPredicateV1,
        true_block: usize,
        false_block: usize,
    },
    AnalysisSplit {
        first_block: usize,
        second_block: usize,
    },
    AnalysisMultiSplit {
        blocks: Vec<usize>,
    },
    ExactSwitch(ProjectedDeterministicSwitchV1),
    Return,
    Trap,
}

fn projected_cfg_terminator(
    function: &SemanticFunctionDeclV1,
    block_index: usize,
    callables: &[SemanticCallableDeclV1],
    non_bounds_assert_proved: bool,
    assertion_facts: &mut impl ProjectedAssertionFactsV1,
    switch_predicates: &[Option<GuardPredicateV1>],
    deterministic_switches: &[Option<ProjectedDeterministicSwitchV1>],
) -> Result<ProjectedCfgTerminatorV1, ProductionRankedProjectionErrorV1> {
    let block = function.blocks().get(block_index).ok_or(
        ProductionRankedProjectionErrorV1::Unsupported("a semantic CFG block outside the function"),
    )?;
    let target = |target: fe2o3_mir_model::semantic_mir_v1::SemanticBlockIdV1| {
        let target = target.index() as usize;
        (target < function.blocks().len()).then_some(target).ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "a semantic CFG edge outside the function",
            ),
        )
    };
    match block.terminator().kind() {
        SemanticTerminatorKindV1::Goto(edge) => {
            Ok(ProjectedCfgTerminatorV1::Branch(target(edge.target())?))
        }
        SemanticTerminatorKindV1::SwitchInt {
            discriminant,
            targets,
        } => {
            let predicate = simple_operand_local(discriminant).and_then(|discriminant| {
                switch_predicates
                    .get(discriminant.index() as usize)
                    .and_then(Clone::clone)
            });
            let Some(predicate) = predicate else {
                if let Some(projected) = deterministic_switches
                    .get(block_index)
                    .and_then(Clone::clone)
                {
                    return Ok(ProjectedCfgTerminatorV1::ExactSwitch(projected));
                }
                let successor_capacity = targets.values().len().checked_add(1).ok_or(
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "analysis switch successor count overflow",
                    ),
                )?;
                if successor_capacity > MAX_RANKED_BOUNDS_EDGES {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "analysis switch edge count exceeds the ranked edge limit",
                    ));
                }
                let otherwise = target(targets.otherwise().target())?;
                let elide_fallback = targets.values().len() == 2
                    && targets.values()[0].value() == 0
                    && targets.values()[1].value() == 1
                    && switch_fallback_is_empty_unreachable_v1(function, otherwise);
                let mut successors = Vec::new();
                successors
                    .try_reserve_exact(successor_capacity)
                    .map_err(|_| {
                        ProductionRankedProjectionErrorV1::Unsupported(
                            "analysis switch successor storage cannot be reserved",
                        )
                    })?;
                let mut seen = HashSet::new();
                seen.try_reserve(successor_capacity).map_err(|_| {
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "analysis switch successor set cannot be reserved",
                    )
                })?;
                for successor in targets.values() {
                    let successor = target(successor.edge().target())?;
                    if seen.insert(successor) {
                        successors.push(successor);
                    }
                }
                if !elide_fallback && seen.insert(otherwise) {
                    successors.push(otherwise);
                }
                if successors.len() > MAX_RANKED_BOUNDS_BLOCKS {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "analysis switch successor count exceeds the ranked block limit",
                    ));
                }
                return match successors.as_slice() {
                    [] => Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "analysis switch has no successor",
                    )),
                    [successor] => Ok(ProjectedCfgTerminatorV1::Branch(*successor)),
                    [first_block, second_block] => Ok(ProjectedCfgTerminatorV1::AnalysisSplit {
                        first_block: *first_block,
                        second_block: *second_block,
                    }),
                    _ => Ok(ProjectedCfgTerminatorV1::AnalysisMultiSplit { blocks: successors }),
                };
            };
            if targets.values().len() == 1 {
                let explicit = &targets.values()[0];
                let explicit_block = target(explicit.edge().target())?;
                let otherwise_block = target(targets.otherwise().target())?;
                return match explicit.value() {
                    0 => Ok(ProjectedCfgTerminatorV1::Predicate {
                        predicate,
                        true_block: otherwise_block,
                        false_block: explicit_block,
                    }),
                    1 => Ok(ProjectedCfgTerminatorV1::Predicate {
                        predicate,
                        true_block: explicit_block,
                        false_block: otherwise_block,
                    }),
                    _ => Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "a comparison predicate switch retained a non-boolean explicit value",
                    )),
                };
            }
            let zero = targets.values().iter().find(|target| target.value() == 0);
            let one = targets.values().iter().find(|target| target.value() == 1);
            if targets.values().len() != 2 || zero.is_none() || one.is_none() {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a comparison predicate switch whose exact boolean variants were not retained",
                ));
            }
            let otherwise = target(targets.otherwise().target())?;
            if !switch_fallback_is_empty_unreachable_v1(function, otherwise) {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a comparison predicate switch with a reachable non-boolean successor",
                ));
            }
            let one = one.ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                "a comparison predicate switch lost its true variant",
            ))?;
            let zero = zero.ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                "a comparison predicate switch lost its false variant",
            ))?;
            Ok(ProjectedCfgTerminatorV1::Predicate {
                predicate,
                true_block: target(one.edge().target())?,
                false_block: target(zero.edge().target())?,
            })
        }
        SemanticTerminatorKindV1::Call(call) => {
            if matches!(call.unwind(), SemanticUnwindActionV1::Cleanup(_)) {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a call with cleanup control flow before exact unwind projection",
                ));
            }
            match call.destination() {
                Some(destination) => Ok(ProjectedCfgTerminatorV1::Branch(target(
                    destination.edge().target(),
                )?)),
                None if matches!(
                    callables.get(call.callee().index() as usize),
                    Some(SemanticCallableDeclV1::CompilerIntrinsic {
                        operation: SemanticCompilerIntrinsicOperationV1::Trap,
                        ..
                    })
                ) =>
                {
                    Ok(ProjectedCfgTerminatorV1::Trap)
                }
                None => Ok(ProjectedCfgTerminatorV1::Return),
            }
        }
        SemanticTerminatorKindV1::Assert {
            condition,
            expected,
            message,
            target: edge,
            ..
        } => {
            if !matches!(message, SemanticAssertMessageV1::BoundsCheck { .. }) {
                let masked_source_proof = assertion_facts.masked_assertion_source_proved_v1(
                    function,
                    block_index,
                    *expected,
                    edge.target(),
                )?;
                // A contradictory actual graph constant overrides a source proof.
                let graph_condition =
                    assertion_facts.condition(block_index, *expected, edge.target())?;
                if !projected_assertion_is_proved_v1(
                    graph_condition,
                    *expected,
                    non_bounds_assert_proved || masked_source_proof,
                ) {
                    return Err(ProductionRankedProjectionErrorV1::UnprovenAssert {
                        block: block_index,
                        kind: semantic_assert_kind_v1(message),
                        expected: *expected,
                        condition_local: simple_operand_local(condition)
                            .map(SemanticLocalIdV1::index),
                        source: Box::new(block.terminator().source()),
                    });
                }
            }
            Ok(ProjectedCfgTerminatorV1::Branch(target(edge.target())?))
        }
        SemanticTerminatorKindV1::Drop { target: edge, .. } => {
            Ok(ProjectedCfgTerminatorV1::Branch(target(edge.target())?))
        }
        SemanticTerminatorKindV1::FalseEdge { .. } => {
            Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a false edge before exact semantic CFG normalization",
            ))
        }
        SemanticTerminatorKindV1::Return
        | SemanticTerminatorKindV1::TailCall(_)
        | SemanticTerminatorKindV1::UnwindResume
        | SemanticTerminatorKindV1::UnwindTerminate
        | SemanticTerminatorKindV1::Abort
        | SemanticTerminatorKindV1::Unreachable => Ok(ProjectedCfgTerminatorV1::Return),
    }
}

const fn semantic_assert_kind_v1(message: &SemanticAssertMessageV1) -> &'static str {
    match message {
        SemanticAssertMessageV1::BoundsCheck { .. } => "bounds-check",
        SemanticAssertMessageV1::Overflow { .. } => "arithmetic-overflow",
        SemanticAssertMessageV1::DivisionByZero(_) => "division-by-zero",
        SemanticAssertMessageV1::RemainderByZero(_) => "remainder-by-zero",
        SemanticAssertMessageV1::MisalignedPointerDereference { .. } => {
            "misaligned-pointer-dereference"
        }
        SemanticAssertMessageV1::NullPointerDereference => "null-pointer-dereference",
        SemanticAssertMessageV1::ResumedAfterReturn => "resumed-after-return",
        SemanticAssertMessageV1::ResumedAfterPanic => "resumed-after-panic",
    }
}

fn switch_fallback_is_empty_unreachable_v1(
    function: &SemanticFunctionDeclV1,
    block: usize,
) -> bool {
    function.blocks().get(block).is_some_and(|block| {
        block.statements().is_empty()
            && matches!(
                block.terminator().kind(),
                SemanticTerminatorKindV1::Unreachable
            )
    })
}

fn projected_block_expansion(
    block: &ProjectedSemanticBlockV1,
    terminator: &ProjectedCfgTerminatorV1,
) -> Result<usize, ProductionRankedProjectionErrorV1> {
    projected_block_expansion_core_v18(block, terminator,
        &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy)
}

fn projected_block_expansion_core_v18(
    block: &ProjectedSemanticBlockV1,
    terminator: &ProjectedCfgTerminatorV1,
    allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<usize, ProductionRankedProjectionErrorV1> {
    let mut count = 1_usize;
    for item in &block.items {
        allocation.charge(1)?;
        if let ProjectedBlockItemV1::Guarded(access) = item {
            let comparisons = if matches!(allocation, source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy) {
                GuardPredicateV1::for_access(access).comparisons.len()
            } else { access.comparisons.len() };
            count = count
                .checked_add(comparisons + 2)
                .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                    "checked-access CFG block count overflow",
                ))?;
        }
    }
    if let ProjectedCfgTerminatorV1::Predicate { predicate, .. } = terminator {
        count = count
            .checked_add(predicate.comparisons.len().saturating_sub(1))
            .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                "semantic CFG predicate block count overflow",
            ))?;
    }
    if let ProjectedCfgTerminatorV1::ExactSwitch(switch) = terminator {
        count = count
            .checked_add(switch.targets.len().saturating_sub(1))
            .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                "deterministic switch CFG block count overflow",
            ))?;
    }
    if let ProjectedCfgTerminatorV1::AnalysisMultiSplit { blocks } = terminator {
        count = count.checked_add(blocks.len().saturating_sub(2)).ok_or(
            ProductionRankedProjectionErrorV1::Unsupported(
                "analysis switch CFG block count overflow",
            ),
        )?;
    }
    Ok(count)
}

fn live_induction_block_arguments(
    block: u32,
    live: &[usize],
) -> Result<Vec<ProductionRankedValueV1>, ProductionRankedProjectionErrorV1> {
    live.iter()
        .enumerate()
        .map(|(argument, _)| live_induction_argument_v18(block,argument))
        .collect()
}

fn live_induction_argument_v18(block:u32,argument:usize)->Result<ProductionRankedValueV1,ProductionRankedProjectionErrorV1>{
    Ok(ProductionRankedValueV1::BlockArgument {block,argument:u32::try_from(argument)
        .map_err(|_|ProductionRankedProjectionErrorV1::Unsupported("live induction argument count does not fit u32"))?})
}

fn live_induction_block_arguments_with_allocation_v18(
    block:u32,
    live:&[usize],
    allocation:&mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<Vec<ProductionRankedValueV1>,ProductionRankedProjectionErrorV1> {
    if matches!(allocation,source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy) {
        return live_induction_block_arguments(block,live);
    }
    let mut rows=allocation.capacity(live.len())?;
    for argument in 0..live.len() {
        let value=live_induction_argument_v18(block,argument)?;
        allocation.push(&mut rows,value)?;
    }
    Ok(rows)
}

fn forward_live_inductions(
    source_block: u32,
    source_live: &[usize],
    target_live: &[usize],
) -> Result<Vec<ProductionRankedValueV1>, ProductionRankedProjectionErrorV1> {
    target_live
        .iter()
        .map(|target|forward_live_induction_argument_v18(source_block,source_live,*target))
        .collect()
}

fn forward_live_induction_argument_v18(source_block:u32,source_live:&[usize],target:usize)
    ->Result<ProductionRankedValueV1,ProductionRankedProjectionErrorV1>
{
    let argument=source_live.iter().position(|source|*source==target)
        .ok_or(ProductionRankedProjectionErrorV1::Incomplete("a ranked edge introduces an induction outside its preheader"))?;
    live_induction_argument_v18(source_block,argument)
}

fn forward_live_inductions_with_allocation_v18(
    source_block:u32,
    source_live:&[usize],
    target_live:&[usize],
    allocation:&mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<Vec<ProductionRankedValueV1>,ProductionRankedProjectionErrorV1> {
    if matches!(allocation,source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy) {
        return forward_live_inductions(source_block,source_live,target_live);
    }
    let mut rows=allocation.capacity(target_live.len())?;
    for target in target_live {
        allocation.charge(source_live.len())?;
        let value=forward_live_induction_argument_v18(source_block,source_live,*target)?;
        allocation.push(&mut rows,value)?;
    }
    Ok(rows)
}

fn build_ranked_cfg(
    types: &[SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    callables: &[SemanticCallableDeclV1],
    switch_predicates: &[Option<GuardPredicateV1>],
    deterministic_switches: &[Option<ProjectedDeterministicSwitchV1>],
    uniform_inductions: &[ProjectedUniformInductionV1],
    entry_operations: Vec<ProductionRankedOperationV1>,
    mut projected_blocks: Vec<ProjectedSemanticBlockV1>,
    assertion_facts: &mut impl ProjectedAssertionFactsV1,
    mut induction_scope: Option<&mut multi_entry_induction_v1::Scope>,
) -> Result<
    (
        Vec<ProductionRankedBlockV1>,
        Vec<ProjectedAccessSourceV1>,
        Vec<ProductionRankedExecutableEffectSourceV1>,
    ),
    ProductionRankedProjectionErrorV1,
> {
    if projected_blocks.len() != function.blocks().len() {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "semantic CFG projection lost a basic block",
        ));
    }
    let (mut proved_assertions, body_predicates) = {
        let mut allocation = source_ranked_consumer_resources_v18::ProjectionAllocationV18::from_facts(assertion_facts)?;
        let proved = SemanticAssertProofsV1::analyze_live_v18(types, function, &mut allocation)?;
        let predicates = indexed_induction_body_predicates_core_v18(function, uniform_inductions, &mut allocation)?;
        (proved, predicates)
    };
    let mut has_multi_entry = false;
    for induction in uniform_inductions {
        has_multi_entry |= matches!(
            induction.preheader_control,
            ProjectedInductionPreheaderControlV1::Multiple(_)
        );
        assertion_facts.require_guarded_source_progress_v1(
            types,
            function,
            induction,
            &entry_operations,
        )?;
        let Some(block) = induction
            .source_progress
            .update
            .proved_overflow_assert_block()
        else {
            continue;
        };
        let proved = proved_assertions.get_mut(block).ok_or(
            ProductionRankedProjectionErrorV1::Incomplete(
                "an authenticated source induction overflow assertion has a stale block",
            ),
        )?;
        *proved = true;
    }
    if has_multi_entry {
        let scope =
            induction_scope
                .as_deref_mut()
                .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                    "multi-entry ranked emission requires live canonical facts",
                ))?;
        multi_entry_induction_v1::before_emission(
            function,
            uniform_inductions,
            &mut multi_entry_induction_v1::Context {
                scope,
                facts: assertion_facts,
            },
        )?;
    }
    if let Some(scope) = induction_scope {
        induction_initialization_v1::before_emission(
            function,
            uniform_inductions,
            &mut multi_entry_induction_v1::Context {
                scope,
                facts: assertion_facts,
            },
        )?;
    } else {
        induction_initialization_v1::without_scope(function, uniform_inductions, assertion_facts)?;
    }
    let terminators = (0..function.blocks().len())
        .map(|index| {
            if !assertion_facts.is_materialized_block(index)? {
                return Ok(ProjectedCfgTerminatorV1::AbsentMaterialized);
            }
            projected_cfg_terminator(
                function,
                index,
                callables,
                proved_assertions[index],
                assertion_facts,
                switch_predicates,
                deterministic_switches,
            )
        })
        .collect::<Result<Vec<_>, _>>()?;
    let mut allocation = source_ranked_consumer_resources_v18::ProjectionAllocationV18::from_facts(assertion_facts)?;
    let entry = function.entry().index() as usize;
    let reachable = reachable_projected_blocks_core_v18(entry, &terminators, &mut allocation)?;
    let live_inductions = if matches!(allocation, source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy) {
        (0..function.blocks().len())
        .map(|block| {
            uniform_inductions
                .iter()
                .enumerate()
                .filter_map(|(index, induction)| induction.contains_block(block).then_some(index))
                .collect::<Vec<_>>()
        })
        .collect::<Vec<_>>()
    } else {
        let mut rows = allocation.capacity(function.blocks().len())?;
        for block in 0..function.blocks().len() {
            let mut live = allocation.empty()?;
            for (index, induction) in uniform_inductions.iter().enumerate() {
                allocation.charge(1 + (usize::BITS - induction.loop_blocks.len().leading_zeros()) as usize)?;
                if induction.contains_block(block) { allocation.push(&mut live, index)?; }
            }
            allocation.push(&mut rows, live)?;
        }
        rows
    };
    let mut base_blocks = allocation.optional(projected_blocks.len())?;
    let mut block_count = 1_usize;
    for (index, (block, terminator)) in projected_blocks.iter().zip(&terminators).enumerate() {
        allocation.charge(1)?;
        if !reachable[index] {
            continue;
        }
        base_blocks[index] = Some(block_count);
        block_count = block_count
            .checked_add(projected_block_expansion_core_v18(block, terminator, &mut allocation)?)
            .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                "semantic CFG block count overflow",
            ))?;
    }
    if block_count > fe2o3_pliron::MAX_RANKED_BOUNDS_BLOCKS {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "semantic CFG projection exceeds the ranked block limit",
        ));
    }
    allocation.charge(projected_blocks.len())?;
    let operation_count = projected_blocks
        .iter()
        .try_fold(entry_operations.len(), |count, block| {
            count.checked_add(block.items.len())
        })
        .and_then(|count| count.checked_add(block_count));
    if operation_count.is_none_or(|count| count > MAX_RANKED_BOUNDS_OPERATIONS) {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "semantic CFG projection exceeds the ranked operation limit",
        ));
    }
    let entry_target = base_blocks.get(entry).copied().flatten().ok_or(
        ProductionRankedProjectionErrorV1::Unsupported("semantic entry block outside the function"),
    )?;
    allocation.charge(entry_operations.len())?;
    let mut next_value = entry_operations
        .iter()
        .filter_map(ranked_operation_last_result_v1)
        .map(ProductionRankedValueIdV1::get)
        .max()
        .map_or(0, |value| value.saturating_add(1));
    let pipeline_values = prepare_pipeline_values_core_v18(&mut projected_blocks, &mut next_value, &mut allocation)?;
    let mut blocks = allocation.capacity(block_count)?;
    allocation.push(&mut blocks, ProductionRankedBlockV1::new(
        entry_operations,
        ProductionRankedTerminatorV1::Branch {
            target: ranked_block_id(entry_target)?,
        },
    ))?;
    let mut sources = allocation.empty()?;
    let mut executable_effect_sources = allocation.empty()?;
    for (semantic_index, (projected, terminator)) in
        projected_blocks.into_iter().zip(terminators).enumerate()
    {
        allocation.charge(1)?;
        let Some(mut current) = base_blocks[semantic_index] else {
            continue;
        };
        let live = &live_inductions[semantic_index];
        let mut operations = allocation.empty()?;
        let mut generated_effect_ordinal = 0_u32;
        for item in projected.items {
            allocation.charge(1)?;
            match item {
                ProjectedBlockItemV1::Effect { operation, source } => {
                    if let Some(source) = source {
                        allocation.push(&mut sources, ProjectedAccessSourceV1 {
                            block: current,
                            operation: operations.len(),
                            access: source.access,
                            memory_space: source.memory_space,
                            source: source.source,
                            output_extent: source.output_extent,
                            semantic_site: source.semantic_site,
                        })?;
                    }
                    allocation.push(&mut operations, operation)?;
                }
                ProjectedBlockItemV1::Guarded(access) => {
                    let predicate = if matches!(allocation, source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy) {
                        GuardPredicateV1::for_access(&access)
                    } else { GuardPredicateV1 { comparisons: allocation.copy_slice(&access.comparisons)? } };
                    let access_block = current + predicate.comparisons.len();
                    let failure_block = access_block + 1;
                    let continuation = failure_block + 1;
                    if !live.is_empty() {
                        append_predicate_blocks_with_index_arguments_core_v18(
                            &mut blocks,
                            current,
                            operations,
                            &predicate,
                            access_block,
                            failure_block,
                            live.len(),
                            &mut allocation,
                        )?;
                    } else {
                        append_predicate_blocks_core_v18(
                            &mut blocks,
                            current,
                            operations,
                            &predicate,
                            access_block,
                            failure_block,
                            &mut allocation,
                        )?;
                    }
                    let access_operations = if let Some(success) = access.checked_success {
                        let [index] = access.indices.as_slice() else {
                            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                                "a predicated checked access is not one-dimensional",
                            ));
                        };
                        if access.access.is_atomic() {
                            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                                "a predicated checked access is not one non-atomic read or write",
                            ));
                        }
                        allocation.one(ProductionRankedOperationV1::PredicatedAccess {
                            kind: access.access,
                            view: ProductionRankedValueV1::Local(access.view),
                            index: *index,
                            success,
                        })?
                    } else {
                        allocation.one(ProductionRankedOperationV1::Access {
                            kind: access.access,
                            view: ProductionRankedValueV1::Local(access.view),
                            indices: access.indices,
                        })?
                    };
                    if !live.is_empty() {
                        let block = ranked_block_id(access_block)?;
                        push_block_at_core_v18(
                            &mut blocks,
                            access_block,
                            Some(u32::try_from(live.len()).map_err(|_| {
                                ProductionRankedProjectionErrorV1::Unsupported(
                                    "live induction argument count does not fit u32",
                                )
                            })?),
                            access_operations,
                            ProductionRankedTerminatorV1::BranchArgs {
                                arguments: live_induction_block_arguments_with_allocation_v18(block, live, &mut allocation)?,
                                target: ranked_block_id(continuation)?,
                            },
                            &mut allocation,
                        )?;
                    } else {
                        push_block_at_core_v18(
                            &mut blocks,
                            access_block,
                            None,
                            access_operations,
                            ProductionRankedTerminatorV1::Branch {
                                target: ranked_block_id(continuation)?,
                            },
                            &mut allocation,
                        )?;
                    }
                    allocation.push(&mut sources, ProjectedAccessSourceV1 {
                        block: access_block,
                        operation: 0,
                        access: access.access,
                        memory_space: access.memory_space,
                        source: access.source,
                        output_extent: access.output_extent,
                        semantic_site: access.semantic_site,
                    })?;
                    let empty_operations = allocation.empty()?;
                    push_block_at_core_v18(
                        &mut blocks,
                        failure_block,
                        None,
                        empty_operations,
                        ProductionRankedTerminatorV1::Trap,
                        &mut allocation,
                    )?;
                    current = continuation;
                    operations = allocation.empty()?;
                }
                ProjectedBlockItemV1::Pipeline(effect) => {
                    let access = match &effect {
                        ProjectedPipelineEffectV1::Access { kind, .. } => Some(*kind),
                        ProjectedPipelineEffectV1::Create { .. }
                        | ProjectedPipelineEffectV1::Event { .. } => None,
                    };
                    let first_operation = operations.len();
                    materialize_pipeline_effect_core_v18(
                        effect,
                        ranked_block_id(current)?,
                        live,
                        &mut operations,
                        &pipeline_values,
                        &mut allocation,
                    )?;
                    if let Some(access) = access {
                        allocation.charge(operations.len().checked_sub(first_operation).ok_or_else(||
                            source_ranked_consumer_resources_v18::resource(fe2o3_kernel_ir::CanonicalKernelIrVerificationResourceErrorV1::Accounting))?)?;
                        let operation = operations[first_operation..]
                            .iter()
                            .rposition(|operation| {
                                matches!(operation, ProductionRankedOperationV1::Access { .. })
                            })
                            .and_then(|operation| first_operation.checked_add(operation))
                            .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                                "a pipeline access did not materialize one ranked memory effect",
                            ))?;
                        allocation.push(&mut sources, ProjectedAccessSourceV1 {
                            block: current,
                            operation,
                            access,
                            memory_space: MemorySpaceAttr::Workgroup,
                            source: function.blocks()[semantic_index].terminator().source(),
                            output_extent: None,
                            semantic_site: Some(ProjectedSemanticAccessSiteV1 {
                                block: semantic_index,
                                statement: None,
                            }),
                        })?;
                    }
                }
                ProjectedBlockItemV1::GeneratedFromSemanticTerminator(effect) => {
                    if effect.semantic_effect_ordinal != generated_effect_ordinal {
                        return Err(ProductionRankedProjectionErrorV1::Unsupported(
                            "generated terminator effects are not in canonical ordinal order",
                        ));
                    }
                    generated_effect_ordinal = generated_effect_ordinal.checked_add(1).ok_or(
                        ProductionRankedProjectionErrorV1::Unsupported(
                            "generated terminator effect ordinal overflow",
                        ),
                    )?;
                    let ProjectedExecutableEffectOriginV1::GeneratedFromSemanticTerminator {
                        parent: _,
                    } = effect.origin;
                    allocation.push(&mut executable_effect_sources, ProductionRankedExecutableEffectSourceV1::new(
                        u32::try_from(semantic_index).map_err(|_| {
                            ProductionRankedProjectionErrorV1::Unsupported(
                                "generated semantic block does not fit u32",
                            )
                        })?,
                        effect.semantic_effect_ordinal,
                        u32::try_from(current).map_err(|_| {
                            ProductionRankedProjectionErrorV1::Unsupported(
                                "generated ranked block does not fit u32",
                            )
                        })?,
                        u32::try_from(operations.len()).map_err(|_| {
                            ProductionRankedProjectionErrorV1::Unsupported(
                                "generated ranked operation does not fit u32",
                            )
                        })?,
                        ProductionRankedExecutableEffectOriginV1::GeneratedFromSemanticTerminator,
                        effect.recipe_identity,
                    ))?;
                    allocation.push(&mut operations, effect.operation)?;
                }
            }
        }
        let mut preheader = None;
        for (index, induction) in uniform_inductions.iter().enumerate() {
            allocation.charge(1)?;
            let matches = match &induction.preheader_control {
                ProjectedInductionPreheaderControlV1::Multiple(entries) => {
                    allocation.charge(1 + (usize::BITS - entries.rows.len().leading_zeros()) as usize)?;
                    entries.contains(semantic_index)
                }
                _ => induction.initializer_block == semantic_index,
            };
            if matches { preheader = Some((index, induction)); break; }
        }
        if let Some((induction_index, induction)) = preheader
        {
            let block = ranked_block_id(current)?;
            let target_live = &live_inductions[induction.header];
            let exit_live = &live_inductions[induction.exit];
            allocation.charge(source_ranked_consumer_resources_v18::add(
                source_ranked_consumer_resources_v18::product(3, target_live.len())?,
                source_ranked_consumer_resources_v18::add(live.len(),
                    source_ranked_consumer_resources_v18::product(exit_live.len(),
                        2 + (usize::BITS - live.len().leading_zeros()) as usize)?)?)?)?;
            if live.contains(&induction_index)
                || exit_live.contains(&induction_index)
                || target_live.len() != live.len().saturating_add(1)
                || target_live
                    .iter()
                    .filter(|candidate| **candidate != induction_index)
                    .copied()
                    .ne(live.iter().copied())
                || target_live
                    .iter()
                    .filter(|candidate| **candidate == induction_index)
                    .count()
                    != 1
                || exit_live
                    .iter()
                    .any(|candidate| live.binary_search(candidate).is_err())
            {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a uniform induction preheader has inconsistent exact live induction sets",
                ));
            }
            let mut arguments = allocation.capacity(target_live.len())?;
            for target_induction in target_live {
                if *target_induction == induction_index {
                    allocation.push(&mut arguments, induction.initial)?;
                } else {
                    allocation.charge(live.len())?;
                    let source_argument = live
                        .iter()
                        .position(|source| source == target_induction)
                        .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                            "a uniform induction preheader introduces an unrelated live induction",
                        ))?;
                    allocation.push(&mut arguments, ProductionRankedValueV1::BlockArgument {
                        block,
                        argument: u32::try_from(source_argument).map_err(|_| {
                            ProductionRankedProjectionErrorV1::Unsupported(
                                "live induction argument count does not fit u32",
                            )
                        })?,
                    })?;
                }
            }
            let terminator = match (&induction.preheader_control, terminator) {
                (
                    ProjectedInductionPreheaderControlV1::Direct
                    | ProjectedInductionPreheaderControlV1::Multiple(_),
                    ProjectedCfgTerminatorV1::Branch(target),
                ) if target == induction.header => ProductionRankedTerminatorV1::BranchArgs {
                    arguments,
                    target: ranked_block_id(projected_target(&base_blocks, target)?)?,
                },
                (
                    ProjectedInductionPreheaderControlV1::Optional {
                        discriminant,
                        explicit_value,
                        explicit_target,
                        otherwise,
                    },
                    ProjectedCfgTerminatorV1::ExactSwitch(switch),
                ) if switch.lane_uniform
                    && switch.source_discriminant == *discriminant
                    && switch.otherwise == *otherwise
                    && matches!(
                        switch.targets.as_slice(),
                        [(value, _, target)]
                            if value == explicit_value && target == explicit_target
                    ) =>
                {
                    let (_, variant, projected_explicit_target) = switch.targets[0];
                    let exit_arguments = forward_live_inductions_with_allocation_v18(block, live, exit_live, &mut allocation)?;
                    let (true_arguments, false_arguments) =
                        if projected_explicit_target == induction.header {
                            (arguments, exit_arguments)
                        } else {
                            (exit_arguments, arguments)
                        };
                    ProductionRankedTerminatorV1::IndexEqualArgs {
                        lhs: switch.discriminant,
                        rhs: variant,
                        true_arguments,
                        false_arguments,
                        true_block: ranked_block_id(projected_target(
                            &base_blocks,
                            projected_explicit_target,
                        )?)?,
                        false_block: ranked_block_id(projected_target(
                            &base_blocks,
                            switch.otherwise,
                        )?)?,
                    }
                }
                (ProjectedInductionPreheaderControlV1::Optional { .. }, _) => {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "an optional uniform induction preheader changed after exact control binding",
                    ));
                }
                (ProjectedInductionPreheaderControlV1::Direct, _) => {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "a direct uniform induction preheader changed after topology binding",
                    ));
                }
                (ProjectedInductionPreheaderControlV1::Multiple(_), _) => {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "a multi-entry induction changed its exact source entry edge",
                    ));
                }
            };
            push_block_at_core_v18(
                &mut blocks,
                current,
                Some(u32::try_from(live.len()).map_err(|_| {
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "live induction argument count does not fit u32",
                    )
                })?),
                operations,
                terminator,
                &mut allocation,
            )?;
            continue;
        }
        allocation.charge(uniform_inductions.len())?;
        if let Some((induction_index, induction)) = uniform_inductions
            .iter()
            .enumerate()
            .find(|(_, induction)| induction.header == semantic_index)
        {
            let header = ranked_block_id(current)?;
            let body = projected_target(&base_blocks, induction.body_entry)?;
            allocation.charge(live.len())?;
            let induction_argument = live
                .iter()
                .position(|candidate| *candidate == induction_index)
                .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                    "a uniform induction header does not carry its induction value",
                ))?;
            push_block_at_core_v18(
                &mut blocks,
                current,
                Some(u32::try_from(live.len()).map_err(|_| {
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "live induction argument count does not fit u32",
                    )
                })?),
                operations,
                ProductionRankedTerminatorV1::IndexLessThanArgs {
                    lhs: ProductionRankedValueV1::BlockArgument {
                        block: header,
                        argument: u32::try_from(induction_argument).map_err(|_| {
                            ProductionRankedProjectionErrorV1::Unsupported(
                                "live induction argument count does not fit u32",
                            )
                        })?,
                    },
                    rhs: induction.bound,
                    true_arguments: forward_live_inductions_with_allocation_v18(
                        header,
                        live,
                        &live_inductions[induction.body_entry],
                        &mut allocation,
                    )?,
                    false_arguments: forward_live_inductions_with_allocation_v18(
                        header,
                        live,
                        &live_inductions[induction.exit],
                        &mut allocation,
                    )?,
                    true_block: ranked_block_id(body)?,
                    false_block: ranked_block_id(projected_target(&base_blocks, induction.exit)?)?,
                },
                &mut allocation,
            )?;
            continue;
        }
        allocation.charge(uniform_inductions.len())?;
        if let Some((induction_index, induction)) = uniform_inductions
            .iter()
            .enumerate()
            .find(|(_, induction)| induction.latch == semantic_index)
        {
            let latch = ranked_block_id(current)?;
            let target_live = &live_inductions[induction.header];
            let arguments = forward_live_inductions_with_allocation_v18(latch, live, target_live, &mut allocation)?;
            allocation.charge(target_live.len())?;
            let add_argument = target_live
                .iter()
                .position(|candidate| *candidate == induction_index)
                .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                    "a uniform induction latch does not carry its induction value",
                ))?;
            push_block_at_core_v18(
                &mut blocks,
                current,
                Some(u32::try_from(live.len()).map_err(|_| {
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "live induction argument count does not fit u32",
                    )
                })?),
                operations,
                ProductionRankedTerminatorV1::BranchArgsAddAt {
                    arguments,
                    add_argument: u32::try_from(add_argument).map_err(|_| {
                        ProductionRankedProjectionErrorV1::Unsupported(
                            "live induction argument count does not fit u32",
                        )
                    })?,
                    step: induction.step,
                    target: ranked_block_id(projected_target(&base_blocks, induction.header)?)?,
                },
                &mut allocation,
            )?;
            continue;
        }
        if !live.is_empty() {
            let block = ranked_block_id(current)?;
            let arguments_for = |target: usize, allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>|
                forward_live_inductions_with_allocation_v18(block, live, &live_inductions[target], allocation);
            if let Some(predicate) = body_predicates[semantic_index] {
                let projected = materialize_induction_body_predicate_core_v18(
                    function,
                    predicate,
                    &terminator,
                    block,
                    live,
                    &base_blocks,
                    &live_inductions,
                    &mut allocation,
                )?;
                push_block_at_core_v18(
                    &mut blocks,
                    current,
                    Some(u32::try_from(live.len()).map_err(|_| {
                        ProductionRankedProjectionErrorV1::Unsupported(
                            "live induction argument count does not fit u32",
                        )
                    })?),
                    operations,
                    projected,
                    &mut allocation,
                )?;
                continue;
            }
            let terminator = match terminator {
                ProjectedCfgTerminatorV1::Branch(target) => {
                    ProductionRankedTerminatorV1::BranchArgs {
                        arguments: arguments_for(target, &mut allocation)?,
                        target: ranked_block_id(projected_target(&base_blocks, target)?)?,
                    }
                }
                ProjectedCfgTerminatorV1::Predicate {
                    predicate,
                    true_block,
                    false_block: _,
                } if predicate.comparisons.is_empty() => ProductionRankedTerminatorV1::BranchArgs {
                    arguments: arguments_for(true_block, &mut allocation)?,
                    target: ranked_block_id(projected_target(&base_blocks, true_block)?)?,
                },
                ProjectedCfgTerminatorV1::Predicate {
                    predicate,
                    true_block,
                    false_block,
                } if predicate.comparisons.len() == 1 => {
                    let (lhs, rhs) = predicate.comparisons[0];
                    ProductionRankedTerminatorV1::IndexLessThanArgs {
                        lhs,
                        rhs,
                        true_arguments: arguments_for(true_block, &mut allocation)?,
                        false_arguments: arguments_for(false_block, &mut allocation)?,
                        true_block: ranked_block_id(projected_target(&base_blocks, true_block)?)?,
                        false_block: ranked_block_id(projected_target(&base_blocks, false_block)?)?,
                    }
                }
                ProjectedCfgTerminatorV1::Predicate { .. } => {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "a uniform induction predicate requires unrepresentable control expansion",
                    ));
                }
                ProjectedCfgTerminatorV1::AnalysisSplit {
                    first_block,
                    second_block,
                } => ProductionRankedTerminatorV1::AnalysisSplitArgs {
                    control_dependencies: allocation.empty()?,
                    first_arguments: arguments_for(first_block, &mut allocation)?,
                    second_arguments: arguments_for(second_block, &mut allocation)?,
                    first_block: ranked_block_id(projected_target(&base_blocks, first_block)?)?,
                    second_block: ranked_block_id(projected_target(&base_blocks, second_block)?)?,
                },
                ProjectedCfgTerminatorV1::AnalysisMultiSplit { blocks: targets } => {
                    analysis_multi_split_v1::append_analysis_multi_split_blocks_with_arguments_core_v18(
                        &mut blocks,
                        current,
                        operations,
                        &targets,
                        &base_blocks,
                        live,
                        &live_inductions,
                        &mut allocation,
                    )?;
                    continue;
                }
                ProjectedCfgTerminatorV1::ExactSwitch(switch) if switch.targets.is_empty() => {
                    ProductionRankedTerminatorV1::BranchArgs {
                        arguments: arguments_for(switch.otherwise, &mut allocation)?,
                        target: ranked_block_id(projected_target(&base_blocks, switch.otherwise)?)?,
                    }
                }
                ProjectedCfgTerminatorV1::ExactSwitch(switch) if switch.targets.len() == 1 => {
                    let (_, variant, target) = switch.targets[0];
                    ProductionRankedTerminatorV1::IndexEqualArgs {
                        lhs: switch.discriminant,
                        rhs: variant,
                        true_arguments: arguments_for(target, &mut allocation)?,
                        false_arguments: arguments_for(switch.otherwise, &mut allocation)?,
                        true_block: ranked_block_id(projected_target(&base_blocks, target)?)?,
                        false_block: ranked_block_id(projected_target(
                            &base_blocks,
                            switch.otherwise,
                        )?)?,
                    }
                }
                ProjectedCfgTerminatorV1::ExactSwitch(_) => {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "a uniform induction deterministic switch requires unrepresentable control expansion",
                    ));
                }
                ProjectedCfgTerminatorV1::AbsentMaterialized => {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "a projected CFG reaches a source block absent from the materialized graph",
                    ));
                }
                ProjectedCfgTerminatorV1::Return | ProjectedCfgTerminatorV1::Trap => {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "a uniform induction body returns before its unique latch",
                    ));
                }
            };
            push_block_at_core_v18(
                &mut blocks,
                current,
                Some(u32::try_from(live.len()).map_err(|_| {
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "live induction argument count does not fit u32",
                    )
                })?),
                operations,
                terminator,
                &mut allocation,
            )?;
            continue;
        }
        match terminator {
            ProjectedCfgTerminatorV1::AbsentMaterialized => {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a projected CFG reaches a source block absent from the materialized graph",
                ));
            }
            ProjectedCfgTerminatorV1::Branch(target) => push_block_at_core_v18(
                &mut blocks,
                current,
                None,
                operations,
                ProductionRankedTerminatorV1::Branch {
                    target: ranked_block_id(projected_target(&base_blocks, target)?)?,
                },
                &mut allocation,
            )?,
            ProjectedCfgTerminatorV1::Predicate {
                predicate,
                true_block,
                false_block: _,
            } if predicate.comparisons.is_empty() => push_block_at_core_v18(
                &mut blocks,
                current,
                None,
                operations,
                ProductionRankedTerminatorV1::Branch {
                    target: ranked_block_id(projected_target(&base_blocks, true_block)?)?,
                },
                &mut allocation,
            )?,
            ProjectedCfgTerminatorV1::Predicate {
                predicate,
                true_block,
                false_block,
            } => append_predicate_blocks_core_v18(
                &mut blocks,
                current,
                operations,
                &predicate,
                projected_target(&base_blocks, true_block)?,
                projected_target(&base_blocks, false_block)?,
                &mut allocation,
            )?,
            ProjectedCfgTerminatorV1::AnalysisSplit {
                first_block,
                second_block,
            } => push_block_at_core_v18(
                &mut blocks,
                current,
                None,
                operations,
                ProductionRankedTerminatorV1::AnalysisSplit {
                    control_dependencies: allocation.empty()?,
                    first_block: ranked_block_id(projected_target(&base_blocks, first_block)?)?,
                    second_block: ranked_block_id(projected_target(&base_blocks, second_block)?)?,
                },
                &mut allocation,
            )?,
            ProjectedCfgTerminatorV1::AnalysisMultiSplit { blocks: targets } => {
                analysis_multi_split_v1::append_analysis_multi_split_blocks_core_v18(
                    &mut blocks,
                    current,
                    operations,
                    &targets,
                    &base_blocks,
                    &mut allocation,
                )?;
            }
            ProjectedCfgTerminatorV1::ExactSwitch(switch) => {
                append_exact_switch_blocks_core_v18(
                    &mut blocks,
                    current,
                    operations,
                    &switch,
                    &base_blocks,
                    &mut allocation,
                )?;
            }
            ProjectedCfgTerminatorV1::Return => push_block_at_core_v18(
                &mut blocks,
                current,
                None,
                operations,
                ProductionRankedTerminatorV1::Return,
                &mut allocation,
            )?,
            ProjectedCfgTerminatorV1::Trap => push_block_at_core_v18(
                &mut blocks,
                current,
                None,
                operations,
                ProductionRankedTerminatorV1::Trap,
                &mut allocation,
            )?,
        }
    }
    if blocks.len() != block_count {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "semantic CFG projection produced a non-canonical block inventory",
        ));
    }
    Ok((blocks, sources, executable_effect_sources))
}

fn ranked_operation_last_result_v1(
    operation: &ProductionRankedOperationV1,
) -> Option<ProductionRankedValueIdV1> {
    match operation {
        ProductionRankedOperationV1::View { result, .. }
        | ProductionRankedOperationV1::ViewInSpace { result, .. }
        | ProductionRankedOperationV1::PipelineCreate { result, .. }
        | ProductionRankedOperationV1::IndexConstant { result, .. }
        | ProductionRankedOperationV1::IndexUnsignedCast { result, .. }
        | ProductionRankedOperationV1::IndexUnknown { result }
        | ProductionRankedOperationV1::InvocationIndex { result, .. }
        | ProductionRankedOperationV1::IndexBinary { result, .. }
        | ProductionRankedOperationV1::DeterministicJoin { result, .. }
        | ProductionRankedOperationV1::CheckedTiledIndex2D { result, .. }
        | ProductionRankedOperationV1::CheckedRowStripedIndex2D { result, .. }
        | ProductionRankedOperationV1::Dimension { result, .. }
        | ProductionRankedOperationV1::TensorResultComponent { result, .. }
        | ProductionRankedOperationV1::SemanticSymbol { result, .. }
        | ProductionRankedOperationV1::SemanticConstant { result, .. }
        | ProductionRankedOperationV1::SemanticBinary { result, .. }
        | ProductionRankedOperationV1::SemanticExpression { result, .. } => Some(*result),
        ProductionRankedOperationV1::PredicatedCheckedTiledIndex2D {
            result, success, ..
        }
        | ProductionRankedOperationV1::PredicatedCheckedRowStripedIndex2D {
            result, success, ..
        } => Some(if result.get() > success.get() {
            *result
        } else {
            *success
        }),
        _ => None,
    }
}

#[derive(Debug)]
enum ProjectedPipelineValuesV18 {
    Legacy(HashMap<usize, ProductionRankedValueV1>),
    Source(Vec<Option<ProductionRankedValueV1>>),
}

impl ProjectedPipelineValuesV18 {
    fn insert(
        &mut self, owner: usize, value: ProductionRankedValueV1,
        allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
    ) -> Result<Option<ProductionRankedValueV1>, ProductionRankedProjectionErrorV1> {
        match (self, allocation) {
            (Self::Legacy(rows), source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy) => Ok(rows.insert(owner, value)),
            (Self::Source(rows), allocation @ source_ranked_consumer_resources_v18::ProjectionAllocationV18::Source(_)) => {
                allocation.charge(1)?;
                let slot = rows.get_mut(owner).ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                    "a pipeline owner is outside the exact dense creation domain"))?;
                Ok(slot.replace(value))
            }
            _ => Err(ProductionRankedProjectionErrorV1::Incomplete("pipeline values lost their allocation mode")),
        }
    }

    fn get(
        &self, owner: usize,
        allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
    ) -> Result<Option<ProductionRankedValueV1>, ProductionRankedProjectionErrorV1> {
        match (self, allocation) {
            (Self::Legacy(rows), source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy) => Ok(rows.get(&owner).copied()),
            (Self::Source(rows), allocation @ source_ranked_consumer_resources_v18::ProjectionAllocationV18::Source(_)) => {
                allocation.charge(1)?;
                rows.get(owner).copied().ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                    "a pipeline owner is outside the exact dense creation domain"))
            }
            _ => Err(ProductionRankedProjectionErrorV1::Incomplete("pipeline values lost their allocation mode")),
        }
    }

    fn finish(
        &self, allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
    ) -> Result<(), ProductionRankedProjectionErrorV1> {
        match (self, allocation) {
            (Self::Legacy(_), source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy) => Ok(()),
            (Self::Source(rows), allocation @ source_ranked_consumer_resources_v18::ProjectionAllocationV18::Source(_)) => {
                for row in rows {
                    allocation.charge(1)?;
                    if row.is_none() { return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "the exact pipeline creation domain contains an unfilled owner")); }
                }
                Ok(())
            }
            _ => Err(ProductionRankedProjectionErrorV1::Incomplete("pipeline values lost their allocation mode")),
        }
    }
}

fn prepare_pipeline_values_v1(
    projected_blocks: &mut [ProjectedSemanticBlockV1],
    next_value: &mut u32,
) -> Result<ProjectedPipelineValuesV18, ProductionRankedProjectionErrorV1> {
    prepare_pipeline_values_core_v18(projected_blocks, next_value,
        &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy)
}

fn prepare_pipeline_values_core_v18(
    projected_blocks: &mut [ProjectedSemanticBlockV1],
    next_value: &mut u32,
    allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<ProjectedPipelineValuesV18, ProductionRankedProjectionErrorV1> {
    let mut pipeline_values = if matches!(allocation, source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy) {
        ProjectedPipelineValuesV18::Legacy(HashMap::new())
    } else {
        allocation.header::<ProjectedPipelineValuesV18>()?;
        let mut count = 0_usize;
        for block in projected_blocks.iter() {
            allocation.charge(1)?;
            for item in &block.items {
                allocation.charge(1)?;
                if matches!(item, ProjectedBlockItemV1::Pipeline(ProjectedPipelineEffectV1::Create { .. })) {
                    count = source_ranked_consumer_resources_v18::add(count, 1)?;
                }
            }
        }
        // Insert and final completion prove dense ordinals; the counted size
        // alone is not evidence that an arbitrary owner is in this domain.
        ProjectedPipelineValuesV18::Source(allocation.optional(count)?)
    };
    for block in projected_blocks {
        allocation.charge(1)?;
        for item in &mut block.items {
            allocation.charge(1)?;
            let ProjectedBlockItemV1::Pipeline(effect) = item else {
                continue;
            };
            match effect {
                ProjectedPipelineEffectV1::Create { owner, result, .. } => {
                    let value = (*result).ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                        "a workgroup pipeline creation result was not prepared",
                    ))?;
                    if pipeline_values
                        .insert(*owner, ProductionRankedValueV1::Local(value), allocation)?
                        .is_some()
                    {
                        return Err(ProductionRankedProjectionErrorV1::Incomplete(
                            "one workgroup pipeline is created more than once in the ranked CFG",
                        ));
                    }
                }
                ProjectedPipelineEffectV1::Event {
                    epoch, slot_result, ..
                } => {
                    prepare_pipeline_scalar_core_v18(epoch, next_value, allocation)?;
                    *slot_result = Some(next_value_id(next_value)?);
                }
                ProjectedPipelineEffectV1::Access {
                    epoch,
                    index,
                    slot_result,
                    ..
                } => {
                    prepare_pipeline_scalar_core_v18(epoch, next_value, allocation)?;
                    prepare_pipeline_scalar_core_v18(index, next_value, allocation)?;
                    *slot_result = Some(next_value_id(next_value)?);
                }
            }
        }
    }
    pipeline_values.finish(allocation)?;
    Ok(pipeline_values)
}

fn prepare_pipeline_scalar_v1(
    scalar: &mut ProjectedPipelineScalarV1,
    next_value: &mut u32,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    prepare_pipeline_scalar_core_v18(scalar, next_value,
        &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy)
}

fn prepare_pipeline_scalar_core_v18(
    scalar: &mut ProjectedPipelineScalarV1,
    next_value: &mut u32,
    allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    allocation.charge(1)?;
    if let ProjectedPipelineScalarV1::Binary {
        result,
        left,
        right,
        ..
    } = scalar
    {
        prepare_pipeline_scalar_core_v18(left, next_value, allocation)?;
        prepare_pipeline_scalar_core_v18(right, next_value, allocation)?;
        *result = Some(next_value_id(next_value)?);
    }
    Ok(())
}

fn materialize_pipeline_effect_v1(
    effect: ProjectedPipelineEffectV1,
    block: u32,
    live: &[usize],
    operations: &mut Vec<ProductionRankedOperationV1>,
    pipeline_values: &ProjectedPipelineValuesV18,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    materialize_pipeline_effect_core_v18(effect, block, live, operations, pipeline_values,
        &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy)
}

fn materialize_pipeline_effect_core_v18(
    effect: ProjectedPipelineEffectV1,
    block: u32,
    live: &[usize],
    operations: &mut Vec<ProductionRankedOperationV1>,
    pipeline_values: &ProjectedPipelineValuesV18,
    allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    allocation.charge(1)?;
    match effect {
        ProjectedPipelineEffectV1::Create { owner, result, .. } => {
            let result = result.ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                "a workgroup pipeline creation result was not prepared",
            ))?;
            if matches!(allocation, source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy) {
                debug_assert_eq!(pipeline_values.get(owner, allocation)?, Some(ProductionRankedValueV1::Local(result)));
            } else if pipeline_values.get(owner, allocation)? != Some(ProductionRankedValueV1::Local(result)) {
                return Err(ProductionRankedProjectionErrorV1::Incomplete("a pipeline creation changed its exact prepared result"));
            }
        }
        ProjectedPipelineEffectV1::Event {
            owner,
            epoch,
            slot_result,
            modulus,
            kind,
        } => {
            let pipeline = pipeline_values.get(owner, allocation)?.ok_or(
                ProductionRankedProjectionErrorV1::Incomplete(
                    "a workgroup pipeline event is not dominated by its creation",
                ),
            )?;
            let epoch = materialize_pipeline_scalar_core_v18(epoch, block, live, operations, allocation)?;
            let slot_result = slot_result.ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                "a workgroup pipeline event slot result was not prepared",
            ))?;
            allocation.push(operations, ProductionRankedOperationV1::IndexBinary {
                result: slot_result,
                kind: IndexBinaryKindAttr::Remainder,
                lhs: epoch,
                rhs: modulus,
            })?;
            allocation.push(operations, ProductionRankedOperationV1::PipelineEvent {
                pipeline,
                epoch,
                slot: ProductionRankedValueV1::Local(slot_result),
                kind,
            })?;
        }
        ProjectedPipelineEffectV1::Access {
            view,
            epoch,
            index,
            slot_result,
            modulus,
            kind,
        } => {
            let epoch = materialize_pipeline_scalar_core_v18(epoch, block, live, operations, allocation)?;
            let index = materialize_pipeline_scalar_core_v18(index, block, live, operations, allocation)?;
            let slot_result = slot_result.ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                "a workgroup pipeline access slot result was not prepared",
            ))?;
            allocation.push(operations, ProductionRankedOperationV1::IndexBinary {
                result: slot_result,
                kind: IndexBinaryKindAttr::Remainder,
                lhs: epoch,
                rhs: modulus,
            })?;
            let indices = if matches!(allocation, source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy) {
                vec![ProductionRankedValueV1::Local(slot_result), index]
            } else { allocation.copy_slice(&[ProductionRankedValueV1::Local(slot_result), index])? };
            allocation.push(operations, ProductionRankedOperationV1::Access {
                kind,
                view,
                indices,
            })?;
        }
    }
    Ok(())
}

fn materialize_pipeline_scalar_v1(
    scalar: ProjectedPipelineScalarV1,
    block: u32,
    live: &[usize],
    operations: &mut Vec<ProductionRankedOperationV1>,
) -> Result<ProductionRankedValueV1, ProductionRankedProjectionErrorV1> {
    materialize_pipeline_scalar_core_v18(scalar, block, live, operations,
        &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy)
}

fn materialize_pipeline_scalar_core_v18(
    scalar: ProjectedPipelineScalarV1,
    block: u32,
    live: &[usize],
    operations: &mut Vec<ProductionRankedOperationV1>,
    allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<ProductionRankedValueV1, ProductionRankedProjectionErrorV1> {
    allocation.charge(1)?;
    match scalar {
        ProjectedPipelineScalarV1::Value(value) => Ok(value),
        ProjectedPipelineScalarV1::Induction { induction } => {
            allocation.charge(live.len())?;
            let argument = live
                .iter()
                .position(|candidate| *candidate == induction)
                .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                    "a pipeline epoch uses an induction outside its live loop region",
                ))?;
            Ok(ProductionRankedValueV1::BlockArgument {
                block,
                argument: u32::try_from(argument).map_err(|_| {
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "live induction argument count does not fit u32",
                    )
                })?,
            })
        }
        ProjectedPipelineScalarV1::Binary {
            result,
            kind,
            left,
            right,
        } => {
            let lhs = materialize_pipeline_scalar_core_v18(*left, block, live, operations, allocation)?;
            let rhs = materialize_pipeline_scalar_core_v18(*right, block, live, operations, allocation)?;
            let result = result.ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                "a workgroup pipeline scalar result was not prepared",
            ))?;
            allocation.push(operations, ProductionRankedOperationV1::IndexBinary {
                result,
                kind,
                lhs,
                rhs,
            })?;
            Ok(ProductionRankedValueV1::Local(result))
        }
    }
}

fn reachable_projected_blocks(
    entry: usize,
    terminators: &[ProjectedCfgTerminatorV1],
) -> Result<Vec<bool>, ProductionRankedProjectionErrorV1> {
    reachable_projected_blocks_core_v18(entry, terminators,
        &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy)
}

fn reachable_projected_blocks_core_v18(
    entry: usize,
    terminators: &[ProjectedCfgTerminatorV1],
    allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<Vec<bool>, ProductionRankedProjectionErrorV1> {
    if entry >= terminators.len() {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "semantic entry block outside the function",
        ));
    }
    let mut reachable = allocation.filled(terminators.len(), false)?;
    let mut pending = allocation.one(entry)?;
    while let Some(block) = pending.pop() {
        allocation.charge(1)?;
        let slot =
            reachable
                .get_mut(block)
                .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                    "a semantic CFG edge outside the function",
                ))?;
        if *slot {
            continue;
        }
        *slot = true;
        match &terminators[block] {
            ProjectedCfgTerminatorV1::AbsentMaterialized => {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a projected CFG reaches a source block absent from the materialized graph",
                ));
            }
            ProjectedCfgTerminatorV1::Branch(target) => allocation.push(&mut pending, *target)?,
            ProjectedCfgTerminatorV1::Predicate {
                predicate,
                true_block,
                false_block,
            } => {
                allocation.push(&mut pending, *true_block)?;
                if !predicate.comparisons.is_empty() {
                    allocation.push(&mut pending, *false_block)?;
                }
            }
            ProjectedCfgTerminatorV1::AnalysisSplit {
                first_block,
                second_block,
            } => {
                allocation.push(&mut pending, *first_block)?;
                allocation.push(&mut pending, *second_block)?;
            }
            ProjectedCfgTerminatorV1::AnalysisMultiSplit { blocks } => {
                if matches!(allocation, source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy) {
                    pending.extend(blocks.iter().copied());
                } else {
                    for &target in blocks { allocation.push(&mut pending, target)?; }
                }
            }
            ProjectedCfgTerminatorV1::ExactSwitch(switch) => {
                if matches!(allocation, source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy) {
                    pending.extend(switch.targets.iter().map(|(_, _, target)| *target));
                } else {
                    for &(_, _, target) in &switch.targets { allocation.push(&mut pending, target)?; }
                }
                allocation.push(&mut pending, switch.otherwise)?;
            }
            ProjectedCfgTerminatorV1::Return | ProjectedCfgTerminatorV1::Trap => {}
        }
    }
    Ok(reachable)
}

fn projected_target(
    base_blocks: &[Option<usize>],
    semantic_block: usize,
) -> Result<usize, ProductionRankedProjectionErrorV1> {
    base_blocks.get(semantic_block).copied().flatten().ok_or(
        ProductionRankedProjectionErrorV1::Unsupported(
            "a projected CFG edge targets a pruned semantic block",
        ),
    )
}

fn append_predicate_blocks(
    blocks: &mut Vec<ProductionRankedBlockV1>,
    first_block: usize,
    first_operations: Vec<ProductionRankedOperationV1>,
    predicate: &GuardPredicateV1,
    true_block: usize,
    false_block: usize,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    append_predicate_blocks_core_v18(blocks, first_block, first_operations, predicate,
        true_block, false_block, &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy)
}

fn projected_first_operations_v18(
    first: &mut Option<Vec<ProductionRankedOperationV1>>,
    index: usize,
    allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<Vec<ProductionRankedOperationV1>, ProductionRankedProjectionErrorV1> {
    if index != 0 { return allocation.empty(); }
    if matches!(allocation, source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy) {
        return first.as_ref().cloned().ok_or(ProductionRankedProjectionErrorV1::Incomplete(
            "ranked CFG first operations were already consumed"));
    }
    // The source route consumes its already-paid input, rather than cloning
    // possibly nested operation payloads through an infallible allocation path.
    first.take().ok_or(ProductionRankedProjectionErrorV1::Incomplete(
        "ranked CFG first operations were already consumed"))
}

fn append_predicate_blocks_core_v18(
    blocks: &mut Vec<ProductionRankedBlockV1>,
    first_block: usize,
    first_operations: Vec<ProductionRankedOperationV1>,
    predicate: &GuardPredicateV1,
    true_block: usize,
    false_block: usize,
    allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    if predicate.comparisons.is_empty() {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "an empty predicate was materialized as conditional control flow",
        ));
    }
    allocation.header::<Option<Vec<ProductionRankedOperationV1>>>()?;
    let mut first_operations = Some(first_operations);
    for (index, &(lhs, rhs)) in predicate.comparisons.iter().enumerate() {
        allocation.charge(1)?;
        let block = first_block + index;
        let operations = projected_first_operations_v18(&mut first_operations, index, allocation)?;
        let next = if index + 1 == predicate.comparisons.len() {
            true_block
        } else {
            block + 1
        };
        push_block_at_core_v18(
            blocks,
            block,
            None,
            operations,
            ProductionRankedTerminatorV1::IndexLessThan {
                lhs,
                rhs,
                true_block: ranked_block_id(next)?,
                false_block: ranked_block_id(false_block)?,
            },
            allocation,
        )?;
    }
    Ok(())
}

fn append_predicate_blocks_with_index_arguments(
    blocks: &mut Vec<ProductionRankedBlockV1>,
    first_block: usize,
    first_operations: Vec<ProductionRankedOperationV1>,
    predicate: &GuardPredicateV1,
    true_block: usize,
    false_block: usize,
    argument_count: usize,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    append_predicate_blocks_with_index_arguments_core_v18(blocks, first_block, first_operations,
        predicate, true_block, false_block, argument_count,
        &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy)
}

fn append_predicate_blocks_with_index_arguments_core_v18(
    blocks: &mut Vec<ProductionRankedBlockV1>,
    first_block: usize,
    first_operations: Vec<ProductionRankedOperationV1>,
    predicate: &GuardPredicateV1,
    true_block: usize,
    false_block: usize,
    argument_count: usize,
    allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    if predicate.comparisons.is_empty() {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "an empty predicate was materialized as conditional control flow",
        ));
    }
    allocation.header::<Option<Vec<ProductionRankedOperationV1>>>()?;
    let mut first_operations = Some(first_operations);
    for (index, &(lhs, rhs)) in predicate.comparisons.iter().enumerate() {
        allocation.charge(1)?;
        let block = first_block + index;
        let operations = projected_first_operations_v18(&mut first_operations, index, allocation)?;
        let next = if index + 1 == predicate.comparisons.len() {
            true_block
        } else {
            block + 1
        };
        let block_id = ranked_block_id(block)?;
        let arguments = if matches!(allocation, source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy) {
            let live = (0..argument_count).collect::<Vec<_>>();
            live_induction_block_arguments(block_id, &live)?
        } else {
            let mut arguments = allocation.capacity(argument_count)?;
            for index in 0..argument_count {
                allocation.push(&mut arguments, live_induction_argument_v18(block_id, index)?)?;
            }
            arguments
        };
        push_block_at_core_v18(
            blocks,
            block,
            Some(u32::try_from(argument_count).map_err(|_| {
                ProductionRankedProjectionErrorV1::Unsupported(
                    "live induction argument count does not fit u32",
                )
            })?),
            operations,
            ProductionRankedTerminatorV1::IndexLessThanArgs {
                lhs,
                rhs,
                true_arguments: if matches!(allocation, source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy) {
                    arguments.clone()
                } else { arguments },
                false_arguments: allocation.empty()?,
                true_block: ranked_block_id(next)?,
                false_block: ranked_block_id(false_block)?,
            },
            allocation,
        )?;
    }
    Ok(())
}

fn append_exact_switch_blocks(
    blocks: &mut Vec<ProductionRankedBlockV1>,
    first_block: usize,
    first_operations: Vec<ProductionRankedOperationV1>,
    switch: &ProjectedDeterministicSwitchV1,
    base_blocks: &[Option<usize>],
) -> Result<(), ProductionRankedProjectionErrorV1> {
    append_exact_switch_blocks_core_v18(blocks, first_block, first_operations, switch, base_blocks,
        &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy)
}

fn append_exact_switch_blocks_core_v18(
    blocks: &mut Vec<ProductionRankedBlockV1>,
    first_block: usize,
    first_operations: Vec<ProductionRankedOperationV1>,
    switch: &ProjectedDeterministicSwitchV1,
    base_blocks: &[Option<usize>],
    allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    if switch.targets.is_empty() {
        return push_block_at_core_v18(
            blocks,
            first_block,
            None,
            first_operations,
            ProductionRankedTerminatorV1::Branch {
                target: ranked_block_id(projected_target(base_blocks, switch.otherwise)?)?,
            },
            allocation,
        );
    }
    allocation.header::<Option<Vec<ProductionRankedOperationV1>>>()?;
    let mut first_operations = Some(first_operations);
    for (index, &(_, variant, target)) in switch.targets.iter().enumerate() {
        allocation.charge(1)?;
        let block = first_block + index;
        let operations = projected_first_operations_v18(&mut first_operations, index, allocation)?;
        let false_block = if index + 1 == switch.targets.len() {
            projected_target(base_blocks, switch.otherwise)?
        } else {
            block + 1
        };
        push_block_at_core_v18(
            blocks,
            block,
            None,
            operations,
            ProductionRankedTerminatorV1::IndexEqual {
                lhs: switch.discriminant,
                rhs: variant,
                true_block: ranked_block_id(projected_target(base_blocks, target)?)?,
                false_block: ranked_block_id(false_block)?,
            },
            allocation,
        )?;
    }
    Ok(())
}

fn push_block_at(
    blocks: &mut Vec<ProductionRankedBlockV1>,
    expected: usize,
    operations: Vec<ProductionRankedOperationV1>,
    terminator: ProductionRankedTerminatorV1,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    push_block_at_core_v18(blocks,expected,None,operations,terminator,
        &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy)
}

fn push_block_at_core_v18(
    blocks:&mut Vec<ProductionRankedBlockV1>,
    expected:usize,
    index_arguments:Option<u32>,
    operations:Vec<ProductionRankedOperationV1>,
    terminator:ProductionRankedTerminatorV1,
    allocation:&mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<(),ProductionRankedProjectionErrorV1> {
    if blocks.len() != expected {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "semantic CFG projection produced non-canonical block numbering",
        ));
    }
    allocation.push(blocks,match index_arguments {
        None=>ProductionRankedBlockV1::new(operations,terminator),
        Some(count)=>ProductionRankedBlockV1::with_index_arguments(count,operations,terminator),
    })
}

fn push_block_at_with_index_arguments(
    blocks: &mut Vec<ProductionRankedBlockV1>,
    expected: usize,
    index_argument_count: u32,
    operations: Vec<ProductionRankedOperationV1>,
    terminator: ProductionRankedTerminatorV1,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    push_block_at_core_v18(blocks,expected,Some(index_argument_count),operations,terminator,
        &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy)
}

fn ranked_block_id(block: usize) -> Result<u32, ProductionRankedProjectionErrorV1> {
    u32::try_from(block).map_err(|_| {
        ProductionRankedProjectionErrorV1::Unsupported(
            "semantic CFG block identity does not fit u32",
        )
    })
}

fn format_ranked_cfg(
    function_name: &str,
    blocks: &[ProductionRankedBlockV1],
) -> Result<String, ProductionRankedProjectionErrorV1> {
    let mut output = String::new();
    push_ranked_ir(&mut output, &format!("func @{function_name} {{\n"))?;
    for (block_index, block) in blocks.iter().enumerate() {
        let arguments = (0..block.index_argument_count())
            .map(|argument| format!("%bb{block_index}_arg{argument}: index"))
            .collect::<Vec<_>>()
            .join(", ");
        let arguments = if arguments.is_empty() {
            String::new()
        } else {
            format!("({arguments})")
        };
        push_ranked_ir(&mut output, &format!("^bb{block_index}{arguments}:\n"))?;
        for operation in block.operations() {
            push_ranked_ir(&mut output, &format_ranked_operation(operation))?;
        }
        let terminator = match block.terminator() {
            ProductionRankedTerminatorV1::IndexLessThan {
                lhs,
                rhs,
                true_block,
                false_block,
            } => format!(
                "  kernel.cond_br {} < {} ^bb{}, ^bb{}\n",
                ranked_value_text_v1(*lhs),
                ranked_value_text_v1(*rhs),
                true_block,
                false_block,
            ),
            ProductionRankedTerminatorV1::IndexLessThanArgs {
                lhs,
                rhs,
                true_arguments,
                false_arguments,
                true_block,
                false_block,
            } => format!(
                "  kernel.index_lt_br_args {}, {} ({}) ^bb{}, ({}) ^bb{}\n",
                ranked_value_text_v1(*lhs),
                ranked_value_text_v1(*rhs),
                format_ranked_values(true_arguments),
                true_block,
                format_ranked_values(false_arguments),
                false_block,
            ),
            ProductionRankedTerminatorV1::IndexEqual {
                lhs,
                rhs,
                true_block,
                false_block,
            } => format!(
                "  kernel.index_eq_br {}, {} ^bb{}, ^bb{}\n",
                ranked_value_text_v1(*lhs),
                ranked_value_text_v1(*rhs),
                true_block,
                false_block,
            ),
            ProductionRankedTerminatorV1::IndexEqualArgs {
                lhs,
                rhs,
                true_arguments,
                false_arguments,
                true_block,
                false_block,
            } => format!(
                "  kernel.index_eq_br_args {}, {} ({}) ^bb{}, ({}) ^bb{}\n",
                ranked_value_text_v1(*lhs),
                ranked_value_text_v1(*rhs),
                format_ranked_values(true_arguments),
                true_block,
                format_ranked_values(false_arguments),
                false_block,
            ),
            ProductionRankedTerminatorV1::AnalysisSplit {
                control_dependencies,
                first_block,
                second_block,
            } => format!(
                "  kernel.analysis_split controls=({}) ^bb{}, ^bb{}\n",
                format_ranked_values(control_dependencies),
                first_block,
                second_block,
            ),
            ProductionRankedTerminatorV1::AnalysisSplitArgs {
                control_dependencies,
                first_arguments,
                second_arguments,
                first_block,
                second_block,
            } => format!(
                "  kernel.analysis_split controls=({}) ({}) ^bb{}, ({}) ^bb{}\n",
                format_ranked_values(control_dependencies),
                format_ranked_values(first_arguments),
                first_block,
                format_ranked_values(second_arguments),
                second_block,
            ),
            ProductionRankedTerminatorV1::Branch { target } => {
                format!("  kernel.br ^bb{target}\n")
            }
            ProductionRankedTerminatorV1::BranchArgs { arguments, target } => format!(
                "  kernel.br_args ({}) ^bb{}\n",
                format_ranked_values(arguments),
                target,
            ),
            ProductionRankedTerminatorV1::BranchArgsAdd {
                value,
                step,
                target,
            } => format!(
                "  kernel.br_args_add {}, {} ^bb{}\n",
                ranked_value_text_v1(*value),
                ranked_value_text_v1(*step),
                target,
            ),
            ProductionRankedTerminatorV1::BranchArgsAddAt {
                arguments,
                add_argument,
                step,
                target,
            } => format!(
                "  kernel.br_args_add_at ({}) [{}] += {} ^bb{}\n",
                format_ranked_values(arguments),
                add_argument,
                ranked_value_text_v1(*step),
                target,
            ),
            ProductionRankedTerminatorV1::Return => "  kernel.return\n".to_owned(),
            ProductionRankedTerminatorV1::Trap => "  kernel.trap\n".to_owned(),
        };
        push_ranked_ir(&mut output, &terminator)?;
    }
    push_ranked_ir(&mut output, "}\n")?;
    Ok(output)
}

fn format_ranked_operation(operation: &ProductionRankedOperationV1) -> String {
    match operation {
        ProductionRankedOperationV1::ExecutionLayout {
            grid_identity,
            global_extents,
            workgroup_extents,
            subgroup_size,
            full_physical_workgroups,
        } => format!(
            "  gpu.execution_layout <grid={}, global={:?}, workgroup={:?}, subgroup={}, full_physical_workgroups={}>\n",
            grid_identity,
            global_extents,
            workgroup_extents,
            subgroup_size,
            full_physical_workgroups,
        ),
        ProductionRankedOperationV1::View {
            result,
            element_width,
            writable,
            shape,
            dynamic_extents,
            allocation_origin,
            noalias_class,
        } => format!(
            "  %{} = kernel.ranked_view <{}, {}, {:?}, origin={}, noalias={}>({})\n",
            result.get(),
            element_width,
            writable,
            shape,
            allocation_origin,
            noalias_class,
            format_ranked_values(dynamic_extents),
        ),
        ProductionRankedOperationV1::ViewInSpace {
            result,
            element_width,
            writable,
            shape,
            dynamic_extents,
            memory_space,
            allocation_origin,
            noalias_class,
        } => format!(
            "  %{} = kernel.ranked_view <{}, {}, {:?}, {:?}, origin={}, noalias={}>({})\n",
            result.get(),
            element_width,
            writable,
            shape,
            memory_space,
            allocation_origin,
            noalias_class,
            format_ranked_values(dynamic_extents),
        ),
        ProductionRankedOperationV1::PipelineCreate {
            result,
            view,
            buffers,
            prefetch_distance,
        } => format!(
            "  %{} = kernel.pipeline_create {} <buffers={}, prefetch_distance={}>\n",
            result.get(),
            ranked_value_text_v1(*view),
            buffers,
            prefetch_distance,
        ),
        ProductionRankedOperationV1::PipelineEvent {
            pipeline,
            epoch,
            slot,
            kind,
        } => format!(
            "  kernel.pipeline_event {}, {}, {} <{:?}>\n",
            ranked_value_text_v1(*pipeline),
            ranked_value_text_v1(*epoch),
            ranked_value_text_v1(*slot),
            kind,
        ),
        ProductionRankedOperationV1::IndexConstant { result, value } => {
            format!("  %{} = kernel.index_constant {}\n", result.get(), value)
        }
        ProductionRankedOperationV1::IndexUnsignedCast {
            result,
            source,
            bit_width,
        } => format!(
            "  %{} = kernel.index_unsigned_cast {} <{}>\n",
            result.get(),
            ranked_value_text_v1(*source),
            bit_width,
        ),
        ProductionRankedOperationV1::IndexUnknown { result } => {
            format!("  %{} = kernel.index_unknown\n", result.get())
        }
        ProductionRankedOperationV1::InvocationIndex {
            result,
            dimension,
            launch_extent,
        } => format!(
            "  %{} = kernel.invocation_index <{}, {}>\n",
            result.get(),
            dimension,
            if *launch_extent == 0 {
                "dynamic".to_owned()
            } else {
                launch_extent.to_string()
            },
        ),
        ProductionRankedOperationV1::IndexBinary {
            result,
            kind,
            lhs,
            rhs,
        } => format!(
            "  %{} = kernel.index_binary {:?} {}, {}\n",
            result.get(),
            kind,
            ranked_value_text_v1(*lhs),
            ranked_value_text_v1(*rhs),
        ),
        ProductionRankedOperationV1::DeterministicJoin {
            result,
            dependencies,
        } => format!(
            "  %{} = kernel.deterministic_join ({})\n",
            result.get(),
            format_ranked_values(dependencies),
        ),
        ProductionRankedOperationV1::CheckedTiledIndex2D {
            result,
            invocation,
            component,
            rows,
            columns,
            row_stride,
            lanes_per_tile,
            tile_rows,
            tile_columns,
            elements_per_lane,
        } => format!(
            "  %{} = kernel.checked_tiled_index_2d <{}, {}, {}, {}>({}, {}, {}, {}, {})\n",
            result.get(),
            lanes_per_tile,
            tile_rows,
            tile_columns,
            elements_per_lane,
            ranked_value_text_v1(*invocation),
            ranked_value_text_v1(*component),
            ranked_value_text_v1(*rows),
            ranked_value_text_v1(*columns),
            ranked_value_text_v1(*row_stride),
        ),
        ProductionRankedOperationV1::CheckedRowStripedIndex2D {
            result,
            invocation,
            component,
            rows,
            columns,
            row_stride,
            lanes_per_row,
            elements_per_lane,
        } => format!(
            "  %{} = kernel.checked_row_striped_index_2d <{}, {}>({}, {}, {}, {}, {})\n",
            result.get(),
            lanes_per_row,
            elements_per_lane,
            ranked_value_text_v1(*invocation),
            ranked_value_text_v1(*component),
            ranked_value_text_v1(*rows),
            ranked_value_text_v1(*columns),
            ranked_value_text_v1(*row_stride),
        ),
        ProductionRankedOperationV1::PredicatedCheckedTiledIndex2D {
            result,
            success,
            invocation,
            component,
            rows,
            columns,
            row_stride,
            physical_extent,
            lanes_per_tile,
            tile_rows,
            tile_columns,
            elements_per_lane,
        } => format!(
            "  %{}, %{} = kernel.checked_tiled_index_2d <{}, {}, {}, {}>({}, {}, {}, {}, {}, {})\n",
            result.get(),
            success.get(),
            lanes_per_tile,
            tile_rows,
            tile_columns,
            elements_per_lane,
            ranked_value_text_v1(*invocation),
            ranked_value_text_v1(*component),
            ranked_value_text_v1(*rows),
            ranked_value_text_v1(*columns),
            ranked_value_text_v1(*row_stride),
            ranked_value_text_v1(*physical_extent),
        ),
        ProductionRankedOperationV1::PredicatedCheckedRowStripedIndex2D {
            result,
            success,
            invocation,
            component,
            rows,
            columns,
            row_stride,
            physical_extent,
            lanes_per_row,
            elements_per_lane,
        } => format!(
            "  %{}, %{} = kernel.checked_row_striped_index_2d <{}, {}>({}, {}, {}, {}, {}, {})\n",
            result.get(),
            success.get(),
            lanes_per_row,
            elements_per_lane,
            ranked_value_text_v1(*invocation),
            ranked_value_text_v1(*component),
            ranked_value_text_v1(*rows),
            ranked_value_text_v1(*columns),
            ranked_value_text_v1(*row_stride),
            ranked_value_text_v1(*physical_extent),
        ),
        ProductionRankedOperationV1::Dimension {
            result,
            view,
            dimension,
        } => format!(
            "  %{} = kernel.dimension {} {}\n",
            result.get(),
            ranked_value_text_v1(*view),
            dimension,
        ),
        ProductionRankedOperationV1::Access {
            kind,
            view,
            indices,
        } => format!(
            "  kernel.access {:?} {}[{}]\n",
            kind,
            ranked_value_text_v1(*view),
            format_ranked_values(indices),
        ),
        ProductionRankedOperationV1::PredicatedAccess {
            kind,
            view,
            index,
            success,
        } => format!(
            "  kernel.predicated_access {:?} {}[{}] if {}\n",
            kind,
            ranked_value_text_v1(*view),
            ranked_value_text_v1(*index),
            ranked_value_text_v1(*success),
        ),
        ProductionRankedOperationV1::ValueAccess {
            kind,
            view,
            indices,
            value,
        } => format!(
            "  kernel.value_access {:?} {}[{}] = {}\n",
            kind,
            ranked_value_text_v1(*view),
            format_ranked_values(indices),
            ranked_value_text_v1(*value),
        ),
        ProductionRankedOperationV1::AtomicAccess {
            kind,
            ordering,
            scope,
            view,
            indices,
        } => format!(
            "  kernel.atomic_access {:?} <{:?}, {:?}> {}[{}]\n",
            kind,
            ordering,
            scope,
            ranked_value_text_v1(*view),
            format_ranked_values(indices),
        ),
        ProductionRankedOperationV1::AtomicValueAccess {
            kind,
            ordering,
            scope,
            view,
            indices,
            value,
        } => format!(
            "  kernel.atomic_value_access {:?} <{:?}, {:?}> {}[{}] = {}\n",
            kind,
            ordering,
            scope,
            ranked_value_text_v1(*view),
            format_ranked_values(indices),
            ranked_value_text_v1(*value),
        ),
        ProductionRankedOperationV1::OwnershipContract {
            view,
            coverage,
            partition,
        } => format!(
            "  kernel.ownership_contract {:?} <{:?}, {:?}>\n",
            ranked_value_text_v1(*view),
            coverage,
            partition,
        ),
        ProductionRankedOperationV1::AllocationEffect {
            kind,
            memory_space,
            allocation_origin,
            noalias_class,
        } => format!(
            "  kernel.allocation_effect {:?} <{:?}, origin={}, noalias={}>\n",
            kind, memory_space, allocation_origin, noalias_class,
        ),
        ProductionRankedOperationV1::Barrier {
            execution_scope,
            memory_scope,
            address_space,
            order,
        } => format!(
            "  gpu.barrier <{:?}, {:?}, {:?}, {:?}>\n",
            execution_scope, memory_scope, address_space, order,
        ),
        ProductionRankedOperationV1::Fence {
            memory_scope,
            address_space,
            order,
        } => format!(
            "  gpu.fence <{:?}, {:?}, {:?}>\n",
            memory_scope, address_space, order,
        ),
        ProductionRankedOperationV1::TensorLayout {
            contract,
            convergence,
            active_lanes,
            binding,
        } => format!(
            "  kernel.tensor_layout <{:?}, {:?}, active_lanes={}, capability_binding={}>\n",
            contract,
            convergence,
            active_lanes,
            binding.is_some(),
        ),
        ProductionRankedOperationV1::SemanticSymbol { result, symbol } => {
            format!("  %{} = kernel.semantic_symbol {}\n", result.get(), symbol)
        }
        ProductionRankedOperationV1::SemanticConstant { result, value } => {
            format!("  %{} = kernel.semantic_constant {}\n", result.get(), value)
        }
        ProductionRankedOperationV1::SemanticBinary {
            result,
            kind,
            lhs,
            rhs,
        } => format!(
            "  %{} = kernel.semantic_binary {:?} {}, {}\n",
            result.get(),
            kind,
            ranked_value_text_v1(*lhs),
            ranked_value_text_v1(*rhs),
        ),
        ProductionRankedOperationV1::SemanticExpression {
            result,
            expression,
            numerical_contract,
        } => format!(
            "  %{} = kernel.semantic_expression {} <{:?}>\n",
            result.get(),
            crate::encode_hex(&expression.canonical_transcript_sha256(*numerical_contract)),
            numerical_contract,
        ),
        ProductionRankedOperationV1::CollectiveSemantics {
            contract,
            view,
            actual,
            expected,
            witness0,
            witness1,
        } => format!(
            "  kernel.collective_semantics <{contract:?}> {}, {}, {}, {}, {}\n",
            ranked_value_text_v1(*view),
            ranked_value_text_v1(*actual),
            ranked_value_text_v1(*expected),
            ranked_value_text_v1(*witness0),
            ranked_value_text_v1(*witness1),
        ),
        ProductionRankedOperationV1::RequireEquivalent { actual, expected } => format!(
            "  kernel.require_equivalent {}, {}\n",
            ranked_value_text_v1(*actual),
            ranked_value_text_v1(*expected),
        ),
        ProductionRankedOperationV1::RequireAuthenticatedReferenceEquivalent {
            actual,
            expected,
            proof,
        } => format!(
            "  proof.require_authenticated_refinement {}, {} <receipt={}>\n",
            ranked_value_text_v1(*actual),
            ranked_value_text_v1(*expected),
            crate::encode_hex(proof.receipt_identity().digest().as_bytes()),
        ),
        ProductionRankedOperationV1::RequestAuthenticatedReferenceEquivalent {
            actual,
            expected,
            subjects,
        } => format!(
            "  proof.request_authenticated_refinement {}, {} <reference_mir={}, kernel_mir={}>\n",
            ranked_value_text_v1(*actual),
            ranked_value_text_v1(*expected),
            crate::encode_hex(subjects.safe_reference_mir_hash().as_bytes()),
            crate::encode_hex(subjects.kernel_mir_hash().as_bytes()),
        ),
        ProductionRankedOperationV1::RequireEffectRefinement { contract, proof } => format!(
            "  proof.require_effect_refinement {}[{}], {}, {}, {}, {}, {}, {} <contract={}, receipt={}>\n",
            ranked_value_text_v1(contract.view()),
            format_ranked_values(contract.indices()),
            ranked_value_text_v1(contract.gpu_domain()),
            ranked_value_text_v1(contract.reference_domain()),
            ranked_value_text_v1(contract.gpu_precondition()),
            ranked_value_text_v1(contract.reference_precondition()),
            ranked_value_text_v1(contract.gpu_value()),
            ranked_value_text_v1(contract.reference_value()),
            contract.contract_identity(),
            crate::encode_hex(proof.receipt_identity().digest().as_bytes()),
        ),
        ProductionRankedOperationV1::RequestEffectRefinement { contract, subjects } => format!(
            "  proof.request_effect_refinement {}[{}], {}, {}, {}, {}, {}, {} <contract={}, reference_mir={}, kernel_mir={}>\n",
            ranked_value_text_v1(contract.view()),
            format_ranked_values(contract.indices()),
            ranked_value_text_v1(contract.gpu_domain()),
            ranked_value_text_v1(contract.reference_domain()),
            ranked_value_text_v1(contract.gpu_precondition()),
            ranked_value_text_v1(contract.reference_precondition()),
            ranked_value_text_v1(contract.gpu_value()),
            ranked_value_text_v1(contract.reference_value()),
            contract.contract_identity(),
            crate::encode_hex(subjects.safe_reference_mir_hash().as_bytes()),
            crate::encode_hex(subjects.kernel_mir_hash().as_bytes()),
        ),
        ProductionRankedOperationV1::RequireNumericalRefinement { contract, proof } => format!(
            "  proof.require_numerical_refinement {}, {}, {}, {} <contract={}, absolute_error=0x{:016x}, relative_error=0x{:016x}, receipt={}>\n",
            ranked_value_text_v1(contract.actual()),
            ranked_value_text_v1(contract.reference()),
            ranked_value_text_v1(contract.domain()),
            ranked_value_text_v1(contract.precondition()),
            contract.contract_identity(),
            contract.absolute_error_f64_bits(),
            contract.relative_error_f64_bits(),
            crate::encode_hex(proof.receipt_identity().digest().as_bytes()),
        ),
        ProductionRankedOperationV1::RequestNumericalRefinement { contract, subjects } => format!(
            "  proof.request_numerical_refinement {}, {}, {}, {} <contract={}, absolute_error=0x{:016x}, relative_error=0x{:016x}, reference_mir={}, kernel_mir={}>\n",
            ranked_value_text_v1(contract.actual()),
            ranked_value_text_v1(contract.reference()),
            ranked_value_text_v1(contract.domain()),
            ranked_value_text_v1(contract.precondition()),
            contract.contract_identity(),
            contract.absolute_error_f64_bits(),
            contract.relative_error_f64_bits(),
            crate::encode_hex(subjects.safe_reference_mir_hash().as_bytes()),
            crate::encode_hex(subjects.kernel_mir_hash().as_bytes()),
        ),
        ProductionRankedOperationV1::TensorResultComponent {
            result,
            tensor_result_root,
            component,
            scalar,
            numerical_contract,
        } => format!(
            "  %{} = kernel.tensor_result_component <result_root={}, component={}, scalar={:?}, numerical={:?}>\n",
            result.get(),
            crate::encode_hex(tensor_result_root.as_bytes()),
            component,
            scalar,
            numerical_contract,
        ),
        ProductionRankedOperationV1::RequireTensorRefinement { contract, proof } => format!(
            "  proof.require_tensor_refinement <contract={:?}, receipt={}>\n",
            contract,
            crate::encode_hex(proof.receipt_identity().digest().as_bytes()),
        ),
        ProductionRankedOperationV1::RequestTensorRefinement { contract, subjects } => format!(
            "  proof.request_tensor_refinement <contract={:?}, reference_mir={}, kernel_mir={}>\n",
            contract,
            crate::encode_hex(subjects.safe_reference_mir_hash().as_bytes()),
            crate::encode_hex(subjects.kernel_mir_hash().as_bytes()),
        ),
    }
}

fn format_ranked_values(values: &[ProductionRankedValueV1]) -> String {
    values
        .iter()
        .map(|value| ranked_value_text_v1(*value))
        .collect::<Vec<_>>()
        .join(", ")
}

fn checked_reference_origins(
    function: &SemanticFunctionDeclV1,
    callables: &[SemanticCallableDeclV1],
    guarded_access_count: usize,
    edges_by_source: &[Vec<CapabilityEdgeV1>],
    option_dominance: &SemanticOptionDominanceV1,
    enum_payload_dominance: &SemanticEnumPayloadDominanceV1,
) -> Result<Vec<Option<CheckedReferenceOriginV1>>, ProductionRankedProjectionErrorV1> {
    let definitions = local_definition_counts(function);
    let mut origins = vec![None; function.locals().len()];
    let mut worklist = VecDeque::new();
    for block in function.blocks() {
        for statement in block.statements() {
            let SemanticStatementKindV1::Assign(assignment) = statement.kind() else {
                continue;
            };
            let destination = assignment.destination();
            if !destination.projections().is_empty()
                || definitions
                    .get(destination.local().index() as usize)
                    .copied()
                    != Some(1)
            {
                continue;
            }
            let SemanticRvalueKindV1::Borrow { kind, place } = assignment.value().kind() else {
                continue;
            };
            if !matches!(kind, SemanticBorrowKindV1::Shared)
                || !place.projections().iter().any(|projection| {
                    matches!(
                        projection.kind(),
                        SemanticProjectionKindV1::Index(_)
                            | SemanticProjectionKindV1::ConstantIndex { .. }
                    )
                })
            {
                continue;
            }
            let destination = destination.local().index() as usize;
            origins[destination] = Some(CheckedReferenceOriginV1 {
                source: CheckedReferenceSourceV1::ProjectedSharedBorrow,
                availability: None,
            });
            worklist.push_back(destination);
        }
    }

    let mut access = 0_usize;
    for block in function.blocks() {
        let SemanticTerminatorKindV1::Call(call) = block.terminator().kind() else {
            continue;
        };
        if !matches!(
            callables.get(call.callee().index() as usize),
            Some(SemanticCallableDeclV1::CompilerIntrinsic {
                operation: SemanticCompilerIntrinsicOperationV1::DisjointSliceGetMut { .. }
                    | SemanticCompilerIntrinsicOperationV1::DisjointSliceGetDisjointMut { .. }
                    | SemanticCompilerIntrinsicOperationV1::DisjointSliceGetMutExclusive { .. }
                    | SemanticCompilerIntrinsicOperationV1::DisjointSliceGetBlockMut { .. }
                    | SemanticCompilerIntrinsicOperationV1::DisjointSliceGetTiled2dMut { .. }
                    | SemanticCompilerIntrinsicOperationV1::DisjointSliceGetRowStriped2dMut { .. },
                ..
            })
        ) {
            continue;
        }
        let destination = simple_call_destination(call)?;
        if definitions.get(destination.index() as usize).copied() != Some(1) {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a checked disjoint result without one exact definition",
            ));
        }
        let destination = destination.index() as usize;
        let availability = option_dominance
            .availability(SemanticLocalIdV1::from_index(destination as u32))
            .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                "a checked disjoint result without exact Option Some availability",
            ))?;
        if origins[destination].is_some() {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a checked disjoint result with a conflicting reference origin",
            ));
        }
        origins[destination] = Some(CheckedReferenceOriginV1 {
            source: CheckedReferenceSourceV1::GuardedAccess(access),
            availability: Some(CapabilityAvailabilityV1::Option(availability)),
        });
        worklist.push_back(destination);
        access += 1;
    }
    if access != guarded_access_count {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "checked disjoint access inventory changed during projection",
        ));
    }
    while let Some(source) = worklist.pop_front() {
        let Some(origin) = origins[source] else {
            continue;
        };
        let edges =
            edges_by_source
                .get(source)
                .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                    "a checked reference source outside the capability graph",
                ))?;
        for edge in edges {
            if !matches!(
                edge.kind,
                CapabilityEdgeKindV1::Alias
                    | CapabilityEdgeKindV1::AuthenticatedOptionPayload
                    | CapabilityEdgeKindV1::AuthenticatedEnumPayload { .. }
            ) {
                continue;
            }
            let authorization_block = match edge.kind {
                CapabilityEdgeKindV1::AuthenticatedEnumPayload {
                    construction_block, ..
                } => construction_block,
                _ => edge.use_block,
            };
            if !origin.availability.is_none_or(|availability| {
                capability_availability_allows(
                    option_dominance,
                    enum_payload_dominance,
                    availability,
                    SemanticBlockIdV1::from_index(authorization_block as u32),
                )
            }) {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "a checked reference is transported outside its authenticated payload region",
                ));
            }
            if definitions.get(edge.destination).copied() != Some(1) {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a checked reference destination without one exact definition",
                ));
            }
            let projected = match edge.kind {
                CapabilityEdgeKindV1::AuthenticatedEnumPayload { availability, .. } => {
                    CheckedReferenceOriginV1 {
                        availability: Some(CapabilityAvailabilityV1::EnumPayload(availability)),
                        ..origin
                    }
                }
                _ => origin,
            };
            let slot = origins.get_mut(edge.destination).ok_or(
                ProductionRankedProjectionErrorV1::Unsupported(
                    "a checked reference destination outside the semantic local table",
                ),
            )?;
            if slot.is_none() {
                *slot = Some(projected);
                worklist.push_back(edge.destination);
            } else if *slot != Some(projected) {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "a checked disjoint reference with conflicting origins",
                ));
            }
        }
    }
    Ok(origins)
}

fn local_definition_counts(function: &SemanticFunctionDeclV1) -> Vec<u8> {
    let mut definitions = vec![0_u8; function.locals().len()];
    let mut record = |place: &SemanticPlaceV1| {
        if let Some(slot) =
            local_definition_index(place).and_then(|local| definitions.get_mut(local))
        {
            *slot = slot.saturating_add(1);
        }
    };
    for block in function.blocks() {
        for statement in block.statements() {
            visit_statement_definition_places(statement.kind(), &mut record);
        }
        if let SemanticTerminatorKindV1::Call(call) = block.terminator().kind()
            && let Some(destination) = call.destination()
        {
            record(destination.place());
        }
    }
    definitions
}

fn checked_reference_origin_for_place(
    place: &SemanticPlaceV1,
    origins: &[Option<CheckedReferenceOriginV1>],
) -> Option<CheckedReferenceOriginV1> {
    let origin = origins
        .get(place.local().index() as usize)
        .copied()
        .flatten()?;
    let mut projections = place.projections().iter();
    if !matches!(
        projections.next().map(|projection| projection.kind()),
        Some(SemanticProjectionKindV1::Dereference)
    ) || !projections.all(|projection| {
        matches!(
            projection.kind(),
            SemanticProjectionKindV1::Field(_)
                | SemanticProjectionKindV1::Downcast(_)
                | SemanticProjectionKindV1::OpaqueCast
                | SemanticProjectionKindV1::Subtype
        )
    }) {
        return None;
    }
    Some(origin)
}

fn checked_reference_origin(
    place: &SemanticPlaceV1,
    block_index: usize,
    references: &CheckedReferencesV1,
) -> Result<Option<CheckedReferenceSourceV1>, ProductionRankedProjectionErrorV1> {
    let Some(origin) = checked_reference_origin_for_place(place, &references.origins) else {
        return Ok(None);
    };
    if !origin.availability.is_none_or(|availability| {
        capability_availability_allows(
            &references.option_dominance,
            &references.enum_payload_dominance,
            availability,
            SemanticBlockIdV1::from_index(block_index as u32),
        )
    }) {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "a checked reference is dereferenced outside its authenticated payload region",
        ));
    }
    Ok(Some(origin.source))
}

fn enum_payload_projection(place: &SemanticPlaceV1) -> Option<(usize, u32)> {
    let [downcast, field] = place.projections() else {
        return None;
    };
    let SemanticProjectionKindV1::Downcast(variant) = downcast.kind() else {
        return None;
    };
    matches!(field.kind(), SemanticProjectionKindV1::Field(0))
        .then_some((place.local().index() as usize, variant))
}

fn allocation_operand_local_v1(
    types: &[fe2o3_mir_model::semantic_mir_v1::SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    operand: &SemanticOperandV1,
) -> Option<SemanticLocalIdV1> {
    let place = transparent_operand_place(operand)?;
    if place.projections().is_empty() {
        return Some(place.local());
    }
    let source = function.locals().get(place.local().index() as usize)?;
    let source_type = types.get(source.ty().index() as usize)?;
    let result_type = types.get(place.ty().index() as usize)?;
    let result_pointer = match result_type.layout().backend_repr() {
        SemanticBackendReprV1::Scalar(pointer)
            if matches!(
                pointer.primitive(),
                SemanticBackendPrimitiveV1::Pointer { .. }
            ) =>
        {
            pointer.primitive()
        }
        _ => return None,
    };
    if !matches!(result_type.shape(), SemanticTypeShapeV1::Pointer(_))
        || source_type.abi_properties().first_pointee().is_none()
    {
        return None;
    }
    match source_type.layout().backend_repr() {
        SemanticBackendReprV1::Scalar(source_scalar)
            if source_scalar.primitive() == result_pointer =>
        {
            Some(place.local())
        }
        SemanticBackendReprV1::ScalarPair { first, .. } if first.primitive() == result_pointer => {
            let [projection] = place.projections() else {
                return None;
            };
            let SemanticProjectionKindV1::Field(0) = projection.kind() else {
                return None;
            };
            let fields = match source_type.shape() {
                SemanticTypeShapeV1::Tuple(fields) | SemanticTypeShapeV1::Aggregate(fields) => {
                    fields
                }
                _ => return None,
            };
            (fields.fields().first() == Some(&place.ty())
                && source_type
                    .layout()
                    .fields()
                    .source_order_offsets_bytes()
                    .and_then(|offsets| offsets.first())
                    == Some(&0))
            .then_some(place.local())
        }
        _ => None,
    }
}

fn simple_call_destination(
    call: &SemanticDirectCallV1,
) -> Result<SemanticLocalIdV1, ProductionRankedProjectionErrorV1> {
    call.destination()
        .map(|destination| destination.place())
        .filter(|place| place.projections().is_empty())
        .map(SemanticPlaceV1::local)
        .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
            "a compiler intrinsic without one exact local destination",
        ))
}

fn reserve_operation(
    operations: &mut Vec<ProductionRankedOperationV1>,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    reserve_operation_core_v18(operations,
        &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy)
}

fn reserve_operation_core_v18(
    operations: &mut Vec<ProductionRankedOperationV1>,
    allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    if operations.len() == MAX_PROJECTED_OPERATIONS_V1 {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "a semantic intrinsic projection exceeding the ranked operation limit",
        ));
    }
    allocation.reserve(operations, 1, false, "semantic intrinsic projection storage cannot be reserved")
}

fn projected_block_uses_bounds_check(
    block: &ProjectedSemanticBlockV1,
    check: ProjectedBoundsCheckV1,
) -> bool {
    projected_block_uses_bounds_check_core_v18(block, check,
        &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18::Legacy)
        .expect("legacy bounds-use inspection has no fallible meter")
}

fn projected_block_uses_bounds_check_core_v18(
    block: &ProjectedSemanticBlockV1,
    check: ProjectedBoundsCheckV1,
    allocation: &mut source_ranked_consumer_resources_v18::ProjectionAllocationV18<'_>,
) -> Result<bool, ProductionRankedProjectionErrorV1> {
    for item in &block.items {
        allocation.charge(1)?;
        let found = match item {
        ProjectedBlockItemV1::Effect {
            operation:
                ProductionRankedOperationV1::Access { indices, .. }
                | ProductionRankedOperationV1::AtomicAccess { indices, .. },
            ..
        } => {
            allocation.charge(indices.len())?;
            indices.contains(&check.index)
        },
        ProjectedBlockItemV1::Guarded(access) => {
            allocation.charge(access.indices.len())?;
            if access.indices.contains(&check.index) {
                allocation.charge(access.comparisons.len())?;
                access.comparisons.contains(&(check.index, check.extent))
            } else { false }
        }
        ProjectedBlockItemV1::Pipeline(_) => false,
        ProjectedBlockItemV1::GeneratedFromSemanticTerminator(_) => false,
        ProjectedBlockItemV1::Effect { .. } => false,
        };
        if found { return Ok(true); }
    }
    Ok(false)
}

fn retain_incomplete(
    result: Result<(), ProductionRankedProjectionErrorV1>,
    incomplete: &mut Option<ProductionRankedProjectionErrorV1>,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    match result {
        Err(
            error @ (ProductionRankedProjectionErrorV1::Incomplete(_)
            | ProductionRankedProjectionErrorV1::UnprovenDeterministicDivisor(_)
            | ProductionRankedProjectionErrorV1::UnresolvedCallableEffect { .. }
            | ProductionRankedProjectionErrorV1::UnresolvedDropEffect { .. }),
        ) => {
            incomplete.get_or_insert(error);
            Ok(())
        }
        result => result,
    }
}

#[allow(clippy::too_many_arguments)]
fn project_statement_accesses(
    types: &[fe2o3_mir_model::semantic_mir_v1::SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    block_index: usize,
    bounds_checks: &[ProjectedBoundsCheckV1],
    statement: &fe2o3_mir_model::semantic_mir_v1::SemanticStatementV1,
    constants: &[Option<u64>],
    local_contracts: &ProjectionLocalContractsV1,
    guarded_accesses: &[GuardedRankedAccessV1],
    guarded_sites: &mut Vec<GuardedAccessSiteV1>,
    projected_views: &mut ProjectedViewsV1<'_>,
    operations: &mut Vec<ProductionRankedOperationV1>,
    sources: &mut Vec<ProjectedAccessSourceV1>,
    next_value: &mut u32,
    ranked_ir: &mut String,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    let source = statement.source();
    match statement.kind() {
        SemanticStatementKindV1::Assign(assignment) => {
            // Match executable lowering: evaluate every RHS read before the
            // destination write, including when both refer to one allocation.
            project_rvalue_reads(
                types,
                function,
                block_index,
                bounds_checks,
                assignment.value().kind(),
                source,
                constants,
                local_contracts,
                guarded_accesses,
                guarded_sites,
                projected_views,
                operations,
                sources,
                next_value,
                ranked_ir,
            )?;
            project_place_access(
                types,
                function,
                block_index,
                bounds_checks,
                assignment.destination(),
                AccessKindAttr::Write,
                PlaceAccessRequirementV1::IfMemory,
                source,
                constants,
                local_contracts,
                guarded_accesses,
                guarded_sites,
                projected_views,
                operations,
                sources,
                next_value,
                ranked_ir,
            )
        }
        SemanticStatementKindV1::Store(store) => {
            project_operand_read(
                types,
                function,
                block_index,
                bounds_checks,
                store.value(),
                source,
                constants,
                local_contracts,
                guarded_accesses,
                guarded_sites,
                projected_views,
                operations,
                sources,
                next_value,
                ranked_ir,
            )?;
            project_place_access_with_atomic(
                types,
                function,
                block_index,
                bounds_checks,
                store.destination(),
                if store.atomic().is_some() {
                    AccessKindAttr::AtomicWrite
                } else {
                    AccessKindAttr::Write
                },
                store.atomic(),
                PlaceAccessRequirementV1::ExplicitMemory,
                source,
                constants,
                local_contracts,
                guarded_accesses,
                guarded_sites,
                projected_views,
                operations,
                sources,
                next_value,
                ranked_ir,
            )
        }
        SemanticStatementKindV1::AtomicRmw(atomic) => {
            project_operand_read(
                types,
                function,
                block_index,
                bounds_checks,
                atomic.value(),
                source,
                constants,
                local_contracts,
                guarded_accesses,
                guarded_sites,
                projected_views,
                operations,
                sources,
                next_value,
                ranked_ir,
            )?;
            project_atomic_address(
                types,
                function,
                block_index,
                bounds_checks,
                atomic.address(),
                atomic.access(),
                source,
                constants,
                local_contracts,
                guarded_accesses,
                guarded_sites,
                projected_views,
                operations,
                sources,
                next_value,
                ranked_ir,
            )?;
            project_place_access(
                types,
                function,
                block_index,
                bounds_checks,
                atomic.destination(),
                AccessKindAttr::Write,
                PlaceAccessRequirementV1::IfMemory,
                source,
                constants,
                local_contracts,
                guarded_accesses,
                guarded_sites,
                projected_views,
                operations,
                sources,
                next_value,
                ranked_ir,
            )
        }
        SemanticStatementKindV1::AtomicCompareExchange(atomic) => {
            project_place_access(
                types,
                function,
                block_index,
                bounds_checks,
                atomic.destination(),
                AccessKindAttr::Write,
                PlaceAccessRequirementV1::IfMemory,
                source,
                constants,
                local_contracts,
                guarded_accesses,
                guarded_sites,
                projected_views,
                operations,
                sources,
                next_value,
                ranked_ir,
            )?;
            project_atomic_address(
                types,
                function,
                block_index,
                bounds_checks,
                atomic.address(),
                atomic.success(),
                source,
                constants,
                local_contracts,
                guarded_accesses,
                guarded_sites,
                projected_views,
                operations,
                sources,
                next_value,
                ranked_ir,
            )?;
            project_operand_read(
                types,
                function,
                block_index,
                bounds_checks,
                atomic.expected(),
                source,
                constants,
                local_contracts,
                guarded_accesses,
                guarded_sites,
                projected_views,
                operations,
                sources,
                next_value,
                ranked_ir,
            )?;
            project_operand_read(
                types,
                function,
                block_index,
                bounds_checks,
                atomic.replacement(),
                source,
                constants,
                local_contracts,
                guarded_accesses,
                guarded_sites,
                projected_views,
                operations,
                sources,
                next_value,
                ranked_ir,
            )
        }
        SemanticStatementKindV1::SetDiscriminant { place, .. }
        | SemanticStatementKindV1::Deinitialize(place) => project_place_access(
            types,
            function,
            block_index,
            bounds_checks,
            place,
            AccessKindAttr::Write,
            PlaceAccessRequirementV1::IfMemory,
            source,
            constants,
            local_contracts,
            guarded_accesses,
            guarded_sites,
            projected_views,
            operations,
            sources,
            next_value,
            ranked_ir,
        ),
        SemanticStatementKindV1::StorageLive(local)
        | SemanticStatementKindV1::StorageDead(local) => {
            if function.locals().get(local.index() as usize).is_none() {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "a storage statement with an out-of-range local",
                ));
            }
            // Storage lifetime markers do not read or write the local's value.
            Ok(())
        }
        SemanticStatementKindV1::Assume(condition) => project_operand_read(
            types,
            function,
            block_index,
            bounds_checks,
            condition,
            source,
            constants,
            local_contracts,
            guarded_accesses,
            guarded_sites,
            projected_views,
            operations,
            sources,
            next_value,
            ranked_ir,
        ),
        SemanticStatementKindV1::Nop => Ok(()),
    }
}

#[allow(clippy::too_many_arguments)]
fn project_atomic_address(
    types: &[fe2o3_mir_model::semantic_mir_v1::SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    block_index: usize,
    bounds_checks: &[ProjectedBoundsCheckV1],
    address: &SemanticPlaceV1,
    atomic: SemanticAtomicAccessV1,
    source: SemanticSourceProvenanceV1,
    constants: &[Option<u64>],
    local_contracts: &ProjectionLocalContractsV1,
    guarded_accesses: &[GuardedRankedAccessV1],
    guarded_sites: &mut Vec<GuardedAccessSiteV1>,
    projected_views: &mut ProjectedViewsV1<'_>,
    operations: &mut Vec<ProductionRankedOperationV1>,
    sources: &mut Vec<ProjectedAccessSourceV1>,
    next_value: &mut u32,
    ranked_ir: &mut String,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    project_place_access_with_atomic(
        types,
        function,
        block_index,
        bounds_checks,
        address,
        AccessKindAttr::AtomicReadModifyWrite,
        Some(atomic),
        PlaceAccessRequirementV1::ExplicitMemory,
        source,
        constants,
        local_contracts,
        guarded_accesses,
        guarded_sites,
        projected_views,
        operations,
        sources,
        next_value,
        ranked_ir,
    )
}

#[allow(clippy::too_many_arguments)]
fn project_terminator_accesses(
    callables: &[SemanticCallableDeclV1],
    callable_effects: &DefinedCallableEmptyEffectSummariesV1,
    types: &[fe2o3_mir_model::semantic_mir_v1::SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    block_index: usize,
    bounds_checks: &[ProjectedBoundsCheckV1],
    terminator: &SemanticTerminatorKindV1,
    source: SemanticSourceProvenanceV1,
    constants: &[Option<u64>],
    local_contracts: &ProjectionLocalContractsV1,
    guarded_accesses: &[GuardedRankedAccessV1],
    guarded_sites: &mut Vec<GuardedAccessSiteV1>,
    projected_views: &mut ProjectedViewsV1<'_>,
    operations: &mut Vec<ProductionRankedOperationV1>,
    sources: &mut Vec<ProjectedAccessSourceV1>,
    next_value: &mut u32,
    ranked_ir: &mut String,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    match terminator {
        SemanticTerminatorKindV1::SwitchInt { discriminant, .. } => project_operand_read(
            types,
            function,
            block_index,
            bounds_checks,
            discriminant,
            source,
            constants,
            local_contracts,
            guarded_accesses,
            guarded_sites,
            projected_views,
            operations,
            sources,
            next_value,
            ranked_ir,
        ),
        SemanticTerminatorKindV1::Call(call) => project_direct_call_accesses(
            callables,
            callable_effects,
            types,
            function,
            block_index,
            bounds_checks,
            call,
            source,
            constants,
            local_contracts,
            guarded_accesses,
            guarded_sites,
            projected_views,
            operations,
            sources,
            next_value,
            ranked_ir,
        ),
        SemanticTerminatorKindV1::TailCall(call) => project_tail_call_accesses(
            callables,
            callable_effects,
            types,
            function,
            block_index,
            bounds_checks,
            call,
            source,
            constants,
            local_contracts,
            guarded_accesses,
            guarded_sites,
            projected_views,
            operations,
            sources,
            next_value,
            ranked_ir,
        ),
        SemanticTerminatorKindV1::Drop { drop_glue, .. } => {
            Err(ProductionRankedProjectionErrorV1::UnresolvedDropEffect {
                block: block_index,
                source: Box::new(source),
                drop_glue: drop_glue.index(),
            })
        }
        SemanticTerminatorKindV1::Assert { condition, .. } => project_operand_read(
            types,
            function,
            block_index,
            bounds_checks,
            condition,
            source,
            constants,
            local_contracts,
            guarded_accesses,
            guarded_sites,
            projected_views,
            operations,
            sources,
            next_value,
            ranked_ir,
        ),
        SemanticTerminatorKindV1::Goto(_)
        | SemanticTerminatorKindV1::FalseEdge { .. }
        | SemanticTerminatorKindV1::Return
        | SemanticTerminatorKindV1::UnwindResume
        | SemanticTerminatorKindV1::UnwindTerminate
        | SemanticTerminatorKindV1::Abort
        | SemanticTerminatorKindV1::Unreachable => Ok(()),
    }
}

const fn requires_ranked_workgroup_barrier_v1(
    operation: &SemanticCompilerIntrinsicOperationV1,
) -> bool {
    matches!(
        operation,
        SemanticCompilerIntrinsicOperationV1::WorkgroupBarrier
            | SemanticCompilerIntrinsicOperationV1::Gfx950LdsTransposePublish { .. }
            | SemanticCompilerIntrinsicOperationV1::WorkgroupPipelineEvent {
                event: SemanticWorkgroupPipelineEventV1::Wait,
                ..
            }
    )
}

#[allow(clippy::too_many_arguments)]
fn project_direct_call_accesses(
    callables: &[SemanticCallableDeclV1],
    callable_effects: &DefinedCallableEmptyEffectSummariesV1,
    types: &[fe2o3_mir_model::semantic_mir_v1::SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    block_index: usize,
    bounds_checks: &[ProjectedBoundsCheckV1],
    call: &SemanticDirectCallV1,
    source: SemanticSourceProvenanceV1,
    constants: &[Option<u64>],
    local_contracts: &ProjectionLocalContractsV1,
    guarded_accesses: &[GuardedRankedAccessV1],
    guarded_sites: &mut Vec<GuardedAccessSiteV1>,
    projected_views: &mut ProjectedViewsV1<'_>,
    operations: &mut Vec<ProductionRankedOperationV1>,
    sources: &mut Vec<ProjectedAccessSourceV1>,
    next_value: &mut u32,
    ranked_ir: &mut String,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    if matches!(
        callables.get(call.callee().index() as usize),
        Some(SemanticCallableDeclV1::CompilerIntrinsic {
            operation: SemanticCompilerIntrinsicOperationV1::NeutralWorkgroupReduceSum { .. }
                | SemanticCompilerIntrinsicOperationV1::NeutralWorkgroupScanSum { .. },
            ..
        })
    ) {
        // The compiler-generated LDS accesses and synchronization are emitted
        // as one ordered, no-source terminator stream by
        // `project_generated_terminator_effects_v1`.
        return Ok(());
    }
    if callables
        .get(call.callee().index() as usize)
        .is_some_and(|callable| {
            matches!(
                callable,
                SemanticCallableDeclV1::CompilerIntrinsic { operation, .. }
                    if requires_ranked_workgroup_barrier_v1(operation)
            )
        })
    {
        reserve_operation(operations)?;
        operations.push(ProductionRankedOperationV1::Barrier {
            execution_scope: HierarchyAttr::Workgroup,
            memory_scope: MemoryScopeAttr::Workgroup,
            address_space: AddressSpaceAttr::Workgroup,
            order: MemoryOrderAttr::AcquireRelease,
        });
        push_ranked_ir(
            ranked_ir,
            "  gpu.barrier <workgroup, workgroup, workgroup, acquire_release>\n",
        )?;
        return Ok(());
    }
    if matches!(
        callables.get(call.callee().index() as usize),
        Some(SemanticCallableDeclV1::CompilerIntrinsic {
            operation: SemanticCompilerIntrinsicOperationV1::ThreadIndex1d { .. }
                | SemanticCompilerIntrinsicOperationV1::ThreadIndexIntoDisjoint { .. }
                | SemanticCompilerIntrinsicOperationV1::ThreadIndexCheckedShift { .. }
                | SemanticCompilerIntrinsicOperationV1::ThreadIndexCheckedBlock { .. }
                | SemanticCompilerIntrinsicOperationV1::DisjointIndexGet { .. }
                | SemanticCompilerIntrinsicOperationV1::DisjointBlockComponentIndex { .. }
                | SemanticCompilerIntrinsicOperationV1::DisjointIndexCheckedShift { .. }
                | SemanticCompilerIntrinsicOperationV1::DisjointSliceGetMut { .. }
                | SemanticCompilerIntrinsicOperationV1::DisjointSliceGetDisjointMut { .. }
                | SemanticCompilerIntrinsicOperationV1::GridLeaderCurrent { .. }
                | SemanticCompilerIntrinsicOperationV1::DisjointSliceGetMutExclusive { .. }
                | SemanticCompilerIntrinsicOperationV1::DisjointSliceGetBlockMut { .. },
            ..
        })
    ) {
        return Ok(());
    }
    if matches!(
        callables.get(call.callee().index() as usize),
        Some(SemanticCallableDeclV1::CompilerIntrinsic {
            operation: SemanticCompilerIntrinsicOperationV1::WorkgroupPipelineCreate { .. }
                | SemanticCompilerIntrinsicOperationV1::WorkgroupPipelineEvent { .. }
                | SemanticCompilerIntrinsicOperationV1::WorkgroupPipelineWrite { .. }
                | SemanticCompilerIntrinsicOperationV1::WorkgroupPipelineRead { .. },
            ..
        })
    ) {
        return Ok(());
    }
    if matches!(
        callables.get(call.callee().index() as usize),
        Some(SemanticCallableDeclV1::Defined { function })
            if !callable_effects.is_exact_empty(*function)
    ) {
        match projected_views.call_projection_disposition_v18(block_index, call, source)? {
            CallProjectionDispositionV18::CheckedUnitLocal => {}
            CallProjectionDispositionV18::PendingStorage(pending) => {
                projected_views.accept_pending_source_call_v18(pending)?;
            }
        }
    } else {
        require_bounds_neutral_callable(
            callables,
            callable_effects,
            call.callee(),
            block_index,
            source,
            false,
        )?;
    }
    for argument in call.arguments() {
        project_operand_read(
            types,
            function,
            block_index,
            bounds_checks,
            argument,
            source,
            constants,
            local_contracts,
            guarded_accesses,
            guarded_sites,
            projected_views,
            operations,
            sources,
            next_value,
            ranked_ir,
        )?;
    }
    if let Some(destination) = call.destination() {
        project_place_access(
            types,
            function,
            block_index,
            bounds_checks,
            destination.place(),
            AccessKindAttr::Write,
            PlaceAccessRequirementV1::IfMemory,
            source,
            constants,
            local_contracts,
            guarded_accesses,
            guarded_sites,
            projected_views,
            operations,
            sources,
            next_value,
            ranked_ir,
        )?;
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn project_tail_call_accesses(
    callables: &[SemanticCallableDeclV1],
    callable_effects: &DefinedCallableEmptyEffectSummariesV1,
    types: &[fe2o3_mir_model::semantic_mir_v1::SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    block_index: usize,
    bounds_checks: &[ProjectedBoundsCheckV1],
    call: &SemanticDirectTailCallV1,
    source: SemanticSourceProvenanceV1,
    constants: &[Option<u64>],
    local_contracts: &ProjectionLocalContractsV1,
    guarded_accesses: &[GuardedRankedAccessV1],
    guarded_sites: &mut Vec<GuardedAccessSiteV1>,
    projected_views: &mut ProjectedViewsV1<'_>,
    operations: &mut Vec<ProductionRankedOperationV1>,
    sources: &mut Vec<ProjectedAccessSourceV1>,
    next_value: &mut u32,
    ranked_ir: &mut String,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    require_bounds_neutral_callable(
        callables,
        callable_effects,
        call.callee(),
        block_index,
        source,
        true,
    )?;
    for argument in call.arguments() {
        project_operand_read(
            types,
            function,
            block_index,
            bounds_checks,
            argument,
            source,
            constants,
            local_contracts,
            guarded_accesses,
            guarded_sites,
            projected_views,
            operations,
            sources,
            next_value,
            ranked_ir,
        )?;
    }
    Ok(())
}

fn require_bounds_neutral_callable(
    callables: &[SemanticCallableDeclV1],
    callable_effects: &DefinedCallableEmptyEffectSummariesV1,
    callable: SemanticCallableIdV1,
    block: usize,
    source: SemanticSourceProvenanceV1,
    tail: bool,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    match callables.get(callable.index() as usize) {
        Some(SemanticCallableDeclV1::CompilerIntrinsic { .. }) => Ok(()),
        Some(SemanticCallableDeclV1::Defined { function })
            if callable_effects.is_exact_empty(*function) =>
        {
            Ok(())
        }
        Some(
            SemanticCallableDeclV1::Defined { .. } | SemanticCallableDeclV1::DeviceFfiImport { .. },
        )
        | None => Err(
            ProductionRankedProjectionErrorV1::UnresolvedCallableEffect {
                block,
                source: Box::new(source),
                callee: callable.index(),
                tail,
            },
        ),
    }
}

#[derive(Clone, Copy)]
enum ConstantDefinitionV1 {
    Missing,
    Direct(u64),
    Alias(SemanticLocalIdV1),
    Invalid,
}

fn constant_locals(
    function: &SemanticFunctionDeclV1,
) -> Result<Vec<Option<u64>>, ProductionRankedProjectionErrorV1> {
    constant_locals_core_v18(
        function,
        &mut optimized_source_projection_v18::ConstantAllocationV18::Legacy,
    )
}

fn constant_locals_core_v18(
    function: &SemanticFunctionDeclV1,
    allocation: &mut optimized_source_projection_v18::ConstantAllocationV18<'_, '_>,
) -> Result<Vec<Option<u64>>, ProductionRankedProjectionErrorV1> {
    let local_count = function.locals().len();
    let mut definitions = allocation.rows(local_count,
        "constant-local definition storage cannot be reserved")?;
    definitions.resize(local_count, ConstantDefinitionV1::Missing);
    for block in function.blocks() {
        allocation.charge(1)?;
        for statement in block.statements() {
            // Escape, definition and invalidation visits are constant-time.
            // The closed MIR destination visitor yields at most two places.
            allocation.charge(3)?;
            if let SemanticStatementKindV1::Assign(assignment) = statement.kind()
                && let Some(definition) = address_escaped_local_index_v1(assignment.value().kind())
                    .and_then(|local| definitions.get_mut(local))
            {
                *definition = ConstantDefinitionV1::Invalid;
            }
            if let SemanticStatementKindV1::Assign(assignment) = statement.kind() {
                if local_definition_index(assignment.destination()).is_some() {
                    record_constant_definition(
                        &mut definitions,
                        assignment.destination().local(),
                        match (
                            assignment.destination().projections(),
                            assignment.value().kind(),
                        ) {
                            ([], SemanticRvalueKindV1::Use(operand)) => {
                                constant_definition(operand)
                            }
                            _ => ConstantDefinitionV1::Invalid,
                        },
                    );
                }
            } else {
                visit_statement_definition_places(statement.kind(), &mut |place| {
                    if local_definition_index(place).is_some() {
                        record_constant_definition(
                            &mut definitions,
                            place.local(),
                            ConstantDefinitionV1::Invalid,
                        );
                    }
                });
            }
        }
        allocation.charge(1)?;
        if let SemanticTerminatorKindV1::Call(call) = block.terminator().kind()
            && let Some(destination) = call.destination()
            && local_definition_index(destination.place()).is_some()
        {
            record_constant_definition(
                &mut definitions,
                destination.place().local(),
                ConstantDefinitionV1::Invalid,
            );
        }
    }
    let mut states = allocation.rows(local_count,
        "constant-local resolution-state storage cannot be reserved")?;
    states.resize(local_count, 0_u8);
    let mut values = allocation.rows(local_count,
        "constant-local value storage cannot be reserved")?;
    values.resize(local_count, None);
    let mut path = allocation.rows(local_count,
        "constant-local resolution-path storage cannot be reserved")?;
    // N root probes, at most N first visits, N terminating probes and N
    // finalized path entries bound this exact shared functional-graph solver.
    allocation.charge_linear_resolution(local_count)?;
    for index in 0..definitions.len() {
        resolve_constant_iterative(index, &definitions, &mut states, &mut values, &mut path);
    }
    allocation.drop_rows(path)?;
    allocation.drop_rows(states)?;
    allocation.drop_rows(definitions)?;
    Ok(values)
}

fn constant_definition(operand: &SemanticOperandV1) -> ConstantDefinitionV1 {
    match operand {
        SemanticOperandV1::Constant(constant) => match constant.value() {
            SemanticConstantValueV1::Scalar(value) => u64::try_from(value.bits())
                .map(ConstantDefinitionV1::Direct)
                .unwrap_or(ConstantDefinitionV1::Invalid),
            _ => ConstantDefinitionV1::Invalid,
        },
        SemanticOperandV1::Copy(place) | SemanticOperandV1::Move(place)
            if place.projections().is_empty() =>
        {
            ConstantDefinitionV1::Alias(place.local())
        }
        SemanticOperandV1::Copy(_) | SemanticOperandV1::Move(_) => ConstantDefinitionV1::Invalid,
    }
}

fn constant_operand_value(operand: &SemanticOperandV1, constants: &[Option<u64>]) -> Option<u64> {
    match constant_definition(operand) {
        ConstantDefinitionV1::Direct(value) => Some(value),
        ConstantDefinitionV1::Alias(local) => {
            constants.get(local.index() as usize).copied().flatten()
        }
        ConstantDefinitionV1::Missing | ConstantDefinitionV1::Invalid => None,
    }
}

fn positive_unsigned_constant_operand_v1(
    operand: &SemanticOperandV1,
    constants: &[Option<u64>],
    types: &[fe2o3_mir_model::semantic_mir_v1::SemanticTypeDeclV1],
) -> Option<u64> {
    let SemanticTypeShapeV1::Scalar(SemanticScalarTypeV1::Integer {
        signed: false,
        bits,
    }) = types.get(operand.ty().index() as usize)?.shape()
    else {
        return None;
    };
    if *bits == 0 || *bits > 64 {
        return None;
    }
    constant_operand_value(operand, constants).filter(|step| *step > 0)
}

fn record_constant_definition(
    definitions: &mut [ConstantDefinitionV1],
    local: SemanticLocalIdV1,
    definition: ConstantDefinitionV1,
) {
    if let Some(slot) = definitions.get_mut(local.index() as usize) {
        *slot = if matches!(slot, ConstantDefinitionV1::Missing) {
            definition
        } else {
            ConstantDefinitionV1::Invalid
        };
    }
}

fn resolve_constant_iterative(
    index: usize,
    definitions: &[ConstantDefinitionV1],
    states: &mut [u8],
    values: &mut [Option<u64>],
    path: &mut Vec<usize>,
) -> Option<u64> {
    match states.get(index).copied() {
        Some(2) => return values[index],
        Some(1) | None => return None,
        Some(_) => {}
    }

    path.clear();
    let mut current = index;
    // Constant aliases form a functional graph. Retain one reusable heap path
    // so every traversed node can be finalized without recursive call depth.
    loop {
        match states.get(current).copied() {
            Some(2) | Some(1) | None => break,
            Some(_) => {}
        }
        states[current] = 1;
        path.push(current);
        match definitions[current] {
            ConstantDefinitionV1::Direct(_) => break,
            ConstantDefinitionV1::Alias(local) => current = local.index() as usize,
            ConstantDefinitionV1::Missing | ConstantDefinitionV1::Invalid => break,
        }
    }

    for current in path.drain(..).rev() {
        let resolved = match definitions[current] {
            ConstantDefinitionV1::Direct(value) => Some(value),
            ConstantDefinitionV1::Alias(local) => {
                values.get(local.index() as usize).copied().flatten()
            }
            ConstantDefinitionV1::Missing | ConstantDefinitionV1::Invalid => None,
        };
        states[current] = 2;
        values[current] = resolved;
    }
    values[index]
}

#[allow(clippy::too_many_arguments)]
fn project_rvalue_reads(
    types: &[fe2o3_mir_model::semantic_mir_v1::SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    block_index: usize,
    bounds_checks: &[ProjectedBoundsCheckV1],
    value: &SemanticRvalueKindV1,
    source: SemanticSourceProvenanceV1,
    constants: &[Option<u64>],
    local_contracts: &ProjectionLocalContractsV1,
    guarded_accesses: &[GuardedRankedAccessV1],
    guarded_sites: &mut Vec<GuardedAccessSiteV1>,
    projected_views: &mut ProjectedViewsV1<'_>,
    operations: &mut Vec<ProductionRankedOperationV1>,
    sources: &mut Vec<ProjectedAccessSourceV1>,
    next_value: &mut u32,
    ranked_ir: &mut String,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    match value {
        SemanticRvalueKindV1::Use(operand) => project_operand_read(
            types,
            function,
            block_index,
            bounds_checks,
            operand,
            source,
            constants,
            local_contracts,
            guarded_accesses,
            guarded_sites,
            projected_views,
            operations,
            sources,
            next_value,
            ranked_ir,
        ),
        SemanticRvalueKindV1::Unary { operand, .. }
        | SemanticRvalueKindV1::Cast { operand, .. } => project_operand_read(
            types,
            function,
            block_index,
            bounds_checks,
            operand,
            source,
            constants,
            local_contracts,
            guarded_accesses,
            guarded_sites,
            projected_views,
            operations,
            sources,
            next_value,
            ranked_ir,
        ),
        SemanticRvalueKindV1::Binary { left, right, .. } => {
            project_operand_read(
                types,
                function,
                block_index,
                bounds_checks,
                left,
                source,
                constants,
                local_contracts,
                guarded_accesses,
                guarded_sites,
                projected_views,
                operations,
                sources,
                next_value,
                ranked_ir,
            )?;
            project_operand_read(
                types,
                function,
                block_index,
                bounds_checks,
                right,
                source,
                constants,
                local_contracts,
                guarded_accesses,
                guarded_sites,
                projected_views,
                operations,
                sources,
                next_value,
                ranked_ir,
            )
        }
        SemanticRvalueKindV1::CheckedBinary(_) | SemanticRvalueKindV1::UncheckedBinary(_) => {
            let (left, right) = match value {
                SemanticRvalueKindV1::CheckedBinary(checked) => (checked.left(), checked.right()),
                SemanticRvalueKindV1::UncheckedBinary(unchecked) => {
                    (unchecked.left(), unchecked.right())
                }
                _ => unreachable!("outer pattern selects a two-operand arithmetic rvalue"),
            };
            project_operand_read(
                types,
                function,
                block_index,
                bounds_checks,
                left,
                source,
                constants,
                local_contracts,
                guarded_accesses,
                guarded_sites,
                projected_views,
                operations,
                sources,
                next_value,
                ranked_ir,
            )?;
            project_operand_read(
                types,
                function,
                block_index,
                bounds_checks,
                right,
                source,
                constants,
                local_contracts,
                guarded_accesses,
                guarded_sites,
                projected_views,
                operations,
                sources,
                next_value,
                ranked_ir,
            )
        }
        SemanticRvalueKindV1::Aggregate(aggregate) => {
            for operand in aggregate.operands() {
                project_operand_read(
                    types,
                    function,
                    block_index,
                    bounds_checks,
                    operand,
                    source,
                    constants,
                    local_contracts,
                    guarded_accesses,
                    guarded_sites,
                    projected_views,
                    operations,
                    sources,
                    next_value,
                    ranked_ir,
                )?;
            }
            Ok(())
        }
        SemanticRvalueKindV1::Load(load) => project_place_access_with_atomic(
            types,
            function,
            block_index,
            bounds_checks,
            load.source(),
            if load.atomic().is_some() {
                AccessKindAttr::AtomicRead
            } else {
                AccessKindAttr::Read
            },
            load.atomic(),
            PlaceAccessRequirementV1::ExplicitMemory,
            source,
            constants,
            local_contracts,
            guarded_accesses,
            guarded_sites,
            projected_views,
            operations,
            sources,
            next_value,
            ranked_ir,
        ),
        SemanticRvalueKindV1::AddressOf { place, .. }
        | SemanticRvalueKindV1::Borrow { place, .. } => {
            project_address_formation(types, function, place, local_contracts)
        }
        SemanticRvalueKindV1::Length(place) | SemanticRvalueKindV1::Discriminant(place) => {
            project_place_access(
                types,
                function,
                block_index,
                bounds_checks,
                place,
                AccessKindAttr::Read,
                PlaceAccessRequirementV1::IfMemory,
                source,
                constants,
                local_contracts,
                guarded_accesses,
                guarded_sites,
                projected_views,
                operations,
                sources,
                next_value,
                ranked_ir,
            )
        }
    }
}

fn project_address_formation(
    types: &[fe2o3_mir_model::semantic_mir_v1::SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    place: &SemanticPlaceV1,
    local_contracts: &ProjectionLocalContractsV1,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    let local_index = place.local().index() as usize;
    let local = function.locals().get(local_index).ok_or(
        ProductionRankedProjectionErrorV1::Unsupported(
            "an address formation with an out-of-range local",
        ),
    )?;
    if place.projections().is_empty() {
        // Taking the address of a MIR local creates a private address and does
        // not observe the value stored in that local.
        return Ok(());
    }

    let mut current = local.ty();
    let mut crossed_dereference = false;
    for (projection_index, projection) in place.projections().iter().enumerate() {
        match projection.kind() {
            SemanticProjectionKindV1::Dereference if projection_index == 0 => {
                let ty = types.get(current.index() as usize).ok_or(
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "an address formation with an out-of-range type",
                    ),
                )?;
                let SemanticTypeShapeV1::Pointer(pointer) = ty.shape() else {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "an address formation whose dereferenced type is not a pointer",
                    ));
                };
                memory_space(pointer.address_space())?;
                crossed_dereference = true;
            }
            SemanticProjectionKindV1::Field(_)
            | SemanticProjectionKindV1::Downcast(_)
            | SemanticProjectionKindV1::OpaqueCast
            | SemanticProjectionKindV1::Subtype => {}
            SemanticProjectionKindV1::Dereference
            | SemanticProjectionKindV1::Index(_)
            | SemanticProjectionKindV1::ConstantIndex { .. }
            | SemanticProjectionKindV1::Subslice { .. } => {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "indexed address formation before exact bounds-only projection",
                ));
            }
        }
        current = projection.result_type();
    }

    if crossed_dereference {
        debug_assert_eq!(reborrowed_allocation_local_v1(place), Some(place.local()));
        let has_allocation_contract = local_contracts
            .allocations
            .get(local_index)
            .copied()
            .flatten()
            .is_some();
        let has_private_provenance = matches!(
            local_contracts
                .allocation_provenance
                .get(local_index)
                .copied()
                .flatten(),
            Some(LocalAllocationProvenanceV1::Private(_))
        );
        if !has_allocation_contract && !has_private_provenance {
            return Err(
                ProductionRankedProjectionErrorV1::MissingAllocationProvenance {
                    local: place.local().index(),
                    projections: place.projections().len(),
                    ty: local.ty().index(),
                },
            );
        }
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn project_operand_read(
    types: &[fe2o3_mir_model::semantic_mir_v1::SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    block_index: usize,
    bounds_checks: &[ProjectedBoundsCheckV1],
    operand: &SemanticOperandV1,
    source: SemanticSourceProvenanceV1,
    constants: &[Option<u64>],
    local_contracts: &ProjectionLocalContractsV1,
    guarded_accesses: &[GuardedRankedAccessV1],
    guarded_sites: &mut Vec<GuardedAccessSiteV1>,
    projected_views: &mut ProjectedViewsV1<'_>,
    operations: &mut Vec<ProductionRankedOperationV1>,
    sources: &mut Vec<ProjectedAccessSourceV1>,
    next_value: &mut u32,
    ranked_ir: &mut String,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    match operand {
        SemanticOperandV1::Copy(place) | SemanticOperandV1::Move(place) => project_place_access(
            types,
            function,
            block_index,
            bounds_checks,
            place,
            AccessKindAttr::Read,
            PlaceAccessRequirementV1::IfMemory,
            source,
            constants,
            local_contracts,
            guarded_accesses,
            guarded_sites,
            projected_views,
            operations,
            sources,
            next_value,
            ranked_ir,
        ),
        SemanticOperandV1::Constant(_) => Ok(()),
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum PlaceAccessRequirementV1 {
    IfMemory,
    ExplicitMemory,
}

#[derive(Clone, Copy)]
enum ProjectedIndexV1 {
    Constant(u64),
    Dynamic(ProductionRankedValueV1),
}

fn projected_bounds_check(
    checks: &[ProjectedBoundsCheckV1],
    block_index: usize,
    extent_source: ProjectedBoundsExtentSourceV1,
    index_local: SemanticLocalIdV1,
) -> Result<ProjectedBoundsCheckV1, ProductionRankedProjectionErrorV1> {
    let mut matches = checks.iter().copied().filter(|check| {
        check.access_block == block_index
            && check.extent_source == extent_source
            && check.index_local == index_local
    });
    let check = matches
        .next()
        .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
            "a dynamic slice access without its exact Rust bounds-check predecessor",
        ))?;
    if matches.next().is_some() {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "multiple Rust bounds checks authorize one dynamic slice access",
        ));
    }
    Ok(check)
}

#[allow(clippy::too_many_arguments)]
fn project_place_access(
    types: &[fe2o3_mir_model::semantic_mir_v1::SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    block_index: usize,
    bounds_checks: &[ProjectedBoundsCheckV1],
    place: &SemanticPlaceV1,
    access: AccessKindAttr,
    requirement: PlaceAccessRequirementV1,
    source: SemanticSourceProvenanceV1,
    constants: &[Option<u64>],
    local_contracts: &ProjectionLocalContractsV1,
    guarded_accesses: &[GuardedRankedAccessV1],
    guarded_sites: &mut Vec<GuardedAccessSiteV1>,
    projected_views: &mut ProjectedViewsV1<'_>,
    operations: &mut Vec<ProductionRankedOperationV1>,
    sources: &mut Vec<ProjectedAccessSourceV1>,
    next_value: &mut u32,
    ranked_ir: &mut String,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    project_place_access_with_atomic(
        types,
        function,
        block_index,
        bounds_checks,
        place,
        access,
        None,
        requirement,
        source,
        constants,
        local_contracts,
        guarded_accesses,
        guarded_sites,
        projected_views,
        operations,
        sources,
        next_value,
        ranked_ir,
    )
}

#[allow(clippy::too_many_arguments)]
fn project_place_access_with_atomic(
    types: &[fe2o3_mir_model::semantic_mir_v1::SemanticTypeDeclV1],
    function: &SemanticFunctionDeclV1,
    block_index: usize,
    bounds_checks: &[ProjectedBoundsCheckV1],
    place: &SemanticPlaceV1,
    access: AccessKindAttr,
    atomic: Option<SemanticAtomicAccessV1>,
    requirement: PlaceAccessRequirementV1,
    source: SemanticSourceProvenanceV1,
    constants: &[Option<u64>],
    local_contracts: &ProjectionLocalContractsV1,
    guarded_accesses: &[GuardedRankedAccessV1],
    guarded_sites: &mut Vec<GuardedAccessSiteV1>,
    projected_views: &mut ProjectedViewsV1<'_>,
    operations: &mut Vec<ProductionRankedOperationV1>,
    sources: &mut Vec<ProjectedAccessSourceV1>,
    next_value: &mut u32,
    ranked_ir: &mut String,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    if access.is_atomic() != atomic.is_some() {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "an atomic access whose ordering/scope contract is missing or attached to a non-atomic access",
        ));
    }
    if let Some(origin) =
        checked_reference_origin(place, block_index, &local_contracts.checked_references)?
    {
        match origin {
            CheckedReferenceSourceV1::GuardedAccess(origin) => {
                if atomic.is_some() {
                    return Err(ProductionRankedProjectionErrorV1::Incomplete(
                        "an atomic access through a checked disjoint reference before exact atomic capability projection",
                    ));
                }
                let mut guarded = guarded_accesses.get(origin).cloned().ok_or(
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "a checked disjoint reference whose access origin is out of range",
                    ),
                )?;
                guarded.access = access;
                guarded.source = source;
                guarded_sites.try_reserve(1).map_err(|_| {
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "checked disjoint access-site storage cannot be reserved",
                    )
                })?;
                guarded_sites.push(GuardedAccessSiteV1 {
                    insertion_operation: operations.len(),
                    access: guarded,
                });
                return Ok(());
            }
            CheckedReferenceSourceV1::ProjectedSharedBorrow
                if atomic.is_none() && access == AccessKindAttr::Read =>
            {
                return Ok(());
            }
            CheckedReferenceSourceV1::ProjectedSharedBorrow => {
                return Err(ProductionRankedProjectionErrorV1::Unsupported(
                    "a projected shared reference used for a non-read memory effect",
                ));
            }
        }
    }
    let private_borrow = projected_views.scalar_private_borrow(
        types,
        function,
        block_index,
        place,
        access,
        atomic,
        local_contracts,
    )?;
    let allocation_local = private_borrow.unwrap_or_else(|| place.local());
    let Some(local) = function.locals().get(allocation_local.index() as usize) else {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "an indexed place with an out-of-range local",
        ));
    };
    let mut current = local.ty();
    let mut shape = Vec::new();
    let mut dynamic_extents = Vec::new();
    let mut indices = Vec::new();
    let mut comparisons = Vec::new();
    let mut crosses_memory_boundary = false;
    let mut dereferenced_memory_space = None;
    let mut canonical_slice = None;
    // Only a freshly checked source occurrence can use its original private
    // scalar allocation here. The access's source site remains unchanged.
    let projections = if private_borrow.is_some() {
        &[][..]
    } else {
        place.projections()
    };
    for projection in projections {
        match projection.kind() {
            SemanticProjectionKindV1::Dereference => {
                crosses_memory_boundary = true;
                let Some(ty) = types.get(current.index() as usize) else {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "an indexed place with an out-of-range type",
                    ));
                };
                let SemanticTypeShapeV1::Pointer(pointer) = ty.shape() else {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "a dereference whose semantic type is not a pointer",
                    ));
                };
                dereferenced_memory_space = Some(memory_space(pointer.address_space())?);
                current = pointer.pointee();
            }
            SemanticProjectionKindV1::Index(index) => {
                crosses_memory_boundary = true;
                if shape.len() == MAX_RANKED_MEMORY_RANK {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "an indexed place exceeding the ranked-memory rank limit",
                    ));
                }
                match types.get(current.index() as usize).map(|ty| ty.shape()) {
                    Some(SemanticTypeShapeV1::Array { length, element }) => {
                        shape.push(*length);
                        if let Some(value) =
                            constants.get(index.index() as usize).copied().flatten()
                        {
                            indices.push(ProjectedIndexV1::Constant(value));
                        } else {
                            if *length == 0
                                || !matches!(
                                    types[element.index() as usize].shape(),
                                    SemanticTypeShapeV1::Scalar(_)
                                )
                                || access != AccessKindAttr::Read
                                || atomic.is_some()
                                || place.projections().len() != 1
                                || local_contracts
                                    .immutable_locals
                                    .get(place.local().index() as usize)
                                    != Some(&true)
                            {
                                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                                    "a dynamic array index requires an immutable local scalar array",
                                ));
                            }
                            let check = projected_bounds_check(
                                bounds_checks,
                                block_index,
                                ProjectedBoundsExtentSourceV1::FixedArray(*length),
                                index,
                            )?;
                            indices.push(ProjectedIndexV1::Dynamic(check.index));
                            comparisons.push((check.index, check.extent));
                        }
                    }
                    Some(SemanticTypeShapeV1::Slice { .. }) => {
                        let mut candidates = bounds_checks.iter().copied().filter(|check| {
                            check.access_block == block_index
                                && check.index_local == index
                                && !matches!(
                                    check.extent_source,
                                    ProjectedBoundsExtentSourceV1::FixedArray(_)
                                )
                        });
                        let candidate = candidates.next().ok_or(
                            ProductionRankedProjectionErrorV1::Incomplete(
                                "a dynamic slice access without its exact Rust bounds-check predecessor",
                            ),
                        )?;
                        if candidates.next().is_some() {
                            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                                "multiple Rust bounds checks authorize one dynamic slice access",
                            ));
                        }
                        let needs_canonical = candidate.extent_source
                            == ProjectedBoundsExtentSourceV1::CanonicalSlice
                            || place.projections().iter().any(|projection| {
                                matches!(projection.kind(), SemanticProjectionKindV1::Field(_))
                            })
                            || local_contracts
                                .allocations
                                .get(place.local().index() as usize)
                                .is_none_or(Option::is_none);
                        let check = if needs_canonical {
                            if access != AccessKindAttr::Read
                                || atomic.is_some()
                                || !shape.is_empty()
                                || canonical_slice.is_some()
                            {
                                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                                    "canonical slice projection requires one ordinary scalar read",
                                ));
                            }
                            canonical_slice = Some(projected_views.slice_input(
                                candidate,
                                sources,
                                guarded_sites,
                                operations,
                            )?);
                            candidate
                        } else {
                            projected_bounds_check(
                                bounds_checks,
                                block_index,
                                ProjectedBoundsExtentSourceV1::Slice(place.local()),
                                index,
                            )?
                        };
                        shape.push(DYNAMIC_EXTENT);
                        dynamic_extents.push(check.extent);
                        indices.push(ProjectedIndexV1::Dynamic(check.index));
                        comparisons.push((check.index, check.extent));
                    }
                    _ => {
                        return Err(ProductionRankedProjectionErrorV1::Unsupported(
                            "an index projection whose base is not an array or slice",
                        ));
                    }
                }
                current = projection.result_type();
            }
            SemanticProjectionKindV1::ConstantIndex {
                offset, from_end, ..
            } => {
                crosses_memory_boundary = true;
                if shape.len() == MAX_RANKED_MEMORY_RANK {
                    return Err(ProductionRankedProjectionErrorV1::Unsupported(
                        "an indexed place exceeding the ranked-memory rank limit",
                    ));
                }
                let extent = static_array_extent(types, current)?;
                let value = if from_end {
                    extent.checked_sub(offset).ok_or(
                        ProductionRankedProjectionErrorV1::Unsupported(
                            "a from-end constant index larger than its static extent",
                        ),
                    )?
                } else {
                    offset
                };
                shape.push(extent);
                indices.push(ProjectedIndexV1::Constant(value));
                current = projection.result_type();
            }
            SemanticProjectionKindV1::Field(_)
            | SemanticProjectionKindV1::Downcast(_)
            | SemanticProjectionKindV1::OpaqueCast
            | SemanticProjectionKindV1::Subtype => current = projection.result_type(),
            SemanticProjectionKindV1::Subslice { .. } => {
                return Err(ProductionRankedProjectionErrorV1::Incomplete(
                    "an indexed place containing a subslice projection",
                ));
            }
        }
    }
    if dereferenced_memory_space.is_none()
        && let SemanticLocalRoleV1::Argument(argument) = local.role()
        && function
            .abi()
            .source_argument_ownership()
            .get(argument as usize)
            == Some(&SemanticSourceArgumentOwnershipV1::ByValue)
    {
        if requirement == PlaceAccessRequirementV1::ExplicitMemory {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "an explicit memory operation targets a by-value argument component",
            ));
        }
        return Ok(());
    }
    if indices.is_empty() && crosses_memory_boundary {
        let singleton = matches!(dereferenced_memory_space, Some(MemorySpaceAttr::Global))
            && local_contracts
                .allocations
                .get(place.local().index() as usize)
                .copied()
                .flatten()
                .is_some_and(|contract| contract.singleton_object);
        if !singleton {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a dereferenced memory access without a ranked index projection",
            ));
        }
        shape.push(1);
        indices.push(ProjectedIndexV1::Constant(0));
    }
    if indices.is_empty()
        && atomic.is_none()
        && (private_borrow.is_some()
            || (requirement == PlaceAccessRequirementV1::ExplicitMemory
                && place.projections().is_empty()
                && place.ty() == local.ty()
                && !local.role().is_entry_argument()
                && projected_views.scalar_private_singleton(place.local())?))
    {
        shape.push(1);
        indices.push(ProjectedIndexV1::Constant(0));
    }
    if indices.is_empty() {
        if requirement == PlaceAccessRequirementV1::ExplicitMemory {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "an explicit memory operation without a ranked index projection",
            ));
        }
        return Ok(());
    }
    reserve_projected_access(operations, sources, indices.len() + 2)?;
    let element_width = type_width(types, place.ty())?;
    let memory_space = if let Some(memory_space) = dereferenced_memory_space {
        memory_space
    } else if matches!(local.role(), SemanticLocalRoleV1::Argument(_)) {
        MemorySpaceAttr::Global
    } else {
        MemorySpaceAttr::Private
    };
    if memory_space == MemorySpaceAttr::Workgroup {
        return Err(ProductionRankedProjectionErrorV1::Incomplete(
            "workgroup memory before exact semantic CFG projection is available",
        ));
    }
    let allocation_contract = if let Some((input, _)) = &canonical_slice {
        if memory_space != MemorySpaceAttr::Global || input.element_width != element_width {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "canonical slice read type or address space changed",
            ));
        }
        let allocation_origin = u64::from(input.source_argument) + 1;
        let established = input.direct_local.and_then(|local| {
            local_contracts
                .allocations
                .get(local.index() as usize)
                .copied()
                .flatten()
        });
        if established.is_some_and(|contract| contract.allocation_origin != allocation_origin) {
            return Err(ProductionRankedProjectionErrorV1::Unsupported(
                "canonical slice input disagrees with its source allocation",
            ));
        }
        AllocationContractV1 {
            allocation_origin,
            noalias_class: established.map_or(0, |contract| contract.noalias_class),
            writable: false,
            singleton_object: false,
        }
    } else {
        match memory_space {
            MemorySpaceAttr::Global => local_contracts
                .allocations
                .get(place.local().index() as usize)
                .copied()
                .flatten()
                .ok_or(ProductionRankedProjectionErrorV1::Incomplete(
                    "an indexed global allocation lacks authenticated Rust pointer provenance",
                ))?,
            MemorySpaceAttr::Private => {
                let identity = u64::from(allocation_local.index()).checked_add(1).ok_or(
                    ProductionRankedProjectionErrorV1::Unsupported(
                        "a private allocation identity overflowed",
                    ),
                )?;
                let identity = PRIVATE_ALLOCATION_ORIGIN_TAG_V1
                    .checked_add(identity)
                    .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                        "a private allocation identity overflowed",
                    ))?;
                AllocationContractV1 {
                    allocation_origin: identity,
                    noalias_class: identity,
                    writable: true,
                    singleton_object: false,
                }
            }
            MemorySpaceAttr::Workgroup => unreachable!(),
        }
    };
    if access.writes_memory() && !allocation_contract.writable {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "a write is rooted in a read-only Rust allocation",
        ));
    }
    // A wrapper local may contain several same-typed slices. The checked
    // per-access view does not inherit that local's legacy cache entry.
    let mut fresh_view = None;
    let view_slot = if canonical_slice.is_some() {
        &mut fresh_view
    } else {
        projected_views
            .get_mut(allocation_local.index() as usize)
            .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
                "an indexed place outside the ranked view table",
            ))?
    };
    let view_id = if let Some(view) = view_slot {
        if view.element_width != element_width
            || view.writable != allocation_contract.writable
            || view.shape != shape
            || view.dynamic_extents != dynamic_extents
            || view.memory_space != memory_space
            || view.allocation_origin != allocation_contract.allocation_origin
            || view.noalias_class != allocation_contract.noalias_class
        {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "one semantic allocation used through inconsistent ranked views",
            ));
        }
        view.result
    } else {
        let view_id = next_value_id(next_value)?;
        operations.push(ProductionRankedOperationV1::ViewInSpace {
            result: view_id,
            element_width,
            writable: allocation_contract.writable,
            shape: shape.clone(),
            dynamic_extents: dynamic_extents.clone(),
            memory_space,
            allocation_origin: allocation_contract.allocation_origin,
            noalias_class: allocation_contract.noalias_class,
        });
        push_ranked_ir(
            ranked_ir,
            &format!(
                "  %{} = kernel.ranked_view <{}, {}, {:?}, {:?}, origin={}, noalias={}>\n",
                view_id.get(),
                element_width,
                allocation_contract.writable,
                shape,
                memory_space,
                allocation_contract.allocation_origin,
                allocation_contract.noalias_class,
            ),
        )?;
        *view_slot = Some(ProjectedViewV1 {
            result: view_id,
            element_width,
            writable: allocation_contract.writable,
            shape: shape.clone(),
            dynamic_extents: dynamic_extents.clone(),
            memory_space,
            allocation_origin: allocation_contract.allocation_origin,
            noalias_class: allocation_contract.noalias_class,
        });
        view_id
    };
    if let Some((_, ordinal)) = canonical_slice {
        projected_views.retain_query(ordinal, view_id)?;
    }
    let mut ranked_indices = Vec::with_capacity(indices.len());
    for value in indices {
        match value {
            ProjectedIndexV1::Constant(value) => {
                let index_id = next_value_id(next_value)?;
                operations.push(ProductionRankedOperationV1::IndexConstant {
                    result: index_id,
                    value,
                });
                push_ranked_ir(
                    ranked_ir,
                    &format!("  %{} = kernel.index_constant {}\n", index_id.get(), value,),
                )?;
                ranked_indices.push(ProductionRankedValueV1::Local(index_id));
            }
            ProjectedIndexV1::Dynamic(value) => ranked_indices.push(value),
        }
    }
    if !comparisons.is_empty() {
        if atomic.is_some() {
            return Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a dynamically bounds-checked atomic access before guarded atomic projection",
            ));
        }
        guarded_sites.try_reserve(1).map_err(|_| {
            ProductionRankedProjectionErrorV1::Unsupported(
                "Rust bounds-checked access-site storage cannot be reserved",
            )
        })?;
        guarded_sites.push(GuardedAccessSiteV1 {
            insertion_operation: operations.len(),
            access: GuardedRankedAccessV1 {
                view: view_id,
                indices: ranked_indices,
                checked_success: None,
                comparisons,
                access,
                memory_space,
                source,
                output_extent: None,
                semantic_site: None,
            },
        });
        return Ok(());
    }
    let operation = operations.len();
    if let Some(atomic) = atomic {
        operations.push(ProductionRankedOperationV1::AtomicAccess {
            kind: access,
            ordering: atomic_ordering_v1(atomic.ordering()),
            scope: atomic_scope_v1(atomic.scope()),
            view: ProductionRankedValueV1::Local(view_id),
            indices: ranked_indices.clone(),
        });
    } else {
        operations.push(ProductionRankedOperationV1::Access {
            kind: access,
            view: ProductionRankedValueV1::Local(view_id),
            indices: ranked_indices.clone(),
        });
    }
    push_ranked_ir(
        ranked_ir,
        &format!(
            "  kernel.{} {:?} %{}[{}]\n",
            if atomic.is_some() {
                "atomic_access"
            } else {
                "access"
            },
            access,
            view_id.get(),
            ranked_indices
                .iter()
                .map(|value| match value {
                    ProductionRankedValueV1::Local(identity) => format!("%{}", identity.get()),
                    ProductionRankedValueV1::Argument(argument) => format!("%arg{argument}"),
                    ProductionRankedValueV1::BlockArgument { block, argument } => {
                        format!("%bb{block}_arg{argument}")
                    }
                })
                .collect::<Vec<_>>()
                .join(", "),
        ),
    )?;
    sources.push(ProjectedAccessSourceV1 {
        block: 0,
        operation,
        access,
        memory_space,
        source,
        output_extent: None,
        semantic_site: None,
    });
    Ok(())
}

const fn atomic_ordering_v1(ordering: SemanticAtomicOrderingV1) -> AtomicOrderingAttr {
    match ordering {
        SemanticAtomicOrderingV1::Relaxed => AtomicOrderingAttr::Relaxed,
        SemanticAtomicOrderingV1::Release => AtomicOrderingAttr::Release,
        SemanticAtomicOrderingV1::Acquire => AtomicOrderingAttr::Acquire,
        SemanticAtomicOrderingV1::AcquireRelease => AtomicOrderingAttr::AcquireRelease,
        SemanticAtomicOrderingV1::SequentiallyConsistent => {
            AtomicOrderingAttr::SequentiallyConsistent
        }
    }
}

const fn atomic_scope_v1(scope: SemanticAtomicScopeV1) -> AtomicScopeAttr {
    match scope {
        SemanticAtomicScopeV1::SingleThread => AtomicScopeAttr::SingleThread,
        SemanticAtomicScopeV1::Workgroup => AtomicScopeAttr::Workgroup,
        SemanticAtomicScopeV1::Agent => AtomicScopeAttr::Agent,
        SemanticAtomicScopeV1::Device => AtomicScopeAttr::Device,
        SemanticAtomicScopeV1::System => AtomicScopeAttr::System,
    }
}

fn reserve_projected_access(
    operations: &mut Vec<ProductionRankedOperationV1>,
    sources: &mut Vec<ProjectedAccessSourceV1>,
    additional_operations: usize,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    let actual = operations.len().checked_add(additional_operations).ok_or(
        ProductionRankedProjectionErrorV1::Unsupported(
            "a semantic statement projection with overflowing operation work",
        ),
    )?;
    if actual > MAX_PROJECTED_OPERATIONS_V1 {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "a semantic statement projection exceeding the ranked operation limit",
        ));
    }
    operations.try_reserve(additional_operations).map_err(|_| {
        ProductionRankedProjectionErrorV1::Unsupported(
            "a semantic statement projection whose operation storage cannot be reserved",
        )
    })?;
    sources.try_reserve(1).map_err(|_| {
        ProductionRankedProjectionErrorV1::Unsupported(
            "a semantic statement projection whose source storage cannot be reserved",
        )
    })
}

fn push_ranked_ir(
    ranked_ir: &mut String,
    fragment: &str,
) -> Result<(), ProductionRankedProjectionErrorV1> {
    let actual = ranked_ir.len().checked_add(fragment.len()).ok_or(
        ProductionRankedProjectionErrorV1::Unsupported(
            "a semantic statement projection with overflowing diagnostic text",
        ),
    )?;
    if actual > MAX_PROJECTED_RANKED_IR_BYTES_V1 {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "a semantic statement projection exceeding the diagnostic text limit",
        ));
    }
    ranked_ir.try_reserve(fragment.len()).map_err(|_| {
        ProductionRankedProjectionErrorV1::Unsupported(
            "a semantic statement projection whose diagnostic storage cannot be reserved",
        )
    })?;
    ranked_ir.push_str(fragment);
    Ok(())
}

fn static_array_extent(
    types: &[fe2o3_mir_model::semantic_mir_v1::SemanticTypeDeclV1],
    ty: SemanticTypeIdV1,
) -> Result<u64, ProductionRankedProjectionErrorV1> {
    match types.get(ty.index() as usize).map(|ty| ty.shape()) {
        Some(SemanticTypeShapeV1::Array { length, .. }) => Ok(*length),
        Some(SemanticTypeShapeV1::Slice { .. }) => {
            Err(ProductionRankedProjectionErrorV1::Incomplete(
                "a slice access before dynamic extent projection is available",
            ))
        }
        _ => Err(ProductionRankedProjectionErrorV1::Unsupported(
            "an index projection whose base is not an array or slice",
        )),
    }
}

fn memory_space(address_space: u32) -> Result<MemorySpaceAttr, ProductionRankedProjectionErrorV1> {
    match address_space {
        0 | 1 | 4 => Ok(MemorySpaceAttr::Global),
        3 => Ok(MemorySpaceAttr::Workgroup),
        5 => Ok(MemorySpaceAttr::Private),
        _ => Err(ProductionRankedProjectionErrorV1::Unsupported(
            "a pointer address space outside the generic memory model",
        )),
    }
}

fn type_width(
    types: &[fe2o3_mir_model::semantic_mir_v1::SemanticTypeDeclV1],
    ty: SemanticTypeIdV1,
) -> Result<u32, ProductionRankedProjectionErrorV1> {
    let bytes = types
        .get(ty.index() as usize)
        .and_then(|ty| ty.layout().size_bytes())
        .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
            "an indexed element without a static layout size",
        ))?;
    let bits = u32::try_from(bytes.checked_mul(8).ok_or(
        ProductionRankedProjectionErrorV1::Unsupported("an overflowing element width"),
    )?)
    .map_err(|_| ProductionRankedProjectionErrorV1::Unsupported("an overflowing element width"))?;
    if !SUPPORTED_ELEMENT_WIDTHS.contains(&bits) {
        return Err(ProductionRankedProjectionErrorV1::Unsupported(
            "an element width outside the ranked-memory dialect",
        ));
    }
    Ok(bits)
}

fn next_value_id(
    next: &mut u32,
) -> Result<ProductionRankedValueIdV1, ProductionRankedProjectionErrorV1> {
    let value = *next;
    *next = next
        .checked_add(1)
        .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
            "too many ranked SSA values",
        ))?;
    Ok(ProductionRankedValueIdV1::new(value))
}

fn function_name(
    function: &SemanticFunctionDeclV1,
) -> Result<&str, ProductionRankedProjectionErrorV1> {
    let symbol = function
        .kernel_entry()
        .ok_or(ProductionRankedProjectionErrorV1::Unsupported(
            "a kernel root without a kernel export",
        ))?
        .export_symbol()
        .as_bytes();
    std::str::from_utf8(symbol).map_err(|_| {
        ProductionRankedProjectionErrorV1::Unsupported("a non-UTF-8 kernel export symbol")
    })
}

fn source_label(source: SemanticSourceProvenanceV1) -> String {
    let Some(origin) = source.call_site().or_else(|| source.expansion()) else {
        return "Rust source location unavailable".to_owned();
    };
    let (line, column) = origin.start_coordinate();
    let digest = origin.file();
    format!(
        "Rust source {}:{}:{}",
        &crate::encode_hex(digest.as_bytes())[..12],
        line,
        column,
    )
}

fn indent_ir(ir: &str) -> String {
    ir.lines()
        .map(|line| format!("    {line}"))
        .collect::<Vec<_>>()
        .join("\n")
}

