    #[test]
    fn address_escaped_pipeline_index_cache_is_not_authority() {
        let types = assertion_proof_types();
        let function = address_escaped_guard_function(false);
        let cached = ProductionRankedValueV1::Argument(7);
        let mut index_values = vec![None; function.locals().len()];
        index_values[1] = Some(ProjectedDisjointIndexV1 {
            value: cached,
            mapping: SemanticDisjointIndexSpaceV1::Index1d,
            precondition: None,
            availability: None,
        });
        let mut runtime_arguments = vec![None; function.locals().len()];
        let mut next_argument = 8;
        let mut operations = Vec::new();
        let mut next_value = 0;
        let mut projector = PipelineScalarProjectorV1 {
            types: &types,
            function: &function,
            index_values: &index_values,
            runtime_index_arguments: &mut runtime_arguments,
            next_runtime_argument: &mut next_argument,
            uniform_inductions: &[],
            entry_operations: &mut operations,
            next_value: &mut next_value,
            assertion_proofs: SemanticAssertProofsV1::new(&types, &function).unwrap(),
            work: 0,
        };
        assert_incomplete(
            projector.project_root(0, &typed_operand(1, U64_TYPE)),
            "a pipeline scalar local has address-escaped value semantics",
        );
    }

    #[derive(Clone, Copy)]
    enum MutatedGuardProofV1 {
        ZeroExclusion,
        StrictUpperBound,
    }

    #[derive(Clone, Copy)]
    enum MutatedGuardShapeV1 {
        Discriminant,
        ComparisonAlias,
    }

    fn mutated_guard_range_function(
        proof: MutatedGuardProofV1,
        shape: MutatedGuardShapeV1,
    ) -> (Vec<SemanticTypeDeclV1>, SemanticFunctionDeclV1) {
        let mut types = assertion_proof_types();
        let bool_pointer = SemanticTypeIdV1::from_index(types.len() as u32);
        types.push(SemanticTypeDeclV1::new(
            SemanticTypeIdentityV1::from_sha256(bytes(49)),
            SemanticLayoutIdentityV1::from_sha256(bytes(49)),
            SemanticTypeLayoutV1::new(Some(8), 8).unwrap(),
            SemanticTypeShapeV1::Pointer(
                SemanticPointerTypeV1::new(
                    BOOL_TYPE,
                    SemanticMutabilityV1::Mutable,
                    5,
                    64,
                    SemanticPointerMetadataV1::None,
                )
                .unwrap(),
            ),
        ));

        let (operation, compared_value) = match proof {
            MutatedGuardProofV1::ZeroExclusion => (SemanticBinaryOpV1::NotEqual, 0),
            MutatedGuardProofV1::StrictUpperBound => (SemanticBinaryOpV1::LessThan, 255),
        };
        let (guard_input, pointer_type, borrowed_place, stored_type, stored_value) = match shape {
            MutatedGuardShapeV1::Discriminant => (
                typed_operand(1, U64_TYPE),
                bool_pointer,
                typed_place(3, BOOL_TYPE),
                BOOL_TYPE,
                typed_constant(BOOL_TYPE, 1, 1),
            ),
            MutatedGuardShapeV1::ComparisonAlias => (
                typed_operand(2, U64_TYPE),
                U64_POINTER_TYPE,
                typed_place(2, U64_TYPE),
                U64_TYPE,
                typed_constant(U64_TYPE, 1, 8),
            ),
        };
        let through_pointer = SemanticPlaceV1::new(
            SemanticLocalIdV1::from_index(4),
            vec![
                SemanticProjectionV1::new(SemanticProjectionKindV1::Dereference, stored_type)
                    .unwrap(),
            ],
            stored_type,
        )
        .unwrap();
        let borrow = typed_assignment(
            4,
            pointer_type,
            SemanticRvalueKindV1::Borrow {
                kind: SemanticBorrowKindV1::Mutable,
                place: borrowed_place,
            },
        );
        let store = statement(SemanticStatementKindV1::Store(SemanticMemoryStoreV1::new(
            through_pointer,
            stored_value,
            SemanticVolatilityV1::NonVolatile,
            None,
        )));
        let comparison = typed_assignment(
            3,
            BOOL_TYPE,
            SemanticRvalueKindV1::Binary {
                operation,
                left: guard_input,
                right: typed_constant(U64_TYPE, compared_value, 8),
            },
        );
        let statements = match shape {
            MutatedGuardShapeV1::Discriminant => vec![comparison, borrow, store],
            MutatedGuardShapeV1::ComparisonAlias => vec![
                typed_assignment(
                    2,
                    U64_TYPE,
                    SemanticRvalueKindV1::Use(typed_operand(1, U64_TYPE)),
                ),
                borrow,
                store,
                comparison,
            ],
        };
        let function = projection_function_with_locals(
            vec![
                block(248, statements, zero_switch(3, BOOL_TYPE, 2, 1)),
                block(249, vec![], SemanticTerminatorKindV1::Return),
                block(250, vec![], SemanticTerminatorKindV1::Return),
            ],
            vec![
                local(248, U64_TYPE, SemanticLocalRoleV1::Return),
                local(249, U64_TYPE, SemanticLocalRoleV1::Argument(0)),
                local(250, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(251, BOOL_TYPE, SemanticLocalRoleV1::Temporary),
                local(252, pointer_type, SemanticLocalRoleV1::Temporary),
            ],
        );
        (types, function)
    }

    fn assert_mutated_guard_does_not_narrow_range(shape: MutatedGuardShapeV1) {
        for proof_kind in [
            MutatedGuardProofV1::ZeroExclusion,
            MutatedGuardProofV1::StrictUpperBound,
        ] {
            let (types, function) = mutated_guard_range_function(proof_kind, shape);
            let escaped = match shape {
                MutatedGuardShapeV1::Discriminant => 3,
                MutatedGuardShapeV1::ComparisonAlias => 2,
            };
            let mut proof = SemanticAssertProofsV1::new(&types, &function).unwrap();
            assert!(proof.address_escaped()[escaped]);
            assert_eq!(
                proof
                    .range_at_operand(&typed_operand(1, U64_TYPE), 1, 0)
                    .unwrap(),
                Some(UnsignedRangeProofV1 {
                    minimum: 0,
                    maximum: u128::from(u64::MAX),
                })
            );
        }
    }

    #[test]
    fn mutated_address_escaped_discriminants_do_not_prove_scalar_ranges() {
        assert_mutated_guard_does_not_narrow_range(MutatedGuardShapeV1::Discriminant);
    }

    #[test]
    fn mutated_address_escaped_comparison_aliases_do_not_prove_scalar_ranges() {
        assert_mutated_guard_does_not_narrow_range(MutatedGuardShapeV1::ComparisonAlias);
    }

    fn guarded_value_with_optional_loop_redefinition(redefine: bool) -> SemanticFunctionDeclV1 {
        let loop_statements = redefine
            .then(|| {
                vec![typed_assignment(
                    1,
                    U64_TYPE,
                    SemanticRvalueKindV1::Use(typed_constant(U64_TYPE, 0, 8)),
                )]
            })
            .unwrap_or_default();
        projection_function_with_locals(
            vec![
                block(185, vec![], zero_switch(1, U64_TYPE, 3, 1)),
                block(186, vec![], zero_switch(2, BOOL_TYPE, 4, 2)),
                block(
                    187,
                    loop_statements,
                    SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1)),
                ),
                block(188, vec![], SemanticTerminatorKindV1::Return),
                block(
                    189,
                    vec![typed_assignment(
                        3,
                        BOOL_TYPE,
                        SemanticRvalueKindV1::Binary {
                            operation: SemanticBinaryOpV1::Equal,
                            left: typed_operand(1, U64_TYPE),
                            right: typed_constant(U64_TYPE, 0, 8),
                        },
                    )],
                    SemanticTerminatorKindV1::Assert {
                        condition: typed_operand(3, BOOL_TYPE),
                        expected: false,
                        message: SemanticAssertMessageV1::DivisionByZero(typed_operand(
                            1, U64_TYPE,
                        )),
                        target: cfg_edge(SemanticEdgeRoleV1::AssertSuccess, 5),
                        unwind: SemanticUnwindActionV1::Unreachable,
                    },
                ),
                block(190, vec![], SemanticTerminatorKindV1::Return),
            ],
            vec![
                local(185, SCALAR_TYPE, SemanticLocalRoleV1::Return),
                local(186, U64_TYPE, SemanticLocalRoleV1::Argument(0)),
                local(187, BOOL_TYPE, SemanticLocalRoleV1::Argument(1)),
                local(188, BOOL_TYPE, SemanticLocalRoleV1::Temporary),
            ],
        )
    }

    #[test]
    fn nonzero_proof_checks_every_reachable_loop_backedge_for_redefinitions() {
        let types = assertion_proof_types();
        let stable = guarded_value_with_optional_loop_redefinition(false);
        assert!(SemanticAssertProofsV1::analyze(&types, &stable).unwrap()[4]);

        let redefined = guarded_value_with_optional_loop_redefinition(true);
        assert!(!SemanticAssertProofsV1::analyze(&types, &redefined).unwrap()[4]);
    }

    fn guarded_unsigned_subtract_function(guarded: bool) -> SemanticFunctionDeclV1 {
        let entry = if guarded {
            zero_switch(1, U64_TYPE, 3, 1)
        } else {
            SemanticTerminatorKindV1::Goto(cfg_edge(SemanticEdgeRoleV1::Goto, 1))
        };
        projection_function_with_locals(
            vec![
                block(191, vec![], entry),
                block(
                    192,
                    vec![typed_assignment(
                        2,
                        BOOL_TYPE,
                        SemanticRvalueKindV1::Binary {
                            operation: SemanticBinaryOpV1::LessThan,
                            left: typed_operand(1, U64_TYPE),
                            right: typed_constant(U64_TYPE, 1, 8),
                        },
                    )],
                    SemanticTerminatorKindV1::Assert {
                        condition: typed_operand(2, BOOL_TYPE),
                        expected: false,
                        message: SemanticAssertMessageV1::Overflow {
                            operation: SemanticBinaryOpV1::Subtract,
                            left: typed_operand(1, U64_TYPE),
                            right: typed_constant(U64_TYPE, 1, 8),
                        },
                        target: cfg_edge(SemanticEdgeRoleV1::AssertSuccess, 2),
                        unwind: SemanticUnwindActionV1::Unreachable,
                    },
                ),
                block(
                    193,
                    vec![
                        typed_assignment(
                            3,
                            U64_TYPE,
                            SemanticRvalueKindV1::Binary {
                                operation: SemanticBinaryOpV1::Subtract,
                                left: typed_operand(1, U64_TYPE),
                                right: typed_constant(U64_TYPE, 1, 8),
                            },
                        ),
                        typed_assignment(
                            4,
                            U64_TYPE,
                            SemanticRvalueKindV1::Binary {
                                operation: SemanticBinaryOpV1::Add,
                                left: typed_operand(3, U64_TYPE),
                                right: typed_constant(U64_TYPE, 1, 8),
                            },
                        ),
                        typed_assignment(
                            5,
                            BOOL_TYPE,
                            SemanticRvalueKindV1::Binary {
                                operation: SemanticBinaryOpV1::Equal,
                                left: typed_operand(4, U64_TYPE),
                                right: typed_constant(U64_TYPE, 0, 8),
                            },
                        ),
                    ],
                    SemanticTerminatorKindV1::Assert {
                        condition: typed_operand(5, BOOL_TYPE),
                        expected: false,
                        message: SemanticAssertMessageV1::DivisionByZero(typed_operand(
                            4, U64_TYPE,
                        )),
                        target: cfg_edge(SemanticEdgeRoleV1::AssertSuccess, 4),
                        unwind: SemanticUnwindActionV1::Unreachable,
                    },
                ),
                block(194, vec![], SemanticTerminatorKindV1::Return),
                block(195, vec![], SemanticTerminatorKindV1::Return),
            ],
            vec![
                local(191, SCALAR_TYPE, SemanticLocalRoleV1::Return),
                local(192, U64_TYPE, SemanticLocalRoleV1::Argument(0)),
                local(193, BOOL_TYPE, SemanticLocalRoleV1::Temporary),
                local(194, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(195, U64_TYPE, SemanticLocalRoleV1::Temporary),
                local(196, BOOL_TYPE, SemanticLocalRoleV1::Temporary),
            ],
        )
    }

    #[test]
    fn unsigned_subtraction_and_ordering_preserve_a_dominating_nonzero_contract() {
        let types = assertion_proof_types();
        let guarded =
            SemanticAssertProofsV1::analyze(&types, &guarded_unsigned_subtract_function(true))
                .unwrap();
        assert!(guarded[1]);
        assert!(guarded[2]);

        let unguarded =
            SemanticAssertProofsV1::analyze(&types, &guarded_unsigned_subtract_function(false))
                .unwrap();
        assert!(!unguarded[1]);
        assert!(!unguarded[2]);
    }

    #[test]
    fn unsigned_interval_subtraction_and_ordering_match_exhaustive_small_domains() {
        let ranges = (0_u128..=4)
            .flat_map(|minimum| {
                (minimum..=4).map(move |maximum| UnsignedRangeProofV1 { minimum, maximum })
            })
            .collect::<Vec<_>>();
        for left in &ranges {
            for right in &ranges {
                let subtraction = SemanticAssertProofsV1::<'_>::range_of_binary(
                    SemanticBinaryOpV1::Subtract,
                    Some(*left),
                    Some(*right),
                    Some(u128::from(u64::MAX)),
                )
                .unwrap();
                if left.minimum >= right.maximum {
                    let values = (left.minimum..=left.maximum)
                        .flat_map(|lhs| (right.minimum..=right.maximum).map(move |rhs| lhs - rhs))
                        .collect::<Vec<_>>();
                    assert_eq!(
                        subtraction,
                        Some(UnsignedRangeProofV1 {
                            minimum: *values.iter().min().unwrap(),
                            maximum: *values.iter().max().unwrap(),
                        })
                    );
                } else {
                    assert_eq!(subtraction, None);
                }

                for operation in [
                    SemanticBinaryOpV1::LessThan,
                    SemanticBinaryOpV1::LessOrEqual,
                    SemanticBinaryOpV1::GreaterThan,
                    SemanticBinaryOpV1::GreaterOrEqual,
                ] {
                    let values = (left.minimum..=left.maximum)
                        .flat_map(|lhs| {
                            (right.minimum..=right.maximum).map(move |rhs| match operation {
                                SemanticBinaryOpV1::LessThan => lhs < rhs,
                                SemanticBinaryOpV1::LessOrEqual => lhs <= rhs,
                                SemanticBinaryOpV1::GreaterThan => lhs > rhs,
                                SemanticBinaryOpV1::GreaterOrEqual => lhs >= rhs,
                                _ => unreachable!("fixture admits only ordering operations"),
                            })
                        })
                        .map(u128::from)
                        .collect::<Vec<_>>();
                    let actual = SemanticAssertProofsV1::<'_>::range_of_binary(
                        operation,
                        Some(*left),
                        Some(*right),
                        Some(1),
                    )
                    .unwrap()
                    .unwrap();
                    assert_eq!(actual.minimum, *values.iter().min().unwrap());
                    assert_eq!(actual.maximum, *values.iter().max().unwrap());
                }
            }
        }
    }

    #[test]
    fn unsigned_remainder_range_accepts_a_variable_nonzero_divisor() {
        let left = UnsignedRangeProofV1 {
            minimum: 0,
            maximum: 100,
        };
        let right = UnsignedRangeProofV1 {
            minimum: 2,
            maximum: 9,
        };
        assert_eq!(
            SemanticAssertProofsV1::<'_>::range_of_binary(
                SemanticBinaryOpV1::Remainder,
                Some(left),
                Some(right),
                Some(u128::from(u64::MAX)),
            )
            .unwrap(),
            Some(UnsignedRangeProofV1 {
                minimum: 0,
                maximum: 8,
            })
        );
        assert_eq!(
            SemanticAssertProofsV1::<'_>::range_of_binary(
                SemanticBinaryOpV1::Remainder,
                Some(left),
                Some(UnsignedRangeProofV1 {
                    minimum: 0,
                    maximum: 9,
                }),
                Some(u128::from(u64::MAX)),
            )
            .unwrap(),
            None
        );
    }

