    #[test]
    fn unsigned_cast_width_is_closed_to_exact_unsigned_type_maxima() {
        assert_eq!(unsigned_bit_width_for_maximum_v1(u8::MAX.into()), Some(8));
        assert_eq!(unsigned_bit_width_for_maximum_v1(u16::MAX.into()), Some(16));
        assert_eq!(unsigned_bit_width_for_maximum_v1(u32::MAX.into()), Some(32));
        assert_eq!(unsigned_bit_width_for_maximum_v1(u64::MAX.into()), Some(64));
        assert_eq!(unsigned_bit_width_for_maximum_v1(0), None);
        assert_eq!(unsigned_bit_width_for_maximum_v1(100), None);
        assert_eq!(unsigned_bit_width_for_maximum_v1(u128::MAX), None);
    }

    #[test]
    fn source_induction_width_rejects_u32_wrap_and_accepts_a_widened_u64_recurrence() {
        let wrapping = multi_block_induction_function(
            InductionCfgShape::Chain,
            SemanticLocalRoleV1::Argument(0),
            16,
        );
        assert_incomplete(
            project_test_inductions(&wrapping),
            "a compiler-derived source induction update may overflow its exact unsigned type",
        );

        let types = assertion_proof_types();
        let widened = widened_u64_induction_function(16);
        let (inductions, operations, _) =
            project_test_inductions_with_types(&types, &widened).unwrap();
        assert_eq!(inductions[0].source_progress.induction_type, U64_TYPE);
        assert_eq!(inductions[0].source_progress.step_value, 16);
        assert!(matches!(
            operations.last(),
            Some(ProductionRankedOperationV1::IndexUnsignedCast { bit_width: 32, .. })
        ));

        let unchecked = widened_u64_induction_function_with_latch(16, WidenedLatchKind::Unchecked);
        let (inductions, _, _) = project_test_inductions_with_types(&types, &unchecked).unwrap();
        assert_eq!(
            inductions[0].source_progress.update,
            ProjectedSourceInductionUpdateV1::Unchecked
        );

        let unchecked_wrapping = multi_block_unchecked_induction_function(
            InductionCfgShape::Chain,
            SemanticLocalRoleV1::Argument(0),
            16,
        );
        assert_incomplete(
            project_test_inductions(&unchecked_wrapping),
            "a compiler-derived source induction update may overflow its exact unsigned type",
        );
    }

